/* 平成19年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.h19.committeeSessions.push(...[{"id":"h19-20070227-6","meetingId":"h19-cm02","date":"2007年2月27日","dateIso":"2007-02-27","committee":"区民委員会","time":"午前１０時０２分～午後０時０１分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を41件抜き出しています。","topics":[{"id":"topic-01","title":"昨日に引き続きまして請願審査","agenda":"昨日に引き続きまして請願審査","exchanges":[{"speaker":"大沢委員","kind":"質問・要望","question":"昨日に引き続いてなんですが、都議会のほうで２８日にまた継続で審議が行われるということで、非常に重要な問題であります。したがって検討しました結果、自民党としましては趣旨採択の方向で持っていっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-001"},{"speaker":"堺委員","kind":"質問","question":"今、趣旨採択ということなんですけど、その際、意見書提出についてはどのようなご意見があったのでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-002"},{"speaker":"大沢委員","kind":"質問・要望","question":"意見書につきましては意見書なしということで、趣旨の採択をしていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"},{"speaker":"堺委員","kind":"意見","question":"紹介議員の大半が自民党ですし、両議員の関係はわかりませんが、大半が自民党ということから、自民党に所属している大沢議員から趣旨採択に意見書なしという趣旨のご発言がございましたので、私も大勢の意見がそれでまとまるならば、今回は趣旨採択で意見書なしということで、お取り扱いいただければいいのではないかと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-004"},{"speaker":"土井委員","kind":"意見","question":"昨日も同じような発言を、そういうような趣旨の発言をしておりますので、我々としてもこの固定資産税にかかわる活発な議論はしっかりとこれからも我々もしていくんだよと、あるいはこういうところもしてもらうんだよという意味を込めての内容だと理解しますので、趣旨採択をして意見書についてはまた、この場でいろいろな状況があればまた別ですけれども。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-005"},{"speaker":"南委員","kind":"意見","question":"きのう私は採択をしていいんじゃないかということで申し上げたんですが、聞くところによると、きのう１１区が提出するということなので、終わってからちょっとインターネットをあちこち見たんですけれども、どんな主張で意見書採択になったのか見たかったんですけれども、そこはちょっと行き当たらなかったので、どんなあれかわからないですけれど、しかし中身的には。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-006"},{"speaker":"南委員","kind":"質問・要望","question":"収集作業中の事故だとかこういう今ご報告があったような内容はあまりないと承知していたんですけれども、各戸収集で、非常に時間を気にして収集作業に当たらなきゃいけないところがあるのかなという気もしまして、私１人だけではなくてそういう意見を聞くものですから、そういう体制を含めて見直すみたいなところがあっていいんじゃないかと思いましたので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"}]},{"id":"topic-02","title":"─────────────────────── (2) 環境影響評価調査計画書（大崎短絡線整備事業）に対する区長意見について 次に","agenda":"─────────────────────── (2) 環境影響評価調査計画書（大崎短絡線整備事業）に対する区長意見について 次に","exchanges":[{"speaker":"土井委員","kind":"質問・要望","question":"先ほど意見を出すに当たって５回ほど事前説明があり、随分差が見られるというお話があったわけですけれども、その辺のところをもうちょっと皆さんにわかるように、少し詳しくお話をしていただければと思います。この意見書に向かっては、その説明会等々で出されたものをベースにされているのであろうと思いますけれども、その辺の状況を若干ご説明いただきたい。","respondent":"田中環境課長","answer":"ＪＲ大崎短絡線の計画説明会というのが、この調査計画書に先立ちまして周辺住民に行っています。大崎第２地区の全町会あての部分と、下の西品川新生会という町会の人たちに対する説明会が、平成１６年１０月２７日から平成１８年１１月１４日までの間に５回行われています。","id":"exchange-008"},{"speaker":"土井委員","kind":"提案","question":"全体の流れとしては、地域の皆さん、町会の皆さんなどの意見を十分聞きなさいということがベースになっていて、そこで出たもののほぼすべてを出しているというふうに聞いていいんでしょうか。それに基づいて、これでは工事担当と詰めたものの評価をすることになっておりますけれども、始まり終期ということでのもともとの提起、提案があるのではないかと思いますので、そこら辺を含めて。","respondent":"田中環境課長","answer":"新生会への説明とか住民が出している要望意見等、すべて盛り込まれているかという最初の質問ですが、基本的に環境アセスメントの手続きの中での区長意見でありますので、都知事あてに出す意見の基本的な内容は環境保全の見地から出すことになります。","id":"exchange-009"},{"speaker":"土井委員","kind":"質問","question":"確かに環境影響評価は調査計画書に対する意見ですから、環境に関するものだということになるんですけれども、この計画というものがここにあって、これに対するものだということですよね。この計画をどうするかという大もとの部分、地下化とか何とかという話はそれに当たるわけでしょうけれども、それらに対する議論というか、どういうふうに収束の方向にあるのかないのか、というところはどうなんでしょうか。","respondent":"田中環境課長","answer":"計画段階でのそこを通すという事業判断は、事業者であるＪＲのほうで計画するところでありますので、もしくは国ラインの交通政策等の中で判断されていくものだと思いますので、この環境影響評価の手続きの中でその議論をやるのは、範囲外になってしまうです。","id":"exchange-010"},{"speaker":"土井委員","kind":"意見","question":"まさしくそこなので。住民がいるということですね、あるいは町会という組織があり、そこら辺が大事なところなので、その辺を今現在どういうふうに受けとめていらっしゃるという背景のもとに、この環境影響評価をとらえているのかというところが知りたいんです。","respondent":"田中環境課長","answer":"その点で住民の人たちの意見を踏まえて生活環境や環境を守る、全体の環境を守っていくという観点で対応していくのが基本的な立場と考えております。","id":"exchange-011"},{"speaker":"土井委員","kind":"意見","question":"まあ、区の立場はそういうことだと思うんですけれど、問題は今、住民の皆さんが、その区と鉄道とのはざまに、事業者との間のどこかにいらっしゃるわけで、そこら辺の微妙なところをどうとらえているかということです。その辺の動向みたいなものをどう受けとめていらっしゃるのか。","respondent":"田中環境課長","answer":"先ほど言いました住民説明会の中で、やはり住民の方たちから幾つかの提案があって、ＪＲのほうがそれに対する説明をやられています。","id":"exchange-012"},{"speaker":"土井委員","kind":"質問","question":"もう１つ伺っておきたいのは、その５回の説明やこれからもＪＲ側から区民の皆さんにご説明があるだろう状況等々に、区がどこまで参加というか関与できるか、傍聴というか担っているのか。もともとの説明会等をやった報告書なり何なりに基づいたレベルの場合もあり得ますので、その辺はどのようになっているかお聞きかせください。","respondent":"田中環境課長","answer":"それで都条例に基づく環境影響評価の対象になるというのが、当初は環境影響評価の対象にならないという話だったんですが、去年の８月ぐらいの時点で環境影響評価の対象になることになりまして、そこから私どももＪＲからの説明を受けたりという対応になっています。","id":"exchange-013"},{"speaker":"南委員","kind":"質問・要望","question":"今のご質疑を聞いていてわからないので、改めて伺いたいんですけれども、今回この区長意見を２月１３日の日付でお出しになったことも含めて、環境影響評価調査計画書がアセスメントの一連の流れの中でどこに位置づけてあるのか、それとこれからの手続きについてさっきご説明はあったんですけれど、改めてその辺を伺いたいのが１つ。","respondent":"田中環境課長","answer":"縦覧されたのはこの１冊の本になりますが、詳しい内容を全部説明するわけにいきませんので概要を説明させていただきました。ということで、最初の位置づけということになります。","id":"exchange-014"},{"speaker":"南委員","kind":"質問","question":"その環境影響評価書が出たにしても、それに対してまた住民意見だとか区長意見だとかというふうになっていくのだろうと私は思っているんですけれど、そこら辺も教えてください。","respondent":"田中環境課長","answer":"その後にその環境影響評価書に基づいてきちっと守った形で事業が進められることになります。ＪＲ側が計画しているのは来年の二、三月ぐらい、一連の手続きを１年で終えるというスケジュールになっています。","id":"exchange-015"},{"speaker":"南委員","kind":"質問","question":"それだけのものを１年間程度で終えてしまうということ、もう少し、何と言うんでしょうか、どの程度の住民の意見とか区長がお出しになった意見について取り込める状況が確保できるのか、１年間の間で私はそんなに、今以上のものにはならないんじゃないかと思うんですけれど、その点についてはどういうふうに思っていらっしゃるんでしょうか。","respondent":"田中環境課長","answer":"評価書の公示・縦覧は１５日、その間に審議会に入ったり事業者にいろいろな計画書や意見が送られたりという一連の手続きがありますので、その結果としてこれぐらいとＪＲ側が見込んでいるところなので、それが途中の審議会の日程とか何かでずれたりとかは多少あるかと思いますが。","id":"exchange-016"},{"speaker":"南委員","kind":"質問・要望","question":"それと、この委員会のあれじゃないんですけれども、わかっていたら教えていただきたいんですが、このＲを描いている勾配というのか、この状況がどういうものなのか数字を示していただきたいと思うんですけれど、その数字そのものを見ても今はどういうものなのかよくわからない、専門家の意見も聞かなきゃいけないと思うんですけれど、もしわかっていたら教えていただきたいです。","respondent":"田中環境課長","answer":"区長意見の１の全般的事項の(2)のところで曲線半径と載っておりますが、１６０Ｒの計画ということになっています。これは鉄道のカーブを描く基準の中には一応入っていると。それを超えればつくっちゃいけないわけですが、その中に入っていることです。","id":"exchange-017"},{"speaker":"南委員","kind":"質問","question":"最後にします。もちろん、こういう計画そのものもできないわけですから基準に入っているのは当然なんですけれども、基準とこの１６０Ｒというのはどういうものなのか、基準そのものはどういうものなんですか。","respondent":"田中環境課長","answer":"最大でＲが１６０までということです。ですからＪＲ側は１６０Ｒの計画で、ここについてはスピード等落として運用するという地元説明等をやっております。","id":"exchange-018"},{"speaker":"山内委員","kind":"質問","question":"そのＲ１６０に対して、この前もＪＲ福知山線のああいう事故がありましたが、スピード的な部分で具体的に時速何kmで駅のホームに入ってくるか、具体的なスピードの数字、多分そういうところを住民の皆さんは気にされるだろうと思うんですが、その辺教えていただけますか。","respondent":"田中環境課長","answer":"たしか計画書の中ではそこの運用部分までは、私も読んでいるんですが、住民説明会の中ではあったかもしれないですが、運用の部分まではたしか出ていないですね。ただ、当然最大限の注意をするということなんですが。","id":"exchange-019"},{"speaker":"山内委員","kind":"質問・要望","question":"その数字的な部分が今後わかれば教えていただきたいのでよろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-020"},{"speaker":"本田委員","kind":"質問・要望","question":"騒音のことでお尋ねします。例えばＪＲ東海道線が品川区を突っ切っておりますけれども、日本ペイントのあたりから大井町、大森とずっと、一番外側は下り線が走っているんですけれども、在来線ということで９０dBを超えるような、例えば踊り子号などが通りますと近所では電話が聞き取りにくくなるという苦情が今でもあるんですけど、ＪＲのほうはそういう住民の要望に対して規制がありませんと。","respondent":"田中環境課長","answer":"ＪＲのほうでこの短絡線整備にかかる鉄道施設の変更について、運輸省の関東運輸局のほうにこれはどういう事業に当たるのか問い合わせています。","id":"exchange-021"},{"speaker":"本田委員","kind":"質問","question":"その辺が沿線住民の方々が心配することではないかと思うんですよね。今のご説明のように、本事業は従来線の改良ということでそういう基準には合致しないと。しかし努力をしなくちゃいけないという程度のことですから、それが法といいますか今の定めの中で、この(3)のところでかぎ括弧で強調していることの理由はそういうことなのかなと思うんですが、区としてはそういうことなんですか。","respondent":"田中環境課長","answer":"当然最新の技術によって、今、本田委員からご説明がありましたように車両の軽量化やロングレール化だとかを含めて、いろいろな騒音を低減するような対策を含めて、おそらく運用も含めてですが、周辺環境の改善の計画となるよう最新技術による万全の対策。","id":"exchange-022"},{"speaker":"本田委員","kind":"質問・要望","question":"この高架橋は普通の鉄橋のような図が書いてありますよね。つまりその基準になるものが新線整備とか大規模整備という締めに当たりませんので、騒音の規制基準が甘いですから、こういう格好でも通るという意味で。そういう基準的なところで、考え方といいますか対策に相違が出てきていると感じるんですけれども、このＲのところの高架橋はそういう防音壁はなされるんですか。これはなされない図面なんですか。","respondent":"田中環境課長","answer":"ただ、区長意見にありますように、大気汚染の(2)で「軌道全体を囲うなどの飛散防止対策」や、騒音振動で「防音壁および緩衝帯を設置する」等を含めて具体的な対応を求めていますので、今の段階でＪＲ側はトラス構造の高架橋以外、具体的なことは提案していませんので。","id":"exchange-023"},{"speaker":"本田委員","kind":"質問・要望","question":"区長意見ではかぎ括弧で従前よりもっと改善するということを強調しておられますけれども、そういう法律といいますか基準になるところでの見解の相違などで、要望、意見は出していてもそれが通らないということもまま、ＪＲの場合は多いですから、この意見の内容については相当きつく実現を図るように区当局としても一層の努力を図っていただきたいと、この騒音の問題に関して強調しておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"},{"speaker":"堺委員","kind":"質問・要望","question":"こういう区長の近隣住民の側に立った貴重なご意見等を都知事あてに出して、鉄道事業者の側にもこれは伝わるんだろうと思うんですが、こういうことに対する今度は回答というんですか、資料の４．今後の環境影響評価の手続きの中に（ア）（イ）（ウ）（エ）と出てくる、このどこかの中に入れられてくるんだろうと思うんですけれども、その辺について確認をしておきたいんです。","respondent":"田中環境課長","answer":"ただ基本的な立場を踏まえて対応していきたいと考えています。","id":"exchange-025"},{"speaker":"堺委員","kind":"質問・要望","question":"流れについては理解できました。ぜひ、今、課長がおっしゃいましたように、努力をしていただきたいと思います。それから、この審査意見書に取り込んで事業者側に伝えるというのは、手続き的にいつごろなんですか、いつごろ事業者側に伝わるのか。今度は事業者側から区長に、向こうの何らかの回答があるとすれば、いつごろそういう回答が出るんですか。公表されるのは。","respondent":"田中環境課長","answer":"標準的な審議する期間は行政手続きですので決まっているんですが、それを超えることもあるんでしょうが、一応計画書の提出から審査意見書の提出までは４５日から６０日です。","id":"exchange-026"},{"speaker":"堺委員","kind":"質問・要望","question":"資料の４．今後の環境影響評価の手続きですけれど、行政手続きとして１年以内で済ませるということですから、４５日から６０日の間で、出てくるんだろうと思うんですが、鉄道はどうしても公益性という面が強いですから、すべて反対というわけにもなかなかいかないのかもしれませんけれども、そのために出てくる影響についてはなるべくといいましょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-027"}]},{"id":"topic-03","title":"３番目のカラス対策推奨ごみ袋の認定","agenda":"３番目のカラス対策推奨ごみ袋の認定","exchanges":[{"speaker":"土井委員","kind":"質問","question":"問題は、これらを推奨する、売ることになるわけですけれども、ここのところでお値段とか、前の袋との関連とかはどう考えたらよろしいんでしょうか。","respondent":"中山資源循環推進課長","answer":"ですから、これがベースになるのかなと考えていますけれども、一応業者の予定を聞きますと、小さいタイプの３０ｌであるとか、１０ないし２０ｌのものもあわせて、杉並区ではそういう小さい袋の要望があるようですから考えていくということで。","id":"exchange-028"},{"speaker":"土井委員","kind":"質問","question":"最初、あの白い袋になってもスーパーマーケットの袋を使える状況にしなきゃならなかったわけですよね、現実問題として。そんなふうにしてやってもらわなきゃいかんだろうと思うんだけれども、これはメーカー２社の特許ということで、２社だけなんですか。それともどこか参入をしようと思ったら、そりゃお金を払えば可能なんでしょうけど、その関係はどうなんでしょう。","respondent":"中山資源循環推進課長","answer":"ちょっと余談ですけれども、黄色の袋なら何でもいいのかというと、他の自治体でとりあえず黄色ならばということでいろいろやってみると被害を受けたという報告もあったり、今のところこの効果現象がされるというのは、カラスの網膜にある成分が。","id":"exchange-029"},{"speaker":"土井委員","kind":"質問","question":"この黄色でこの材質でということなのか、要するにこの黄色は何の黄色なのと。それが特許なのかどうかわかりませんけれど、黄色ですからね。どう使っても黄色は黄色なんだけれども、ある種の周波数が特殊的に出るような配合とか何とかということが特許になっているのかどうかわかりませんが、これじゃ大分違うなと思いながら見ているんですけれど、その辺はどうなんですか。","respondent":"中山資源循環推進課長","answer":"ただし、そのことが先ほど申し上げた検査結果であるとかあるいは客観的なデータ、第三者機関の認定、証明も含めて出されていることを前提に、区が申請を受けて審査をした結果、認められると、新たな独自条項の区の認証の対象になっていくです。","id":"exchange-030"},{"speaker":"土井委員","kind":"質問","question":"そうすると、黄色であろうがピンクであろうが、何色でもいいよと。ただ問題は、カラスがちゃんと言うことを聞いてくれるかどうかの問題ですね、カラスの反応次第でね。それを業者さんにやりなさいよということですね。その辺をどうしたらいいのかなと思うものですから、逆に、こういうのでやったのでテストしてくれますかという話などが起こったらどうするのかなという気がするので。","respondent":"中山資源循環推進課長","answer":"実は杉並区も袋の色を契機に独自の認定をするということで、同じような形で間口を広げておりますけれども、今のところこの黄色以外の袋は現実として出てきていないというのが実態ではありますけれども、可能性はあるということです。","id":"exchange-031"},{"speaker":"土井委員","kind":"質問","question":"要するにこの黄色の周波数を分析すればわかるわけですから、その色が目に映ればカラスは退散してくれるということだとすれば、そのある周波数のものが含まれた袋であればカラスは行ってくれる可能性が極めて大だということになるので、その周波数さえはかればいいことになるわけですよ。ある周波数だけだったらもっと出しようがあるんじゃないですか。","respondent":"中山資源循環推進課長","answer":"ただなかなか、さっきも申し上げたように黄色であれば何でもいいのかというとそうでもないという分析が、現段階ではまだ特定できるほど大きな成果が出ているものが限られているということでございまして、今後そういうものがもっと客観的に出てきていろいろな形がとれれば。","id":"exchange-032"},{"speaker":"土井委員","kind":"意見","question":"高密度、低密度になってみたり、黒かったり白かったり、黄色になったり、そのうちどんな色が出てくるのかどうかわかりませんが、ということになると、みんな迷うわけですよ。どうなってるのということになるわけで。ましてやこの２つが仮に売り出されたら、どっちをとるかなというとき、よく先が見えないわけです。というのがどうも腑に落ちない部分があるので、意見を述べて終わります。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-033"},{"speaker":"土井委員","kind":"質問・要望","question":"あの建物はたしか女の館と男の館とあって、女の館のほうがきゅりあんと一緒ですから、そこら辺でも利用形態等の変更等に関連して、品川区等が何か要望、意見等を言っていける立場にあるのかないのかも含めて、出資比率みたいなものはもちろん、その辺も含めてどのようにお考えになっているのかお聞かせください。","respondent":"金子産業振興課長","answer":"幾つかのご質問ですけれども、まず丸井からの話としては、丸井にかわる新しい入居者には現状のまま引き継ぐと聞いておりますので、そういった管理形態等々について大きく変更することはないだろうという見込みを今たてているところです。","id":"exchange-034"},{"speaker":"土井委員","kind":"意見","question":"ということは、きゅりあんのある建物の分の部分所有権として、要するに丸井以外の部分、そこには共有部分があるかもしれませんけれども、そういうところの所有というスタイルで運用がされているんだというふうに理解してよろしいんですね。","respondent":"金子産業振興課長","answer":"あの建物は１号棟、２号棟２つあります。２号棟は丸井が完全に所有しているものです。１号棟につきましては、大まかに言いますと品川区と丸井と地権者の方が持っている部分があります。","id":"exchange-035"},{"speaker":"土井委員","kind":"意見","question":"その地権者の皆さんとの絡みなんですけれども、地権者の方々は自分の権利のある部分を丸井にお貸しして丸井が営業にお使いになっていたということだと思うので、その使用者が移ることも了解されているんだろうと思いますけれど、どうなんだろうか。","respondent":"金子産業振興課長","answer":"地権者の方の関係ですけれども、丸井からは先ほど申し上げましたとおり、新しい入居者には現状を引き継ぐという考え方であるということで、地権者にも影響が及ばないよう検討されていると聞いているところです。","id":"exchange-036"},{"speaker":"本田委員","kind":"質問","question":"丸井が入るについても、丸井１社だけじゃなくて何社もあった中から丸井が選定されて入ってきたという経過を見ると、大井町の振興とまちのあり方についても、この変更によって当初の目標が崩されるようなことがあってはならないと思いますし、近隣商店との調和というものを大事にしていくような対応が今後なされなければならないと思いますので、そういうことについては。","respondent":"金子産業振興課長","answer":"ただし、今申し上げたとおり、どういう業種、業態が入るかによって違ってくると思いますので、その辺についてはまたその時点、時点で考えていきたいと考えております。","id":"exchange-037"},{"speaker":"南委員","kind":"質問","question":"８月で終了ということなんですけれども、丸井はどういうことで終了するというふうになっているんでしょうか。どういうふうに聞いていらっしゃるんですか。","respondent":"金子産業振興課長","answer":"丸井が営業を終了する理由としては、私どもがお聞きしているのは小売業界の環境が厳しい状況があるということでお聞きしています。","id":"exchange-038"},{"speaker":"南委員","kind":"質問","question":"収益が予想を大幅にというか落ち込んで、あそこでの営業活動は停止せざるを得ないというふうに私は聞いたんですけれど。そういう点でどういうふうに全国の実態を見て、都心と地方とは違うというのがあるかもしれないけれど、それはしかし、こういう事態を招いたときやはり違うんだということでは済まされないと私は思いますので、その辺の見解もあわせて伺いたいと思います。","respondent":"金子産業振興課長","answer":"ご案内のとおり、大井町はりんかい線が開通して以降、かなりにぎやかさが増してきているという認識は持ってございまして、区議会でもそのようにご答弁してきたところだと考えています。","id":"exchange-039"},{"speaker":"南委員","kind":"質問","question":"だからどんなお店が入って来るにしても、それはそれで相当影響が出てくるでしょうし、その辺の認識はどういうふうに持っているのか、今ちょっと答弁がなかったんですけれども、もう１回伺いたいと思います。","respondent":"山田区民生活事業部長","answer":"あちらも途中で撤退することに関しては責任を感じて、今ある形態の部分を同じ形で継続できるようにということで、いろいろな量販店との交渉の中で今、絞りつつあるですので、同じような環境、同じような条件で進出されるということであれば。","id":"exchange-040"},{"speaker":"南委員","kind":"質問・要望","question":"品川区はやはり地域の活性化を第一番にしなきゃいけないと思うんですよね。大型店頼りにあまりにもなっていたんじゃないかと、こういう撤退を聞いたときに私は改めて思うんですけれども、やはり地域の商店街の活性化をいかに図るかという点で、きちんとこの問題に対応していただきたいということを、こういう時間なのでこれ以上言うつもりはありませんので、そのことは強調しておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-041"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/593414?Template=document&Id=2484#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2007-01-01&TermEnd=2007-12-31"}],"sourceMeta":{"pages":0,"characters":29707,"voices":102}},{"id":"h19-20070227-7","meetingId":"h19-cm02","date":"2007年2月27日","dateIso":"2007-02-27","committee":"厚生委員会","time":"午前１０時０３分～午後２時５８分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を66件抜き出しています。","topics":[{"id":"topic-01","title":"請願・陳情審査","agenda":"請願・陳情審査","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"理事者の方にお聞きしたいんですけれども、ここでは有料老人ホームよりも特別養護老人ホームをつくってほしいという請願ですけれども、有料老人ホームと今度のケアホームは違うということですけれども、基本的には有料老人ホームも介護報酬のくくりでは特定施設入居者生活介護ということになりますので、基本的なくくりとしては私は同じであると思うんですけれども、そのところで。","respondent":"蓼沼高齢福祉課長","answer":"それからケアホームにつきましては、第２段階の数字が手元にないんですけれども、要介護５で第３段階で約２０万円、西五反田については要介護５ですと約２８万円、それから補助金の関係ですけれども、整備費につきましては１人当たり定額で３９０万円という整備費。","id":"exchange-001"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"特別養護老人ホームが５万２,０００円でケアホームが２８万円ということで、第２段階という方は収入が８０万円以下という方ですけれども、この方は初めからケアホームというのは対象にしていない施設ということで、貯金があれば別ですけれども、ただ、また８０万円の収入の方というのは貯蓄というのもなかなか難しいと思うんですけれども、大体この特別養護老人ホームの対象にしている所得の割合というか。","respondent":"蓼沼高齢福祉課長","answer":"それから９月の入所調整の際、約４５０名の方が申し込みをされておりますけれども、その方の１月末現在の状況では約５０名の方が入居されているという状況です。","id":"exchange-002"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そういう声に対してどう考えているかということと、それからそこの中でかなりもう本当に切実な声がたくさん挙がっていまして、ちょっと本当に１つ１つ私は部長や課長に見ていただきたいなと、まとめたらぜひ持ってきたいなと思っているところなんですけれども、ここの中でも、ケアホームの負担ができない老人はどうするのかと。","respondent":"蓼沼高齢福祉課長","answer":"今後の施設の整備につきましては、個室・ユニットケア、今後の団塊世代を含めた高齢者が増加する中で、さまざまなそういう住まい、施設へのニーズがあるだろうということで、そういったニーズに対応していく。","id":"exchange-003"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そこら辺のところはそういう考えなのかということが１つ、そして補助金も同じ、そして利用料についてはそういうふうにきちんと所得によって減免制度があって払える金額になっているというふうなところなのに、しかも個室・ユニットというふうなところでは、区の求めている施設ということであるにもかかわらず、なぜ特別養護老人ホームでなくてケアホームなのかということが１つお聞きしたいのと、それから。","respondent":"木下福祉高齢事業部長","answer":"特別養護老人ホーム整備等に関する考え方という点ですけれども、品川区の場合には介護保険が始まる平成１２年度までに基盤的な部分については整備を完了しているというのが基本的認識でありまして、区内には５７２、三多摩も含めまして、今。","id":"exchange-004"},{"speaker":"西本委員","kind":"質問","question":"この請願書の中で、請願趣旨ですね、原小学校跡地に特別養護老人ホームをつくってくださいということを書いておられるんです。ここはたしか現存の校舎を建て直すのではなくて、そこを利用していろいろな施設が入るということで聞いているんですが、その考え方はどういう、建て替えじゃなくて、つまり現存の校舎を利用してというところの決めた理由というのはどういったところでしょうか。","respondent":"蓼沼高齢福祉課長","answer":"今のご質問にありましたように、原小学校跡の活用につきましては建て替えではなくて既存の校舎を改修して使う、その考え方につきましては、基本的にはまず校舎の耐用年数がまだ大分残っているということと、あとは道路事情、周辺環境等もあわせ考えまして。","id":"exchange-005"},{"speaker":"西本委員","kind":"質問","question":"それと、ここの理由の中に、お聞きしたいのが、大田区の民間施設を利用しているということですが、品川区にはリハビリ施設という意味合いのもの、要は寝たきりにしないためのそういう施設というのはあるんでしょうか、ないんでしょうか。現状はどうなっているんでしょうか。","respondent":"蓼沼高齢福祉課長","answer":"介護保険上のリハビリと申しますと、できる施設が老人保健施設と診療所というふうに規定されております。ですので区においては南大井のケアセンター南大井が老人保健施設として介護保険上のリハビリ施設になっております。","id":"exchange-006"},{"speaker":"西本委員","kind":"質問","question":"それと、最近は筋力トレーニングというのがあったり、予防ということですね、寝たきりにさせないよという事業もかなりいろいろ進んでいるのではないかなというふうには認識はしているんですけれども、仮に、シルバーセンターが入ってきますので、その中に寝たきりにならないためのそういう施設というか、考え方というか、そういうものが入れられるんじゃないかなと思うんですが。","respondent":"冨岡高齢事業課長","answer":"シルバーセンターにおきましては、今、改修している施設も同じですが、西大井のシルバーセンターにつきましても介護予防の施設を一緒につけまして、介護予防に努めてまいりたいと考えています。","id":"exchange-007"},{"speaker":"鈴木（真）委員","kind":"提案","question":"その中では、幾つかは先ほど来の質問の中でやはり特別養護老人ホームの必要性というものも理解はいたしますけれども、この案件の中、それともう１点、リハビリ設備という点も、私どもも多少その考えはありますけれども、現状においてこれはもう既に公募している、区から先に例えばこのリハビリをつけてくださいという条件がついているならまた別ですけれども、現状、このプロポーザルの中では。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-008"},{"speaker":"三上委員","kind":"質問・要望","question":"先ほどの質疑の中からもう少し確認させていただきたいんですが、品川区議会における行財政改革特別委員会でこの跡地の問題については検討されたという、その部分についての、ちょっと私は委員会が違っていましたので、つぶさには承知していませんので、いつのとき、どれくらい時間をかけてそういったことが検討されたのかということがまず１つ、それから。","respondent":"蓼沼高齢福祉課長","answer":"原小学校跡の行財政改革特別委員会での検討状況ですけれども、具体的にその委員会の回数ですとかはちょっと今、手元にデータはございませんけれども、大体昨年の５月ごろから庁内でワーキンググループを立ち上げて、同時並行して行財政改革特別委員会にも、５。","id":"exchange-009"},{"speaker":"三上委員","kind":"質問・要望","question":"どういった検討の仕方になるかは、それはわかりませんけれども、そういう中にあって、現段階にあっての高齢者比率、それから少子比率、そういったことが随分変わってきているという現状の中にあって、区長も長期計画を見直そうと、こういう段階にあるということになれば、そこらあたりでしっかりとどういう取り組みを今後していかなければならないのかと、当然。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"},{"speaker":"木下委員","kind":"質問・要望","question":"すいません、ちょっと確認なんですが、先ほど港区が調べた事例で、一番低かったというお話を課長がされていたんですけれども、それは、要するにいろいろ人口比だとか、いろいろな例えば高齢者比率ですと区によって違うんですが、そういう比率の中で品川区は２３区中一番低かったというのは、一番その対応ができているという認識でよろしいんでしょうか。それを確認で教えていただきたい。","respondent":"蓼沼高齢福祉課長","answer":"すいません、ちょっと説明が不十分だったようで。先ほどの説明ですけれども、港区の調査では、まず６５歳人口に対する待機者の割合、それともう１つが認定者数です。","id":"exchange-011"},{"speaker":"木下委員","kind":"質問","question":"なかなかはっきり言いにくい部分があるのかもしれないですけれども、対応しているということをおっしゃっていると思うんです。仙台市にある。その際に、施設の皆さん、施設長を集めて講演した際に、「もし高齢になって寝たきりになった際に、そういう施設に皆さん入りたいですか」と質問したら、だれ一人として入りたいという人がいなかったと、二、三百人そういう方々を集めた講演の際に。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-012"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"私は、今日言いたいのは、先ほど来のご答弁で、昨年９月４５０名申し込んで、１月末に５０名程度の方が入居をされている、この１月末の状況でも既に４００人の方が希望されて入れていないというこの状況を、区はたびたびご答弁の中で整備済みとお答えになっているんですが、この４００人の方たちはどうなってしまうのかとまず疑問なんですけれども。","respondent":"蓼沼高齢福祉課長","answer":"整備済みということについての考え方ですけれども、基本的に区といたしましては、先ほど申し上げましたように、在宅重視というのが基本的な考え方です。在宅生活が立ち行かなくなったときに施設入所の見通しが立つということで、そういう方針で進めております。","id":"exchange-013"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"今の基準のところをもうちょっとわかりやすく教えていただきたい。そういった状況の中で暮らしていらっしゃる方に、在宅がいいんですよ、在宅がいいんですよと言っても、実際とはかけ離れている状況であると思うんです。すいません、その辺をどう考えていらっしゃるのか、あともう一回、すいません、基準をもうちょっとわかりやすく教えていただきたいんですが。","respondent":"蓼沼高齢福祉課長","answer":"入所されている方はそういうことでは、先ほど申し上げました基準で照らして、要介護度で申し上げますと、先ほど要介護３、４、５の方が中心と申し上げましたけれども、さまざまな状況によっては要介護１、２の方も入所されているという状況があります。","id":"exchange-014"},{"speaker":"飯沼副委員長","kind":"意見","question":"私は整備済みとあるのは、これは認識が誤りであると思うのでぜひ変えてほしいし、今回の皆さんの願いをしっかり受けとめるべきであるし、ケアハウスというのは今日、料金を聞いても、ここにいらっしゃる皆さんはほとんど利用ができない、多分、部長や課長や私たちなんかも利用ができる料金ではないなと思っていますので、そういった意味では本当に税金の使いどころというか。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-015"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"ケアホームというのは品川区だけという状況で、そういう状況が明らかになりましたけれども、そして西本委員、そして木下委員、鈴木（真）委員にお聞きしたいんですけれども、特別養護老人ホームは必要だと認識しているということで先ほどご発言がありましたけれども、そうであれば、品川区はもう特別養護老人ホームは増設しないという方針を持っていますけれども、その方針を取りやめて。","respondent":"須藤委員長","answer":"今、請願の内容を審査していますので、特別養護老人ホームについての全般的なことになってくると、また別の観点ですので、そのあたりは、考慮してください。お答えになるのは自由ですが。","id":"exchange-016"},{"speaker":"鈴木（真）委員","kind":"意見","question":"その中において、こういう高齢者の方の施設の必要性を感じておりますので、私も例えばケアホーム、都南病院の跡地も随分お願いをしていましたし、それが実現できたことによって高齢者施設が１つでもできてきた、またここに原小学校跡にできてくればまたもう１個追加になってくる、これからの必要性は十分感じているという意味で、これからの制度のあり方はまた長期の考え方の中で施設が必要だという意味で。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-017"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そこで働いている方もいらっしゃるわけですよね。そういうところで、あと本当にこの問題は、またもう１つの請願のところでも特別養護老人ホームの問題が出てきますので、まだまだ言いたいことはたくさんあるんですけれども、そういうところで区民の願いから考えると、私は改めて、区民からケアホームという要望が出てきたのかどうか、そこら辺のところを１点だけお聞かせいただきたいと思うんですけれども。","respondent":"木下福祉高齢事業部長","answer":"ただ、先ほど申し上げたように、やはり個室になってきますと２対１とか、１.８対１とか、そういう体制をとらないとなかなか難しいということがあります。","id":"exchange-018"},{"speaker":"三村委員","kind":"意見","question":"ただ、この原小学校跡地というところで限定されているというところでは、なかなか採択というところまでは行かないんですけれども、ただこの趣旨、こういう介護施設を充実させてほしいというところでは、趣旨採択というところで私たちは考えております。","respondent":"須藤委員長","answer":"改めまして、請願第３号について継続審議あるいは結論を出すと、どちらかにしていきたいと思いますので、大体皆さん方の態度を見ますと結論を出す方向で考えていらっしゃるようですので、結論を出すということでよろしゅうありますか。","id":"exchange-019"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"このベッドとか車いすのレンタルが介護保険でできなくなってしまったという問題は、地域でたくさんの方からお聞きしたんですけれども、品川区にもこういう多分これは困るというような声がたくさん届いたんじゃないかと思うんですけれども、そういうご相談があったケースとか、件数とか、そういう実態ですとか、そこら辺のところをまず教えていただけないでしょうか。","respondent":"蓼沼高齢福祉課長","answer":"対象者の方、利用者の方につきましては、そういう意味では個別に説明をしてまいりまして、そこにおきましてやはりそういう困るですとか、いろいろな声は相談としてあったと聞いておりますが、例えば具体的な苦情のような形で区に声が寄せられたというのは特段ございません。","id":"exchange-020"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"そういうので、私が聞いただけでも何件かあるので、多分、全体ではたくさんあるんじゃないかと思うんですけれども、そういうことに対してはどう考えられているでしょうか。","respondent":"蓼沼高齢福祉課長","answer":"先ほどありましたようにベッドを持っていかれるとか、そういうことはもちろんないと思っていますけれども、基本的には事業者にもそういうような扱いはしないように指導しておりますし、事前に、ですから経過措置がありましたので、経過措置の時間が、４月から制度改正があって。","id":"exchange-021"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"であれば、私は課長がそういう実態を把握していないということそのものが、高齢福祉課の課長としてどうなのかなと改めて驚くんですけれども、そういうことで高齢福祉課に相談に何度も行っているわけですから、何とかならないかと、それでもどうにもならないというふうなことになったためにベッドを持っていかれちゃったわけですから、持っていかれちゃったとみんな思ってますよ。","respondent":"蓼沼高齢福祉課長","answer":"生活保護の方につきましても、一定のそういう経過措置の期間の中で用立てをといいますか、なるべくそういう購入できるもの、あるいはレンタルできるもので対応してきたと考えています。","id":"exchange-022"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"やっぱり一番住民に身近な自治体なんですから、そこら辺の区民のそういう実態に心を寄せるというのがすごく必要なんだと思うんです。それと、他の自治体はどうなのかというところで見たときに、２３区の中でほとんどの区が対策をとっていると思うんですけれども、２３区の介護ベッドの貸与が受けられなくなった問題に対しての対策について、把握されていたらお聞かせいただけないでしょうか。","respondent":"蓼沼高齢福祉課長","answer":"品川区といたしましては、今回の制度改正は適切な改正であったという認識に立って、ベッドについてもそういう一定の基準が示されておりますので、それについて利用者に対して、利用者の皆様に早い時期から制度の趣旨を説明して、ご理解をしていただいて。","id":"exchange-023"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"しかも私はこの東京都が施策を９月末にしたというのが遅過ぎたというのが区の言われるところですけれども、これはもっと本当は先に東京都も先を見越して出していれば一番よかったのかなと思うんですけれども、先を見越して出していたら、品川区としては適用されたのでしょうか。そこのところも１つお聞きしたいのと、あとは多分この時期、いろいろな問題が噴き出したんだと思うんです。","respondent":"蓼沼高齢福祉課長","answer":"この基準が、先ほど申し上げましたような２つの起き上がりができない、寝返りができないという基準で、非常に機械的ではないかというような問題点があって、それでもう少し実態はどうなのかということで厚労省で各都道府県を調査した中で。","id":"exchange-024"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それに対して今度は厚生労働省からそれは見直して、もっと緩和して進めていきましょう、これでも不十分だと思うんですけれども、そういうふうなことが出てきたわけですけれども、これに対しての考え方というのをご答弁いただきたいということで先ほどお願いしたので、それを１つお願いしたいと思います。","respondent":"木下福祉高齢事業部長","answer":"やはり給付の効率化という点で、保険料がどこまで区民の方に持っていただけるのかというようなことも含めて考えますと、特殊寝台という部分については、軽い方についてはむしろ日常の生活のありようの選択の問題というようなことで判断をしていくべき。","id":"exchange-025"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そういうところでは一番、先ほどからも申し上げていますように、高齢者にそういう要介護者の方たちに直接接する、声を聞くところですので、区としてもそこら辺のところをしっかりと見ていただいて、この他区がやっているような助成制度をぜひ区でもやっていただきたいと思いますので、この請願に賛成をしていきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-026"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"ぜひそこの調査をしていただきたいなと今、つくづく思いました。そこを１つお伺いしたいのと、あと私はどうして品川区は対策がとられないのかなと本当に疑問に思っているんですけれども、本当に東京都全体にしても、区としたら１０区、あと２市１町というところで、具体的に独自の介護ベッドの貸与、利用料、購入料の助成をしているところが本当に広がっているんです。","respondent":"蓼沼高齢福祉課長","answer":"それから区としての助成についての考えですけれども、先ほどの繰り返しになりますけれども、制度改正の趣旨を踏まえて、そういう軽度の方、要支援あるいは要介護１までの方については、自立生活を支援するという制度改正の趣旨にのっとってご説明をして。","id":"exchange-027"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"ご理解をいただいている、ご理解をいただいているというご答弁のわりには実態に接していらっしゃらないご様子なので、ぜひ実態に触れていただきたいなと思いますし、本当に今の状況って基準に対してどうかという、その基準自体がよりよい生活に持っていくための支援というよりも、ふるい落として排除をするための基準になっているくらい厳しい実態になっていると思うんです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-028"},{"speaker":"鈴木（真）委員","kind":"意見","question":"今、委員長がおっしゃったように非常に難しい点があると思っていますが、請願項目２のほうから先に意見を言わせていただきますと、先ほど鈴木（ひ）委員からご指摘があった言葉の中で答えを出してとなると、我が会派としては現状の品川区のケアホーム、グループホームという考え方を支持しておりますので、２番の点については賛同はできないという答えになると思います。助成という問題になっていくと。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-029"},{"speaker":"三上委員","kind":"質問","question":"先ほど来から説明がありましたように、私も代表質問等での軽度者に対するやっぱり国の考え方をもう少し明確に打ち出してもらいたいということで、私どもも国会議員を通じながらいろいろやっているところですので、そういった点から考えて、本日のところはこれについては継続、特別養護老人ホームを増設してくださいということになってくると、委員長から話がありましたように、これだけということになると。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-030"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"私は今日、結論をぜひ出していただきたいと思います。というのも、選挙になって継続にしたとしても、それが廃案になっていくということになってしまって、その後に続かないということがありますので、ぜひ私は今日、結論を出していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-031"},{"speaker":"西本委員","kind":"質問・要望","question":"この請願の１番については、私も相談を受けていたケースがあります。ただ、今後の、先ほど部長のお話にもありますように、制度が変わるかもしれないというところがありますので、私はしっかりとそこを見た上で判断すべきことではないのかなと思いますので、継続としていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-032"},{"speaker":"三村委員","kind":"意見","question":"私は、鈴木（ひ）委員と同じように、今回採択すべきだと考えています。内容としても、今回の介護ベッドを実際のところはかなり現場というか、このベッドが使えなくなるということで、実際の当事者たちはいろいろ大変な思いをされているというお話も聞いていますので、ぜひ採択をすべきではないかと考えています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-033"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"視力障害２級を福祉タクシー券の対象にしてくださいというのが項目の１つなんですけれども、品川区の視力障害２級の方の人数と、もしその方を対象にするとどれぐらい予算としてかかるのかを教えていただきたいのと、あと視力障害の方について、ここでは「他区では視力障害２級がタクシー券の対象になっていると聞きました」と書かれているんですけれども。","respondent":"西島障害者福祉課長","answer":"それから他区の状況ですが、この辺は本当に正確な資料かどうかというのは私もちょっと、中身を見ますと時々違っていますのでわかりませんが、平成１７年ぐらいの資料で申し上げますと、１級までというところは２区です。","id":"exchange-034"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"１級しか対象にしていないというのは品川区ともう１区だけと２区しかなくて、あとは２級以上を対象にしているということですけれども、そしてまたその対象の方は１５４名で４３０万円ということなんですが、４３０万円ということであれば、区がその気になればすぐにでもやっていただける額かなと思うんですけれども。","respondent":"西島障害者福祉課長","answer":"４３０万円がどうかというのはなかなか難しいところでございまして、それは予算全体にかかわることですが、２級に対する考え方です。今回、こういうご希望をいただきました。","id":"exchange-035"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そういう点では３級まで拡大して支給をしているところも何区かありますので、２級にとどまらずにさらに３級まで拡大していただけたら、それはそういう要望にこたえるということで、ぜひそういうところでも含めてご検討いただきたいと思っていますので、前向きなご検討ということで、ご検討いただけるということで、改めてちょっと確認をお願いしたんですが。","respondent":"西島障害者福祉課長","answer":"その形によって不便さのぐあいも大分異なってまいりますので、その辺も総合的に見ていく必要があると、だからといって、どこかでやっぱり線を引かなければいけないというようなこともありますので、その点については今後の研究課題と現在は考えているところです。","id":"exchange-036"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"私が今回のこの福祉タクシーの利用券の問題でインターネットでいろいろと調べていましたら、これって東京都とか２３区だけでなくて、地方都市でもかなり同じような状況で福祉タクシーの利用券というのが実施されているんだなというのを改めて思ったんですけれども、ここのところでは横浜市が、横浜市ももちろん視覚障害２級の方まで対象にもしているんですけれども。","respondent":"西島障害者福祉課長","answer":"他区の状況というのはどういうことをお尋ねなのかわかりませんが、２３区で言いますと、それぞれの区が、それぞれ目的は一緒でしょうけれども、実施をしているです。","id":"exchange-037"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"他区の状況というのは、他区の支給枚数の額について教えていただきたいということなんですけれども。","respondent":"西島障害者福祉課長","answer":"多いところでは月に５,０００円とかというところもありますが、おおむねそのような状況です。１区１区読み上げるとちょっと時間がかかりますので、この程度にします。","id":"exchange-038"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そういう方が福祉タクシーで本当に人間らしい生活ができる、ほんのわずかなというふうな、そういうささやかな願いだと思うんですけれども、そういう願いにこたえるという点からも、ぜひ福祉タクシー券の枚数を増やしていただきたいと思うんですけれども、改めていかがでしょうか。","respondent":"西島障害者福祉課長","answer":"ですから年間７万２,０００円だと聞いてます。ただここの部分は高いんですが、では江戸川区の今回の障害者自立支援法に対する軽減措置はどのような措置をとっているかということを考えたときに、ほとんど軽減措置をとっていないと聞いております。","id":"exchange-039"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"だから自立支援のほうで上乗せ施策をとっているから福祉タクシー券のほうはというふうなことで、それは区として全体としてはそういうふうなことというのはあるかもしれないんですけれども、この人にとってはこの福祉タクシー券の拡充というのが切実な願いだというところで、ぜひ前向きにご検討いただきたいということで、要望でとりあえず終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-040"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"この方のご要望は十分理解はできたと思います。それと一緒に、これも１月２２日にいただいた資料の中で障害者福祉計画、これも含めていく中にこの辺のご要望を生かせる部分が、取り入れられる部分があれば、その辺も十分ご検討いただきたいとは思います。態度まで言っちゃってよろしいですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-041"},{"speaker":"西本委員","kind":"質問・要望","question":"二、三分かかるところを二、三十分かかります、これは考え方によっては１人で行くよりはやはり家族の方がある程度いろいろ支援していただけるのであれば、やっぱり二、三十分かかりながらも、何ていうんですか、家族だけじゃなくて、周りの地域の方たちも含めて支援をするというような、そういう考え方もあろうかと思うんです。ちょっとそこがよくわからないんですけれども、わかっていたら教えてください。","respondent":"西島障害者福祉課長","answer":"やはり障害をお持ちの方もできるだけ自立してやるためには、訓練的な要素のガイドヘルプ、それからそうではない安全を見たガイドヘルプ、さまざまな施策の進め方があろうと思いますが、そういうことも含めまして、先ほど鈴木（真）委員からも出ましたように、基本計画の中で。","id":"exchange-042"},{"speaker":"西本委員","kind":"質問・要望","question":"ぜひ、これはお金というのは、お金がないと何もできないというのがありまして、財源をどうするのという考え方も出てきますよね。ですから１個１個の１つの項目で議論するというのはなかなか福祉のところは難しいと思いますので、もっと広い意味でのところで、これはどうするのかという視点に立って議論を進めていただきたいなと思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-043"},{"speaker":"三村委員","kind":"意見","question":"先ほど障害者団体の方から声が挙がってこないというようなお話がありましたけれども、この障害者団体の中には、中途の方、特にご高齢で失明されたような方というのはどの程度の割合入られているとか、その辺のことはわかりますか。","respondent":"西島障害者福祉課長","answer":"視覚障害者のことに限定して言いますと、障害者の方に対するデータというのはそれぞれ手帳の関係を出すのですが、１人１人ずっと追っていかないと、先天性なのかどうなのかというのはなかなか判断がつきませんので、この辺の把握はなかなか時間のかかることかなと思ってあります。","id":"exchange-044"},{"speaker":"三村委員","kind":"質問・要望","question":"そういった状況だと今度は足腰が弱ってきますし、家の中での転倒だとか、そういうほかの部分でのコストがかかって、介護のほうのお金がかかってきちゃうということもありますので、それぞれの状況に応じて、生まれたときからぼんやりというような、周りが把握できるという状況下でずっと生まれ育っていれば、それほど不自由なくある程度の自立した生活ができるかもしれないんですけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-045"},{"speaker":"三上委員","kind":"意見","question":"そういった人に対して一律２,３００円のタクシー代ということが支給されるということになってくると、その人はどういう使い方をしているかどうかわかりませんけれども、そういったことについても果たしてどうなのかということは先ほどちょっと指摘がされているような話にもつながってくるのかなと。そういった点では、継続にしておいてということでお願いしたいなと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-046"},{"speaker":"木下委員","kind":"質問・要望","question":"私も今までのお話を聞いておりまして、やっぱり一律はどうなのかなと、課長のお話があったように、視覚障害者の団体の方のこういうタクシー券の要望が出てきていないというのは、今までの話の中で、トータルで対応していただきたいということで出てきていないのかなというふうにも思ってます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-047"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"その福祉タクシーのところで、品川区の場合は予約代に４００円かかって、そのほかに初乗り分がかかって、出発するときにはもう既に１,１４０円がかかっているという状況なので、特にこの福祉タクシー券の２,３００円では１回分にもならないということもお聞きしているんですけれども、ここら辺のところというのは、なぜ区が契約している睦交通とか飛鳥交通第五でも、予約代とか。","respondent":"西島障害者福祉課長","answer":"その方がほかへ出てしまいますと、仮に車は運転できたとしても、介護できる方がいらっしゃるとは限りませんので、ホームへルーパー２級なり１級なりの資格を持っている人で、なおかつタクシーの運転手のもちろん資格を持っている方が運転している、そのような状況もありますので。","id":"exchange-048"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そしてそういうのが全く、予約代も、送迎料金ですか、そこまで向かってくるまでの料金だから、品川区で言えば１,１４０円がかからなくても済むという区もあるということで、なぜこんな補助金が出ているにもかかわらず、そこら辺のところは何とかならないかという声をたくさんお聞きしているんですけれども、その点についてもぜひお聞かせください。","respondent":"西島障害者福祉課長","answer":"その後、現在は大分、品川区の事業を後追いして、現在、ストレッチャーを持っていない区は３分の１ぐらいになってきたのかな、３分の２ぐらいが後追いで事業を実施してきたと、そのような経過もありまして、今、迎車料金、予約料金とをいただいているです。","id":"exchange-049"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"この料金が民間と変わらないというんです。先ほどから予算のことが言われていますけれども、財源は４３０万円ですので、これは区の１,４００億円の予算からすると本当にわずかな額なので、これは区がやるという方針を決めれば、そのやり方というのはどうにでもなるという額なんだと思うんです。そういう点からすると、ぜひ今日の採決をお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-050"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"だからメーターで走る分以上に１,０００円以上も片道でかかるという状況の中で、本当にどれだけ貴重なタクシー券であるのかなというところが私はすごく自分の実態と違うなというところで受けとめたので、その辺を考えて、ぜひ料金を上げていただきたいなと思うのと、今、鈴木（ひ）委員が質問した中で、本当に福祉タクシーのところの問題点というのも。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-051"}]},{"id":"topic-02","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"西本委員","kind":"確認","question":"リニューアルの工事期間というのはいつごろから始まるのかということと、ここは耐震とかの問題はどうなっているのかを確認したいんですが。","respondent":"諸岡児童課長","answer":"３月の中旬から下旬にかけて工事が完了する予定でございまして、４月１日からオープンできるようになってあります。工事期間は約半年間かかってあります。ここにつきましては、耐震というよりも老朽改修を中心に行って、それに合わせてティーンズプラザ整備を行ったものです。","id":"exchange-052"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"この資料はすごく簡単な資料で、４月１日からオープンということであれば、その状況がわかるような図面とかもぜひ出していただいて、イメージがわくような形での資料をぜひ出していただきたかったなというふうに思っているんですが、いかがでしょうか。","respondent":"諸岡児童課長","answer":"今回の改修につきましては、間取り等の変更はございませんで、今ある間取りどおりにフローリングの改修でありますとか、雰囲気をちょっと変えて壁を塗りかえたりとか、そういった改修ですので、内装の改修です。","id":"exchange-053"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"間取りは変更ないとしても、たぶん中身は変わってくると思うんですよね。それで、ちょっとここ、私は地元ではないのでちょっとわからない部分もありますので、要望です。今後こういうときは、ぜひ間取りとかも含めたわかりやすい資料にしていただきたいということでお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-054"},{"speaker":"鈴木（真）委員","kind":"確認","question":"１点だけちょっと確認させてください。４階の部分、遊戯室とルーフバルコニーと、さっきルーフバルコニーというお話があったんですけど、そのイメージが浮かんでこない。もともとはわかりますけど、安全性という面で、ルーフバルコニーをつけたことによっての危険はないのかという、その辺の確認だけ。","respondent":"諸岡児童課長","answer":"もともとここはルーフバルコニーとして使用しておりましたけれども、あまり雰囲気がよくないといいますか、きれいじゃなかったということでございまして、もともと安全性については問題ないところなんですが、そういう中高生が語らいができるとか、集まれる。","id":"exchange-055"},{"speaker":"三上委員","kind":"質問","question":"六つ目ということで、ここまでやってこられて、利用者の数としては、中高生の比率というのはどのくらい上がってきているんでしょうか。もともとこれは児童センターですから、小学生にとどまっているということで、そうすると、小学生の利用率も中学生が増えたら小学生が減ってきているというのか、現状の利用ぐあいというのはどんなふうになっているのか、ちょっと教えていただけませんか、全般的でいいです。","respondent":"諸岡児童課長","answer":"乳幼児につきましては、親子クラブとか親子サロン等乳幼児向けの施設としても整備を図ってまいりましたので、平成１３年が２万２,０００人、平成１７年が３万４,０００人と幼児だけ増えております。","id":"exchange-056"},{"speaker":"三上委員","kind":"質問","question":"乳幼児の皆さんというのは、大体午前中ぐらいが主なんでしょう。そうでもないのかな。小学生が少し減ってきている。円満にすべての年齢層を拡大しながらうまく遊んでいるという形で受けとめておいていいのかなと思うんだけど、どうなんですか、そこら辺。","respondent":"諸岡児童課長","answer":"小学生と高校生なんですが、高校生の活動に小学生が参加して、例えばバンド活動や何か、小学生バンドなんかをやっておりますが、それに中高生がかかわって教えてあげたりとか、そういった異世代の交流も行われておりますので、そういう意味では、小学生。","id":"exchange-057"},{"speaker":"飯沼副委員長","kind":"質問","question":"児童センターが子育ての拠点として、またこのところ重要視されているんですが、今ちょっと親子サロンの話も出たんですが、児童センターがティーンズプラザとして中高生のところを強化していく中で、やりくりがいろいろあると思うんですが、乳幼児のところがどうなっているのか、利用も増えていますけれども、あと予算的なところでよく教材費とかを増やしてほしいなという声も聞いているんですが。","respondent":"諸岡児童課長","answer":"ティーンズプラザにおきましても、親子サロン、あわせて設置をしております。","id":"exchange-058"},{"speaker":"西本委員","kind":"質問・要望","question":"既に２９名のというのは、これは４月からのお子さんということですか、それとも入っているのですか。どういう仕組みになっているのか。要は、在宅の方でも利用できるという状況なのか、そうすると、保育園というイメージがちょっと変わってくるかなというふうに思っているんですが、認証保育所なんかも、最近はそういう形で対象が広がってきているものなのか、教えていただきたいと思います。","respondent":"小林保育課長","answer":"もちろん、こちらのリーフレットにありますように、就労しない、あるいは一時的な保育というのは、通常の定員に空きのある範疇での対応になるかとは思います。","id":"exchange-059"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"この認証で、認証保育園が１０カ所目ということなんですけど、これで合計の定員数が認証保育園でどれぐらいになったのかということと、あと、今まで９カ所認証保育園があったと思うんですけれども、厚生委員会の中にこういう形でご報告いただいてきた記憶があまりないんですけど。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-060"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"全部されている。そうですか。わかりました。じゃあ、その点だけちょっとお聞かせください。","respondent":"小林保育課長","answer":"定員ですが、今回の３７名を加えまして、１０カ所、合計で３３０名となっております。","id":"exchange-061"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"それと、小山倶楽部、小規模多機能のほうなんですけど、この登録者の２０名というのは、範囲はどこら辺までということで考えられているのかと、送迎についてどうなるのかと、それからあと、この利用料なんですけど、１泊当たり４,５００円ということにこれだとなると思うんですけど、ショートステイの利用料と比べるとどんなぐあいなのか、ちょっとその点についても教えてください。","respondent":"蓼沼高齢福祉課長","answer":"利用料金、お泊まりの場合ですと、食事を含めると４,５００円、ショートステイとの比較は、ショートステイの場合、特養を利用した場合ですと、１日につき約７,２００円から１万円ぐらいの間というふうになっております。その１割ということになります。","id":"exchange-062"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"先ほど後期高齢者医療懇談会というのが関係者の声などを聞いていくところということで、中身については詰めているところということなんですけど、この制度そのものが区から離れて広域にあるということでは、区民の声が届きにくい、特に高齢者の意見が反映される仕組みがないということが問題だというのも、国会の中でもそこのところは検討していきたいという答弁があった議事録を私も読んだんですけど。","respondent":"冨岡高齢事業課長","answer":"一番最初にありますのは推薦ということで、それから、候補者が決まりまして、選挙を実施するということで、選挙結果を集約いたしまして、選挙長が当選人を決定するというような流れになっております。","id":"exchange-063"}]},{"id":"topic-03","title":"その他","agenda":"その他","exchanges":[{"speaker":"飯沼副委員長","kind":"質問・要望","question":"本間議員の質問の中で、今後小学校の改築に当たり、幼保一体化を進めていくというご答弁があったわけなんですけれども、次世代育成の支援対策推進行動計画の中にも、公立幼稚園と保育園の連携による新たな幼保一元化施設を検討しますという文書があるので、この辺が、今後どのように進められていくのかというあたりを教えていただきたい。","respondent":"高橋幼保一元担当課長","answer":"その他の７園につきましては、今後小学校の改築等、その地域の特性とかということもありますけれども、その７園につきましては、今後小学校の改築計画に合わせながら幼保一体施設の複合化として可能性があるかどうかということを検討してまいりたいと思っています。","id":"exchange-064"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"区民要求との関連でもう一点お伺いしたいのが、この間の世論調査の結果のところで、子育て支援のところに今後充実してほしい子育て支援というところでは、仕事と子育ての両立支援への要望が高いと、４２.３％が保育サービスを充実し、仕事と子育ての両立を支援する、この項目を４２.３％の方が選んでいらっしゃるんですが、幼保一体化を進めるに当たって。","respondent":"高橋幼保一元担当課長、小林保育課長","answer":"今後についての就労支援との関係ですが、品川区は平成１４年から幼保一元化事業に取り組んできまして、そして、幼稚園におきましても、私立は既に預かり保育等もしていますけれども、公立だけがやっていなかったという部分では。そういった需要に沿って、どういうサービスを提供していくのかという点、そしてまた在宅支援との関係、バランスも踏まえて、区民の保育ニーズに対応していく施策を展開してまいりましたし、今後も展開してまいりたいと考えています。","id":"exchange-065"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"本当に区民のニーズというのは多様だと思うんですね。その一つ一つに対応していくのは大変なことだと思うんですけれども、在宅とのバランスという意味でも、私は本当に保育園の充実が今、保育園の役割というのがすごく在宅の子育てでも求められているなと思うので、個々の対応というところはもちろんですけれども、就労支援の主力の保育園のところの充実を願っていきたいなと思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-066"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/443219?Template=document&Id=3170#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2007-01-01&TermEnd=2007-12-31"}],"sourceMeta":{"pages":0,"characters":64556,"voices":173}},{"id":"h19-20070227-8","meetingId":"h19-cm02","date":"2007年2月27日","dateIso":"2007-02-27","committee":"建設委員会","time":"午前１０時０３分～午後４時０１分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を99件抜き出しています。","topics":[{"id":"topic-01","title":"昨日、継続となっておりました第１５号議案、品川区手数料条例の一部を改正する条例","agenda":"昨日、継続となっておりました第１５号議案、品川区手数料条例の一部を改正する条例","exchanges":[{"speaker":"宮崎委員","kind":"質問","question":"ご苦労さまでした。全体で値上げ額が１.２倍ということなんですけれども、今の出された資料のところでは、飲食店の新規が１.９倍、喫茶店等は１.１９倍と。菓子製造が新規だと１.２倍ということなんですが、この中で大体一番多いケースというのは、どういうところなんですか。","respondent":"谷田部健康課長","answer":"許可されている業種が一番多いというご質問でございました。やはり現在食品衛生法で申し上げますと飲食店営業が１８年３月末現在で５,９８６営業所が許可を受けております。次いで多いのが喫茶店営業でございまして、１,６５４軒。","id":"exchange-001"},{"speaker":"宮崎委員","kind":"意見","question":"もしかしたらもうちょっと多くて、それを東京都が１.２倍にするか、ちょっと値上げ幅を圧縮したのかなというふうなイメージもあったんですけれども、今のこの説明だと、１.２倍のところ、菓子製造業で、この例の中では１.２倍を超えるものというものがちょっとないので、そうするとますますこの１.２倍の根拠というのは何なのかなという疑問がますます出てくるんですけれども。","respondent":"谷田部健康課長","answer":"１.２倍に極力抑えているのは、やはり一度期にご負担を求めるのは、許可を受けている皆さんにとって大きな負担になるということで、実際にかかる経費はこちらに算出していますけれども、ある程度判断、いわゆる激変緩和措置を入れまして１.２倍に極力抑えたということで。","id":"exchange-002"},{"speaker":"宮崎委員","kind":"質問","question":"きのうも聞いたんですけれども、東京都と行政相互が近くなきゃいけないというのはわかりますけれども、きのうから言っているのは、行政の足並みをそろえるのが、金額を一緒にするということとイコールなのかどうなのか。ほかの区はあっていないところもあるわけですよね。あえてこの金額を一緒にしなきゃいけない。例えば低く抑えられるんじゃないですかということなんですけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"},{"speaker":"宮崎委員","kind":"質問","question":"私の質問はこれで最後にしたいと思うんですが、きのうはコストを言っていました。でも少なくともこのコストを変えたこれは全く１.２倍の根拠はここからは出てこないということですよね。これが一番多い。大体職員を税金で雇っているわけですから、ここに税金で盛り込んでいくというのは、私はこのコストを出す根拠というのは、そもそも私はおかしいと思います。ちょっと最後は意見になりましたけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"中塚委員","kind":"質問","question":"今のご説明の中で、激変緩和の話が出ておりましたけれども、とどのつまりは、例えば飲食店営業（新規）のところで見ると、品川区は１万８,５７５円を負担していただくことが当然だという考えなんですか。喫茶店の問題だと、９,９６４円負担してもらうのは当然だという考えなんですか。そのこともちょっと教えていただけますか。","respondent":"谷田部健康課長","answer":"昨日来お話し申し上げているのは、１.１倍から１.２倍の範囲内で抑えるところは抑えていくということで、私ども、今回、手数料の改定を予定しているということでございまして、当然これを計算していきますと、高いところも出てくる。","id":"exchange-005"},{"speaker":"中塚委員","kind":"質問","question":"私が伺いたかったのは、激変緩和という話が今出たんですね。ということは、最終的には飲食店営業（新規）のところは、１万８,５７５円まで引き上げることが、いわゆる政策的な目標ということなのか、それとも違うのか、そこを伺っているんです、区の考えを。これについてのお答えがなかったので、教えてください。","respondent":"谷田部健康課長","answer":"今回、いわゆる１.２倍に抑えさせていただいたのは、来年このコストの形に近づけるために改正する予定があるかどうかというご質問だと思いますけれども、先ほども申し上げましたけれども、将来、社会的な情勢がどのように変化していくかどうか。","id":"exchange-006"},{"speaker":"中塚委員","kind":"意見","question":"答弁がはっきりしないんですけれども、激変緩和で抑えるんだと。結局、今の課長の説明だと、将来的には人権費も含めて１万８,５７５円、ここに向けて当然動いていくんだと。やっぱり今回の値上げの話でいけば、将来は上がってくる。これではとてもやっていけないですよね。特に同じラーメン屋にしたって、チェーン店ならまだしも、事業規模の小さいところほどやっぱり負担が重くなる。意見です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-007"},{"speaker":"本多委員","kind":"質問・要望","question":"きのうからもコスト、コストという話が出ていて、このように資料を出していただきまして、例えばこの一番目の飲食店、新規の場合ですと、コストが１万８,５７５円かかって、今回の改定額が１万８,３００円ということで、この実費のコストから改定額を引くと２７５円税金が投入されるということで、２番目の喫茶店につきましては、９,９６４円のコストに対して改定額が５,７００円ですから。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-008"},{"speaker":"井上委員","kind":"質問・要望","question":"更新の部分で報告数が、審査項目が違うことで更新の年数が違うということだったので、１、２、３の更新をこうやって出されるということは、項目が同じだというグループで出されたと思うので、更新の１、２、３の事業で教えていただきたいということと、もう１つは、増収である３２０万円は手数料として先ほどおっしゃった食品安全について評価されるようなことであれば。","respondent":"谷田部健康課長","answer":"許可をしなければ、飲食店営業をはじめとする営業ができませんので、それは私ども許可以外に、例えば先ほども言いました食品の食品衛生推進協議会を設けまして何回か会合を持つとか、それから食中毒を出さないための研修に対する支援ですとか。","id":"exchange-009"},{"speaker":"井上委員","kind":"質問・要望","question":"お金に色がついているわけじゃないので、手数料そのままということではないですけれども、こういうような形で負担を強いるということは、そのことが理解できるということが必要だと思いますので、そういう分では、こういったところを評価したというような政策をぜひ進めていってほしいということを要望して終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"},{"speaker":"宮崎委員","kind":"質問","question":"そのためにいるんですから。別に何か特別な費用がかかるというんだったら、それはわかるけれども、こういう行政側の人件費ですから、一体税金は何に使うのという議論になる。そういうことであれば、前のとおり、しっかり行政が今までどおりやるということになれば、今までどおりの対応でできるわけですから、今回の手数料条例の改正は、共産党は認められないということです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"}]},{"id":"topic-02","title":"第１５号議案に対して、昨日、自民党松澤委員から提案がありました附帯決議","agenda":"第１５号議案に対して、昨日、自民党松澤委員から提案がありました附帯決議","exchanges":[{"speaker":"松澤委員","kind":"質問・要望","question":"国が２３区について押しつけようとしているということで、この点に対しての法制度の整備を、各自治体の支援について、国に対して強く働いていただきたいということと、２点目は、同じくピアチェック機関、これが公平かつ的確に審査が行われるように、指定権限は都道府県知事にあるものですから、厳格に機関の監視・監督に努めるようにしていていただきたいということで、２つにまとめて提出しました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-012"},{"speaker":"阿部委員","kind":"質問","question":"品川区が働きかける相手としては、１の国というのはわかるんですけれども、２はやっぱり都道府県知事ということになるんですか。品川区だと、そっちだけなのかなと思ったんですけれども、ほかの道府県知事も入ってくるものですか。それともこれはこういう書き方をするものなんですか。よく知らないので、教えてください。","respondent":"片田建築課長、福田まちづくり事業部長","answer":"昨日の説明の中で、こういうピアチェック機関は各都道府県知事が指定すると。ですから、東京都でいけば都知事が指定すると。品川区が直接働きかけるのは、確かに都知事です。しかし、この問題というのは、先生方、おそらく共通に認識されておられるのは、一人東京都、一人品川区の問題ではなくて、全国的な問題だろうというふうにご認識があると思うんです。","id":"exchange-013"},{"speaker":"中塚委員","kind":"提案","question":"提案者にお伺いしたいんですけれども、１つ目の３行目から、自治体の責任と負担の増大に対して法制度の整備やという、この整備のところなんですけれども、僕のほうとしては、いわゆる確認審査そのものを民間に開放させることが、ボタンのかけ違いかなという思いなんです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-014"},{"speaker":"松澤委員","kind":"確認","question":"その辺をしっかりと担保されるような、しっかりと法整備をしてもらいたいということです。特に民間機関による建築確認なんていうのは全然こっちに話がないわけですからね。民間が建築確認を受けて、その民間機関がピアチェックでもって出すわけだから、それでやったものに関して、最終的な責任は自治体というのはちょっと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"},{"speaker":"宮崎委員","kind":"意見","question":"今の、要するに民間がやったやつも、要するに自治体が責任を負わなきゃいけないと。今のそういう仕組みを変えていってほしいということですよね。ちょっと文書だけ読むと、そこのところが何かストレートに伝わってこないので、今の説明があわせてあれば。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-016"},{"speaker":"井上委員","kind":"質問","question":"質問ということでお願いしたいんですが、２行目の指定構造計算適合性判定機関設置などというのは、それは自治体が設置するということで負担増ということですか。これは自治体が設置をするものだから、負担が多くなります、だからという流れですか。それともこの「など」の仕組みがちょっとわかっていないので。","respondent":"片田建築課長","answer":"ほんとうは東京都が機関として位置づけられれば、よろしいんでしょうけれども、東京都自体もそういうことができませんので、今回の法整備の中では、各自治体が自前のものが設置できればよろしいんですけれども、それができないために、民間機関として手を挙げたところ。","id":"exchange-017"},{"speaker":"中塚委員","kind":"確認","question":"質問なんですけれども、ピアチェック、僕もまだなかなかどういうものなのかよくわからない部分があるのでお伺いしたいんですけれども、都道府県知事のもとに置くんですけれども、議会の審査といいますか、報告を受けるといいますか、そういう関係にピアチェックという新たな確認事務ですとかそういうものというのはどんなふうに、区議会なのか、都議会なのか、そこも含めてよくわからないんですけれども。","respondent":"片田建築課長","answer":"基本的には議会のほうの審議をもってというようなことは記載されてございませんので、いろいろな経過の中で報告することはあろうかなと思いますけれども、設置者である知事の判断の中で進めるというものです。","id":"exchange-018"},{"speaker":"宮崎委員","kind":"意見","question":"先ほどの松澤委員の説明ではわかったんですけれども、本来であれば、ストレートにそういう表現にしたほうが何かいいとは思うんですけれども、ちょっとここのところでこういうふうに今の説明も含めたところではわかるんですけれども、本来であれば、もうちょっと今の仕組みで自治体にそのまま来るのが疑問だというふうな、何かそういうふうな文言があればなと。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-019"},{"speaker":"宮崎委員","kind":"意見","question":"問題意識はわかるんだけれども、そういう問題意識であれば、ストレートにそういう表現のほうがいいかなというふうに。このまま文書は文書でいきますから、今のこの議論がそのまま使わないから、どんなものかなと。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-020"}]},{"id":"topic-03","title":"平成１８年陳情第１２号、（仮称）戸越６丁目ワンルームマンション建設に関する陳情","agenda":"平成１８年陳情第１２号、（仮称）戸越６丁目ワンルームマンション建設に関する陳情","exchanges":[{"speaker":"井上委員","kind":"質問","question":"このケースだけに限らず、何割方近隣商業のほうに多く建ててれば、隣が一種住居地域でも問題ないとか、そういう意味では、住民にいろいろな部分でこういう問題が起こる可能性がありますけれども、そういう用途地域の緩衝エリアみたいなものを検討するというようなことは、品川区のまちづくりの中では、考えとしてはないんでしょうか。","respondent":"片田建築課長","answer":"今、用途地域の境の問題ですけれども、確かに、委員からお話があったように、道路があって、道路沿いの近隣商業地域、あるいは後背地といった場合には、今回のように、近隣商業地域のほうに建物が建ってなくて、後背地への影響というのは確かにあるということは認識しております。","id":"exchange-021"},{"speaker":"中塚委員","kind":"質問・要望","question":"関連なんですけれども、ワンルームマンション、この陳情ですけれども、今回が初めてじゃないんじゃないかなと実感をするんです。やっぱり商店街のマンションというのは、新たな対応策とか、対策とか、いろいろ求められているのかなと思うんですけれども、もし何かお考えがありましたらお聞かせいただけますか。","respondent":"齋藤住宅課長","answer":"今後、一定の方向性につきましては、地域に溶け込むような形で維持できないか、こんなような形で一定の誘導ができないかということは検討してまいりたいと思っていますし、現に検討しております。","id":"exchange-022"},{"speaker":"中塚委員","kind":"質問","question":"最後に、地域に溶け込めるような検討をしているというお話なんですけれども、これは何か具体的なところで、今もし考えていることがありましたら、そこだけもう少し教えていただけますか。","respondent":"齋藤住宅課長","answer":"ただ、どこまで、どうするかについては、まだ検討中で、いろいろなものを考えながら、総合的に考えていきたいと思っています。","id":"exchange-023"},{"speaker":"宮崎委員","kind":"意見","question":"ちょっと１点だけ聞きたいんですけれども、今、話し合いをやっているところだということなんですけれども、先ほどの住民の方々とは、３分の２ぐらいは合意が、というお話だったんですけれども、当初、いわゆる住民の会というふうにはっきりしていたかどうかわからないんですけれども、そうすると、今は会というのがあまり体をなさなくて、個別でやってきていると、そういう段階なのか、そこら辺がわかったら。","respondent":"齋藤住宅課長","answer":"説明し難いところでございまして、会としての固まりはあります。固まりの中でいろいろご要望もあるので、いろいろなお話をしてほしいと事業者に働きかけていらっしゃる方もいらっしゃいます。","id":"exchange-024"},{"speaker":"阿部委員","kind":"質問","question":"現在のところ、大体何戸ぐらいが参加されているか教えてください。","respondent":"齋藤住宅課長","answer":"本件におきましては、２０人ぐらいの方が、当初、会のような形で参加されておりました。","id":"exchange-025"},{"speaker":"阿部委員","kind":"質問","question":"そうすると、その会以外にも、個別に住民の方々と交渉されているという理解でよろしいんでしょうか。","respondent":"齋藤住宅課長","answer":"その後、四、五人新たに事業者への、我々に対しても一定の、これもまた言いにくいんですけれども、補償という形で言いに行った方もいらっしゃるというふうに聞いております。","id":"exchange-026"},{"speaker":"松澤委員","kind":"質問・要望","question":"ワンルームがいけないなんていうのは、何でなのかと思うぐらいで、それぞれ独身で住む方だっているわけですから、それを否定しているのかなというふうに思うぐらい、いろいろな意味では、やっぱりどんどん話し合いをしながら、いいものをつくっていただきたい。結論的には、まだもうちょっとで妥協すべき話し合いをしているというのですから、推移を見守るしかないと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-027"}]},{"id":"topic-04","title":"平成１９年請願第１号、目黒線立体交差事業に伴う旧西小山四号踏切上車両通行の代替案に反対する請願","agenda":"平成１９年請願第１号、目黒線立体交差事業に伴う旧西小山四号踏切上車両通行の代替案に反対する請願","exchanges":[{"speaker":"井上委員","kind":"質問","question":"平成６年５月から９月にわたって地域住民に説明をされたということが一番最初のスタートだと思うんですけれども、その部分で、地元の方に伺うと、この５回の説明会が場所が違うところで説明をされていて、地域ではなかったような話を伺ったんですが、この５回の説明会をどこでされているのかということが１点。","respondent":"浜脇街路事業担当課長","answer":"２点目の、説明会の中で十分にと言いますけれども、私どもとすれば、反対住民は特に品川区方のほうが多い状況がございましたので、これらについては、日ごろから、代替施設全体を図示しながら説明をしています。","id":"exchange-028"},{"speaker":"井上委員","kind":"質問","question":"住民の方たちは、５０ｍ先に行けば道路がちゃんとあるのに、どうしてここにつくるんですかということも含めて言うんですけれども、この代替道路は、住民にとって大変重要な道路であるという認識があって、１日１０３台ぐらいの車が通るということでは、私はよくわからないんですが、普通に考えると、１日１０３台ぐらい通る道路というのは、大変重要な、必要性のある道路ということなんでしょうか。","respondent":"浜脇街路事業担当課長","answer":"申しわけございません。あの道路に１０３台ではなくて、地区全体、今、私どもで資料を出しましたけれども、地区内ですけれども、その中で１０３台があっちへ行ったりこっちへ行ったりするということです。","id":"exchange-029"},{"speaker":"井上委員","kind":"質問・要望","question":"平成１５年の住民からのまちづくり事業部長への質問書の中に、この代替案の道路は危ないから通すべきではないという声に対して、前の部長は、その要望に対して、「これを真摯に受けとめ、事業者間、東京都、品川区、目黒区、東急電鉄で慎重に検討した結果、さまざまな安全対策を講じることにより、車両を通行させることは可能であると判断したところです」という回答が来ているんです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-030"},{"speaker":"井上委員","kind":"質問・要望","question":"車を通すためだけに、いろいろな対策をして、住民に対してどうかというところでは、地域住民が本当に求めているかというところは、再三声聞いて計画変更をするというようなことを、一番最初に言われながら、住民たちにとっては、そういう声が一切届かないということも、いろいろな回答書なんかを見ると明らかなので、下ってきたところの五叉路というか、四つ角は、信号機もつけられないような状況だし。","respondent":"浜脇街路事業担当課長","answer":"今の自転車の話なんですけれども、きのうも歩いていただきましたけれども、今回、自転車は歩道のほうに行っていただいて、押してくださいというルールになっております。","id":"exchange-031"},{"speaker":"中塚委員","kind":"質問・要望","question":"僕が言うのが違っていたら教えていただきたいんですけれども、つまり、ここは前に道が通っていたときは、品川区からは５４０台、目黒区からは４０台でしたか、そういう時期があったと。交通量から、代替道路をつくる基準みたいなものというのはあるんですかね。これだけの交通量が予測されているんで、代替道路をつくらなければいけませんと、そういう基準というのがあるんですかね。その説明を、ちょっと。","respondent":"浜脇街路事業担当課長","answer":"安全かどうかですけれども、これにつきましては、私どもとすれば、道路をつくる際には、道路構造令等の法令、それから当然、安全施設について所轄警察との協議を十分に重ねまして、これが一番安全策であろうということで、最大の安全策をとっていると考えております。","id":"exchange-032"},{"speaker":"中塚委員","kind":"質問・要望","question":"結局、さっき質問した、交通量を減らすための道路をつくる基準というものは、じゃあ、ないということなんですかね。では、この道路をつくることは、一般車両にとって必要なのか。緊急車両の話が出ましたけれども、シミュレーションの結果をまた伺いたいのは、ここを通るのと、通らないのと、実際に何分違うんですか。先ほど、緊急車両の話も出ていたので、何分違うのか、その際の基準も教えていただけますか。","respondent":"岩田まちづくり事業部次長","answer":"これはかなり年月が経っておりますけれども、もともと連立事業を、いろいろ高さをどうするかということを検討したときに、本来であれば、全部の道路と鉄道の交差がすべて立体化されれば一番よかったわけですけれども、この地区においては、どうしても数カ所。","id":"exchange-033"},{"speaker":"中塚委員","kind":"質問","question":"今の説明は説明として、今までの経過は伺いましたけれども、私が聞いたのは、さっき緊急車両の話をおっしゃっていましたので、そのシミュレーションの中で、これがないと、こっちから向こうへの時間がどのぐらい変わるのか。さっき、代替道路をつくる主な理由が、緊急車両の通行、一般車の通行という２点をおっしゃっていたので、そこを伺っているんですけれども。","respondent":"岩田まちづくり事業部次長","answer":"だから、おそらく、今の数十台というは、この沿道にどうしても必要な方とか、サービス車両しか通らない。現実に、ここの道路だけじゃなくて、この周り自体が輻輳した一方通行で、荏原地区はよそものが進入できないような道路形態にしてあるんです。","id":"exchange-034"},{"speaker":"中塚委員","kind":"質問","question":"地域の方に伺いますと、この道がなくても、ほかに渡れるということもおっしゃっていましたし、通り抜けができなくなったから、今、車両が１０３台ぐらいなんだと。雪が降ったら、アイスバーンにならないように除雪をやるっていうけど、いちいちここへ除雪に行くわけですか、雪が降るたびに。そうではないですよね。だから、今の区の説明では、やっぱりここを道路にする必要があるとは感じられません。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-035"},{"speaker":"藤田委員","kind":"質問・要望","question":"これは、今、まちづくり事業部次長からご説明があったとおりに、当初からの計画なんですよね。そうしたこともあって、通過できたときは、道路ですから、人や自転車が歩いている中に車が通っていた。それを今回、今までの要望があって、車道と歩行者、自転車を分けたということです。ですから、雪が降ったらどうのこうのという話がありましたけれども、ここだけではない。そういうことでよろしいんですね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-036"},{"speaker":"宮崎委員","kind":"質問・要望","question":"だから今の数がこんなものだということは、いつまで続くのかというふうに思うんです。前の６００台ぐらいの交通量に戻ってくるんじゃないかという心配は、住民にとってみれば、当然あると思うんですよ。それから、いわゆる通り抜けをどういうふうに規制していくのかというところは、ここのところはどういうふうな考え方があるのかというのがあれば、ちょっと説明していただきたいと思うんです。","respondent":"岩田まちづくり事業部次長","answer":"沿道の方は、今まで、自分の車しか通らなかったところで、人が入ってこなかったところに、少ないと言えども、通り抜けの車が若干入っていますので、そういう面でのご不安というのはわからないでもないですけれども、そういった安全対策については、今後も様子を見ながら。","id":"exchange-037"},{"speaker":"宮崎委員","kind":"質問","question":"スピードも相当出していたんですけれども、よく事故があったんです。ですからこういう形状の下り坂となると、私自身の経験からいくと、非常に危険だという感じをしています。だから、例えば速度表示が２０kmとなっているからいいかどうかと、またそんなことじゃ、運転手というのは、私も運転しますけれども、私は守りますけれどもね。ちょっと意見になりましたけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-038"},{"speaker":"井上委員","kind":"質問","question":"先ほど、藤田委員がおっしゃったように、ここは高台になっているというところで、住民の方に伺うと、この地域では、上のこの道路というのが唯一の平坦道路であり、自転車と歩行者の方たちが、目黒区立第九中学校から、子どもたちもこの道路を使って帰ってきて、ここが唯一平坦なところで、自転車とか通る人たちが一番使うところであるということが、地域の方の認識なんです。","respondent":"岩田まちづくり事業部次長","answer":"そういう面では、もう供用開始をしておりますので、歩道はまだ未整備なんですが、地域の実情、今後の利用状況を、区もきちっと見ながら、本当に対策の必要があるんであれば、これはやらなきゃいけませんから、そういう面で、今後も地域の方の意見は聞きながら。","id":"exchange-039"},{"speaker":"井上委員","kind":"質問","question":"リスクがあるかどうかというところについての答弁がないので、ここの部分でとまらなかったり、リスクがあって、もし人身事故が起きた場合には、道路管理者として責任を負わなければいけないので、税金で道路をつくっていながら、そういう話にもなるかと思うんですけれども、そこについてはどうですか。","respondent":"岩田まちづくり事業部次長","answer":"引き続き利用者の利用勝手がどういう使い方をされるかというのは、こういう輻輳した変則交差点ですから、そういうものも、今後きちっと利用実態を見ながら、必要な対策がもしあるのであれば、十分に対応していくという姿勢ですので、ご理解をお願いします。","id":"exchange-040"},{"speaker":"阿部委員","kind":"質問・要望","question":"ただ、当然、大変難しい地形なので、やっぱり危険性を感じられるとか、周囲の住民の方が何となく不安感を持つというところも、また推測できるところではありますので、さっきもまちづくり事業部次長もおっしゃっていましたけれども、今後の運用を見て、それこそ危ないとか、あるいは、大変に予想に反して通行量が増えて危ないとか、そういう新しいニーズができてくれば。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-041"},{"speaker":"本多委員","kind":"意見","question":"できる前と、できてからの状況と、いろいろなシミュレーション、そして状況をもう少し見ていきたいと思っています。状況としては、もう十分に昨日の視察で見させていただいて、結論を出してもいいという判断もありましたが、もう少し状況を見たいと考えていますので、継続でお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-042"},{"speaker":"宮崎委員","kind":"意見","question":"つくってみて、今の状況がこういう状況なので、将来的にどうなるのかというのは、はっきり言ってまだよくわからないところがあるというのがわかるんですよ。皆さんの意見の出ぐあいで考えているんですけれども、うちのほうはやっぱり、こういう意見をしっかり担保してというか、そういう意味では、採択を主張したいと考えています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-043"},{"speaker":"藤田委員","kind":"質問・要望","question":"一つだけ、危険だ、危険だとおっしゃっていますので、余計な建造物は取り除いていただいて、すっきりした見通しのいい道路にするということを、今後、ぜひ取り組んでいただきたいなと考えています。きょうのところは、継続で結構です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-044"},{"speaker":"阿部委員","kind":"意見","question":"大変悩ましいところではありますが、ここで採択を取ってもいいのかなという気持ちも半分はあるんですけれども、供用開始してまだ時間がないということで、この道路が、今後どのように使われていくかという観察期間という気持ちも含めまして、今回のところは、一たん継続ということです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-045"},{"speaker":"井上委員","kind":"意見","question":"たまに行ってみたような人たちではなくて、日々暮らしている方たちがそういうことを危惧しているということは、この請願でも、視察に行っても、当事者の方々にお話を聞いてもよくわかりましたので、住民の皆さんの意向を反映させたいと思いますので、採択をしていただいて、結論を出すということでお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-046"},{"speaker":"中塚委員","kind":"質問・要望","question":"説明の後半のほうに、北側の隣地との境界線の話の中で、民法上は５０cmというお話、それがどういうものなのか、教えていただきたい。目の前に２０ｍ強の建物があるわけですから、圧迫感を感じるとおっしゃるのは、当然だろうなと思うんですけれども、それにしても５０cmしかないというのは、いくら何でも狭いなという感じがするんです。","respondent":"齋藤住宅課長、片田建築課長","answer":"民法のことについてご説明します。民法の相隣関係でございまして、隣地とは慣習がなければ５０cm離しなさい。５０cm隣地境界から離さないでつくった場合は、建築の差しとめもできますと、こういう条文があるんです。ただ、建築基準法と民法は法体系が全く違うもので、契約上、あるいは民事的な対応、法令上の制限とは全く異なります。","id":"exchange-047"},{"speaker":"中塚委員","kind":"質問","question":"例えば、こんなことを聞いてもあれでしょうけれども、形を目いっぱいやるということは、業者とは、そういう考えにはならないんでしょうかね。何か、経済性というか、目いっぱいの建物で、近隣の方への配慮が感じられないんですけれども、何か業者から聞いていることがありましたら、教えていただけますか。","respondent":"齋藤住宅課長","answer":"真ん中がＡ棟で、次がＢ棟で、部屋のつくりを一定にして、売りやすい大きさにしていきますと、Ａ棟のほうは、隣地と５０cmのところから建物を建てないと、部屋の数、大きさが取れないということだと思います。","id":"exchange-048"},{"speaker":"阿部委員","kind":"質問","question":"今、請願が出ている方のアパートというのは、Ａ棟の北側だと思うんですけれども、もしご存じでしたら、このアパートから隣地境界線までの距離はどのぐらいなんですか。","respondent":"齋藤住宅課長","answer":"わかりません。","id":"exchange-049"},{"speaker":"阿部委員","kind":"質問","question":"現地を見た感覚だと、そちら側も相当詰まっていたという感触を持つんですけれども、あれだけ詰まって建てられるというのは、これが準工業地域だからなんですか、それとも、どういう地域でも詰まって建てられるんでしょうか、教えてください。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-050"},{"speaker":"松澤委員","kind":"質問","question":"何回かお話し合いをされているみたいで、ある程度階高も低くなっているということですし、目隠し等々もされているということですから、一生懸命やっていただいているのかなと思っているところですけれども、こういうマンションの請願を出されたんですけれども、やっぱりちょっと推移を見たいと思います。今回は継続にしていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-051"},{"speaker":"宮崎委員","kind":"意見","question":"結論から言いますと、継続でしようがないとは思いますけれども、隣との間がこれだけとか、これはちょっと、不安というのは当然だと思うんですよね。当たり前のことが、本当に私は、建築行政そのものが住民から支持が得られなくなっちゃうんじゃないかと思うんです。それはちょっと感想ですけれども、この請願自身も、今、話し合いを進めているということですので、継続でしようがないかなと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-052"},{"speaker":"藤田委員","kind":"意見","question":"私も、きょうのところは継続ということでお願いしたいんですが、今まで駐車場であったところが、７階、８階というものが１ｍも離れずに建ってしまうということは、住民の皆さんの気持ちはよくわかります。ですので、粘り強く建主との交渉をお願いしたいと考えていますが、きょうのところは、継続ということでお願いいたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-053"},{"speaker":"阿部委員","kind":"意見","question":"確かに、これまでとあまりにも環境かがらっと変わるということで、住民の方のそういう声というのは、確かにそうだなろうと思う気持ちは十分にありますが、話し合いを進めているようですので、これはまだ当事者間の話し合いの中でさらに改善がなされるかなと思いますので、そういう意味では継続に。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-054"},{"speaker":"井上委員","kind":"意見","question":"結論から言えば継続なんですが、まちづくりを考える中で、民法上の５０cmというところでは、ほかの方たちのところでも、建てられてしまって、後に室外機だとか、排水管だとかがそこにつけられるという矛盾を感じている人たちがたくさんいるということは現実なので、何かこれを仕組みとして対応できるものがないのかなと思います。どこかで、だれかが何とかしたいという項目でもあると感じています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-055"}]},{"id":"topic-05","title":"平成１９年請願第８号、東急目黒線立体交差事業に伴い新たに発生した騒音の対策を求める請願","agenda":"平成１９年請願第８号、東急目黒線立体交差事業に伴い新たに発生した騒音の対策を求める請願","exchanges":[{"speaker":"井上委員","kind":"質問","question":"対策はとるということが明らかになっているけれども、住民に対して具体的なものが教えられていないということで、ぜひ説明をしてほしいということに対して、説明会をする予定はない、個々に対応するとおっしゃいましたけれども、なぜ説明会をしようとされないのか、その点を教えてください。","respondent":"浜脇街路事業担当課長","answer":"実は、いろいろな説明会等を二十何回もやったんですが、ちょうどそのときに、これまでの具体的な説明はしないで、個別に近隣に、こういう工事をやるということで、工程表を渡して、やっているですので、それをそのままやることで済むというふうに考えてあります。","id":"exchange-056"},{"speaker":"井上委員","kind":"質問","question":"工程を言っているわけではなくて、工程は、チラシをまいてどうのこうのという説明ですけれども、そこのところが、説明を拒否される理由は何らないと思うんですけれども、ここについては、今後、お互いに、行政も、事業者も、区民も協力していい方向に進んでいきたいんだという趣旨なので、説明会をすれば別によろしいんじゃないかですか。","respondent":"浜脇街路事業担当課長","answer":"住民のほうにも、そういったことで、私どもにいち早く苦情が来まして、対応しているわけですので、当然、私どものほうとすれば、住民に対して説明責任というのがありますので、これまでも、こういう対策、いつまでにこういうふうにやりますということをやっていますので。","id":"exchange-057"},{"speaker":"井上委員","kind":"質問","question":"すればいいじゃないですかという、単純なところなんですけれども、それをしませんと言い切られていること自体、説明責任があって、納得をしていただくことのほうが、その先いろいろなトラブルがないわけですから、してほしいということに対して、声があったら行きますよと、個々ではなく団体でも、周辺の皆さんに行きますよということでよろしいと思うんですけれども、なぜそれを。","respondent":"浜脇街路事業担当課長","answer":"今、工事途中でこういうことが起きておりますけれども、これについては、工程が進めば目隠し板や防音壁がつくですので、改めて説明会というものをする必要はないと。","id":"exchange-058"},{"speaker":"中塚委員","kind":"質問・要望","question":"今の話の中で、途中から出てきた意見を聞かない理由は何なんですか。今の説明では、いや、途中からの意見は聞かないですというのは、その理由は何なのか、ちょっと伺いたい。それから、一緒に聞きます。７９dBから７３dBになったと言いましたけれども、それは２５ｍ離れた地点ですよね。一番近いところ、住宅のあるところでは調査はされているのか。どんな音なのか教えていただきたい。","respondent":"浜脇街路事業担当課長","answer":"途中での意見ではなくて、私どもは最初から、こういうことは取り付けるということでやっておりましたし、そういう説明をさせてもらっていますです。","id":"exchange-059"},{"speaker":"中塚委員","kind":"質問","question":"先ほどから聞いていますけれども、今ある区の考えでなぜ説明会を開かないのか、全く説明になっていない、まちづくり事業部というものはそういう部なんですか。日ごろは、住民の方々のご意見を伺いながら云々と言っていますけれども、かたくなに説明会を開かないという、その意味がわからないので、特別な理由があれば、あえて教えてください。なぜその気持ちがわからないのか、教えていただけますか。","respondent":"浜脇街路事業担当課長","answer":"説明会の意味なんですけれども、私どもと事業者側も何回かの説明会、あるいは反対者側との話し合いの中で、実は平成１７年度の終わりごろに要するに脅迫的なものがあって、それからそういった説明会については行わないと決めたという経緯があります。","id":"exchange-060"},{"speaker":"中塚委員","kind":"質問・要望","question":"説明会を開かない理由がころころ変わるので、よくわからないんで、もう一度整理して教えてください。要は、説明会を開かない理由は何なのか、もう１回整理してお答えいただきたい。それから、防音工事については、やっぱり最善の策を取り入れていただきたい。それを最後に教えてください。","respondent":"浜脇街路事業担当課長、岩田まちづくり事業部次長","answer":"それから当然、防音壁につきましては、今言われましたけれども、私どもとすれば、最善策といいますか、一番いいものを使って、近隣へご迷惑がかからないように、それについては今後とも検討する材料だと認識しておりますので。今回の場合は、沿線住民の方が現実に騒音問題で困っておられるということですから、それに対しては、これこれこういう対策を今考えておりますとか。","id":"exchange-061"},{"speaker":"井上委員","kind":"質問","question":"今の防音壁の効果、最終的にはまだ先の工事だということなので、その工事があって、まだそれでは対応が不十分だということであれば、その後の対策というのはきちんとやりますということでよろしいでしょうか。","respondent":"浜脇街路事業担当課長","answer":"それを含めて、騒音のレベルの問題というのはちょっとわかりませんけれども、当然、そういうご質問に対してはお答えするように、やはり皆さんにある部分迷惑をかけていることですので、迷惑が減るような努力は、今後してまいることは事実です。","id":"exchange-062"},{"speaker":"宮崎委員","kind":"意見","question":"歩道橋のほうも、きのうも歩いてみて、大分音がするので、私は、どうして鉄板でやったのかなという、そういう気持ちが強いんです。今、いろいろ安全な対策をとってきたというところなんですけれども、今時点でどんな対策が考えられているのか。話し合いの進め方と、今実際に考えられることなのか、その効果はどういうふうなものなのかということが、わかったらお願いします。","respondent":"浜脇街路事業担当課長","answer":"今、検討している最中ですけれども、対策ということでは、階段の音が大きいといいますか、しますので、それについては、今敷いてありますけれども、ゴムのマットを厚くするというようなこと、それから、階段の裏が太鼓状になっていますので。","id":"exchange-063"},{"speaker":"宮崎委員","kind":"質問","question":"もう一つ、先ほどの音なんですけれども、７９dBから７３dBというお話だったんですけれども、もうちょっと聞きたいんですけれども、７９dBというのは、いつはかって、７３dBというのはいつなのかということ。それから、やっぱり急行が入っているときといないときは変わってきますので、実際に急行での音なのか、どうなのか。同じ各駅だけの比較なのか、そこの部分はどうですか。","respondent":"浜脇街路事業担当課長","answer":"もう一度言いますが、工事前に調査したのが平成２年３月です。それから、地下化後にやったのが、平成１８年１２月です。それは急行運転のところでやって、今言ったように、前回が７９dBで、今回が７３dBだったという結果が出ております。","id":"exchange-064"},{"speaker":"宮崎委員","kind":"確認","question":"確認しますけれども、前回の７９dBは当然各駅停車ので、今回の７３dBは急行電車の通過のときにはかったものだと。実際の住民の感情に合った測定になっているのか、どうなのか、そこら辺のところはどういうふうにお考えなんでしょうか。","respondent":"浜脇街路事業担当課長","answer":"新しい車両で運航したというようなことで、若干音質の変化があって、私どもが考えている音質より、皆さんがこれまで聞いたのと違った音質というふうに受けとめた方もいるかなとは思います。","id":"exchange-065"},{"speaker":"宮崎委員","kind":"質問・要望","question":"やっぱり今の騒音のはかり方というのは、ある意味では今の機械のレベルでいくものですから、実際に住民というか、人間の感覚とはまた違うレベルがありますので。それから、ちょっと先ほどの話し合いというのが、非常にかたくなかなという感じもするんですよ。そこら辺のところの住民の感覚、実際に受けとめている感じというのを直に聞いていくという、そういう姿勢を強く求めたいと思うんですね。","respondent":"浜脇街路事業担当課長","answer":"先ほども、防音壁と目隠し板のところでも申し上げましたように、私どもとすれば、最善の方法をとっていくのが私どもの使命ですので、そういういった意味では、一番ご迷惑のかかる方に対してやっていく、詳細な説明とか、対応とかが必要ということは考えておりますので。","id":"exchange-066"},{"speaker":"藤田委員","kind":"質問・要望","question":"きょうのところは、継続ということで。１軒１軒、周辺住民の家でも、これまで感じ方の違い、また地形等もありますので、その辺の説明をぜひ丁寧にやっていただきたいということを要望します。きょうのところは、継続でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-067"},{"speaker":"阿部委員","kind":"質問","question":"先ほど来伺っていて、区側でもいろいろと対策に力を注いでいるという印象を受けました。ただ、説明というのは、単に区の思いを伝える、あるいは区の工事の内容を伝えるという一方通行ではなくて、むしろ住民の日々の苦しみに耳を傾けるということを含めての説明というものを続けていかれることを期待しつつ、今回は継続ということでお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-068"},{"speaker":"井上委員","kind":"質問・要望","question":"今、本当にこれからそういう意味で住民に対応していくということがわかりましたので、さらに住民の方たちの要望を応援する意味で、結論を出すということで、採択をするということでお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-069"}]},{"id":"topic-06","title":"を行います。(1)の品川南ふ頭公園の都市計画決定","agenda":"を行います。(1)の品川南ふ頭公園の都市計画決定","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"平成１８年１２月２０日の住民説明会では、何名参加で、どんな意見が挙げられたか。それから、今後の予定のところですけれども、東京都から移管をされるときは無償だというお話を伺っているんですけれども、隣接地の買収というのは、大体幾らぐらいで、どこから買うとかということ。あわせて、多目的広場に整備する工事の費用、幾らぐらいなのか、ちょっと教えていただけますか。","respondent":"松代管理工事課長","answer":"１２月２０日に開きました説明会、夜の７時から８時半という予定で開催しましたが、残念ながら、参加者はございませんでした。広報等によりまして、説明会を事前に呼びかけをしたところです。","id":"exchange-070"},{"speaker":"中塚委員","kind":"質問・要望","question":"説明会は参加者はなかったけれども、団体の中で意見を伺っているというお話だったんですけれども、その中でもどんな意見が挙がったのか、教えていただきたい。こちらの財布の準備ぐあいといいますか、見込みといいますか、大体幾らで調節しようかなというのがありましたら、教えていただけますか。","respondent":"松代管理工事課長","answer":"スポーツ団体等の懇談会の中では、日ごろから申請をするんだけれどもなかなか取りづらいといった点で、何とか取りやすいような、また枠を広げられるようなことができないかというようなことがございました。","id":"exchange-071"}]},{"id":"topic-07","title":"の北品川五丁目第１地区市街地再開発事業に関する都市計画素案","agenda":"の北品川五丁目第１地区市街地再開発事業に関する都市計画素案","exchanges":[{"speaker":"井上委員","kind":"質問","question":"普通だったら、ここは都市再生特別地域とかにしなくても、再生地域として、開発地域ということを指定されていると思うんですけれども、赤く指定するということは、どんどん最優先にいくとか、優先的に公費がここに補助されていくとか、区としてはいろいろなメリットがあると思うんですけれども、そういう状況を教えてください。","respondent":"青木都市開発課長","answer":"ですので、先ほどご説明しましたとおり、今後は、この説明会、あるいはこの素案がまとまったことを受けまして、今度は東京都、あるいは品川区という行政側での都市計画手続に進んでまいります。そのための近隣の意見集約をしたいということで、お願いした説明会です。","id":"exchange-072"},{"speaker":"阿部委員","kind":"質問・要望","question":"これは一応民間の開発という形にはなっておりますが、しかし、公共性の高い再開発ですし、区側の出席があってもよかったのではないかと、私は感じているんですが、区としては、例えばこういう説明会に出席するときの基準ですとか、こういうところには、区としては行かないんだとか、そういう判断があって欠席、あるいは出席していらっしゃらなかったのか、その辺も伺ってみたいと思います。","respondent":"青木都市開発課長","answer":"２点目の、御殿山小学校に関する説明ですけれども、これはあくまでも事業予定者といいますか、準備組合という任意の地元の方々が集まった組合が事業計画の案をまとめて、近隣の方々にご説明する内容ですので、御殿山小学校については区の教育委員会の所管といいますか。","id":"exchange-073"},{"speaker":"阿部委員","kind":"質問・要望","question":"教育委員会の所管であるから、この事業者の説明では説明できないと。住民にとっては、そういうのが縦割りというものに映るんだろうなと思います。ですから、住民説明会という場をせっかく設けるのあれば、それを最大限活用できるような形で柔軟に考えていただきたいと思いますが、いかがでしょうか。","respondent":"青木都市開発課長","answer":"繰り返しになりますけれども、準備組合という地元の方々の計画案をご説明する機会でございまして、それに対して、区としても協議を進める中で、御殿山小学校への影響が多いということは、過去にもう既に認識しておりまして。","id":"exchange-074"},{"speaker":"中塚委員","kind":"質問・要望","question":"幾つかまとめて伺いたいと思うんですけれども、まず、この北品川五丁目の再開発なんですけれども、都市再生特別地区、赤いほう、総事業費は幾らなんですかね。それから、補助金の投入ですけれども、どういう補助金になるのか、そしてその金額も教えていただきたい。具体的に教えていただきたい。","respondent":"青木都市開発課長","answer":"従前は、２ページの絵にありますＤ棟の東側に細い道路が通っておりまして、それが御殿山小学校の敷地を二つに分断しているんですけれども、今回の再開発事業によりまして、ここを一体的な活用ができることによって、この道路は廃道できる見込みです。","id":"exchange-075"},{"speaker":"中塚委員","kind":"質問","question":"つまり、きょうの資料の２７ページを見て、等時間を見ますと、丸々すっぽり５時間日影になるように見えるんですね。それから、教育委員会にも相談したというお話がありましたけれども、じゃあ、教育委員会はこの日影の影響をご存じなんですかね。それを踏まえて、Ｅ棟を下げてＤ棟を上げるというこの計画に、教育委員会もいいですよと、その辺の協議のぐあいを教えてください。","respondent":"青木都市開発課長","answer":"委員、ご指摘のとおり、２７ページをごらんください。等時間日影図があります。若干、コピーの関係で見づらいんですが、薄い緑で影を書いておりますのが、４時間の日影です。１日４時間日影になる部分の範囲を表示しております。","id":"exchange-076"},{"speaker":"中塚委員","kind":"質問・要望","question":"なぜ、学校を日影にするのか。３時間から４時間、今の話ですと、今ある校舎の位置ですと、校舎が１日中日影になるんでしょうか。午前中は日影になるんでしょうか。教育委員会と相談したのかよくわからないんですけれども、どんなふうに教育委員会と協議を進めて、向こうがよしとしているのか、悪いとしているのかわかりませんけれども、何か意見が挙がっていないんですかね。その２点を、お願いします。","respondent":"青木都市開発課長","answer":"教育委員会との協議の中、文教委員会と建設委員会でご報告したのが平成１７年ですので、そのころから既に検討を始めておりまして、配置計画の見直し等で、午前中、小学校ですから生徒がいる間、グラウンドには日が当たるようにしようという配慮をしておりますし、あわせて、今。","id":"exchange-077"},{"speaker":"中塚委員","kind":"質問","question":"じゃあ、教育委員会との協議は１年以上にわたって行われているんですか。ちょっとスケジュール的なことがあれば教えてください。今の区の説明ですと、じゃあ、何時間当たればいいのかと、何時間当たれば、子どもにとって良好な教育環境だと思っているのか。学校整備指針をどう理解しているのか。しかも、区がみずからやることは、私はあってはいけないと思うんですけれども、最後のところだけ教えてください。","respondent":"福田まちづくり事業部長","answer":"そういうふうに見るならば、このまち全体の調和、いろいろな機能の調和が図られるということ。ひいては、学習環境の向上にも寄与するというふうに考えております。","id":"exchange-078"},{"speaker":"本多委員","kind":"質問・要望","question":"この計画は、都道にぶつかるところまで、１６ｍでもっとまっすぐいくと思っていたんですが、１５ページのところで、ソニー本社のところで直角に曲がっているんですけれども、この辺の計画について、ちょっと教えていただきたいと思うんです。","respondent":"青木都市開発課長","answer":"今、委員からご指摘いただきましたのは、１５ページでごらんいただいておりますので、ご説明申し上げます。今回、再開発事業で整備するところは、白抜きになっている、委員ご指摘の道路です。","id":"exchange-079"},{"speaker":"本多委員","kind":"確認","question":"１本道ではなくて、将来は、１６ｍがＴの字になるということですか。それだと、１６ｍ拡幅する、セットバックするところもいろいろと、この何年間か話し合いも進めてきたと思うんですけれども、ソニー本社とかもあって、その辺は引き続きやっていくのか、それだけちょっと確認をお聞かせください。","respondent":"青木都市開発課長","answer":"すみません、今の私の説明が足りなかったんですが、北に伸びる部分と、それから、委員ご指摘のＴの字になったところからさらに西側の日野学園のほうに向かうところ、これにつきましても、１５ページの図で申しますと、ソニー第２工場と書いてあるところの北側になるんですが。","id":"exchange-080"},{"speaker":"宮崎委員","kind":"質問","question":"１９名の参加権利者数というんですか、個人や企業、それからあと主な事業者、そこのところを伺います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-081"},{"speaker":"宮崎委員","kind":"質問・要望","question":"主な参加企業があったら教えていただきたい。それから、この計画を見ますと、業務棟と店舗、それぞれあるんですけれども、今わかっているだけで、業務棟というのはどういう会社が入ってくる予定になっているのか。店舗も、この不景気の中で大手のところが撤退するとか、そういう動きもあるんですけれども、そこら辺の、この計画というのはどういう計画になっているのか。","respondent":"青木都市開発課長","answer":"本組合が設立された後は、参加組合員を募ることを考えておりますけれども、その参加組合員は、まだ設立前ですので、だれになるかはわかりません。","id":"exchange-082"},{"speaker":"宮崎委員","kind":"質問","question":"事務局の企業名がわかったらお願いしたい。それから、店舗、今のですと、小さなスーパーというお話なんですけれども、大きな住宅棟になるんですけれども、そういう商業施設ぐらいなのか、それとも大きなキーテナントを考えているのか、そこのところは、わかっている範囲で教えてください。","respondent":"青木都市開発課長","answer":"店舗のスーパーマーケットですけれども、あくまでもご近所の方々の利便性ということで小規模なものを想定しておりますし、飲食店や物販というものは、それぞれ小規模なものを、沿道型のものを考えておりまして、委員ご指摘になりました。","id":"exchange-083"},{"speaker":"井上委員","kind":"質問","question":"Ｂの地域コミュニティ施設等というのは、よくこういったところで地域センターの無償誘致だとか、いろいろなところでありますけれども、これはどういうものなんでしょうか。","respondent":"青木都市開発課長","answer":"情報発信や交流の場としての活用であるとか、あるいは、今、交番の増設がなかなかままならないということで、地元の防犯のステーションというようなことでも活用していきたいということで検討されていると伺っています。","id":"exchange-084"},{"speaker":"阿部委員","kind":"質問","question":"先ほど、中塚委員の質問に答えられまして、学校への配慮ということを具体的に幾つか挙げていらっしゃいました。まさにそういったことを、たとえ口頭でも構いませんので、やはり住民の方に、部分的でもいいから伝えて、安心してもらえると、再開発が終わるのを楽しみに待てるような、説明会はそんな場にしてほしかったと考えています。これは意見です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-085"}]},{"id":"topic-08","title":"大崎駅西口南地区市街地再開発事業に関する都市計画素案","agenda":"大崎駅西口南地区市街地再開発事業に関する都市計画素案","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"資料の２８ページなんですけれども、大崎のいわゆる短絡線、その線が地図上に載っているんですよね。この理由を聞きたいんですけれども、計画どおり進むということを、区が認めているから載せているんですか。ここに扇状に載っておりますけれども、これはどういう意味なのか、再開発事業の中の一環としてのことなのか、ちょっと教えていただけますか。","respondent":"青木都市開発課長","answer":"その前提の上で、ご説明申し上げますけれども、準備組合は、短絡線構想が出たことによって、事業計画の変更を余儀なくされておりまして、それによってスケジュールも１年以上おくれているという被害を受けていらっしゃいます。","id":"exchange-086"},{"speaker":"中塚委員","kind":"意見","question":"２月１３日に、区長が都知事あてに出した回答の中でも、事業計画案にこだわらず再検討されたいというのが区の立場ですよね。にもかかわらず、今のＪＲが勝手に示している計画どおりここに書かれているというのがどうしても意味がよくわからないので、ご説明いただけますか。","respondent":"阿部都市計画課長","answer":"短絡線の件ですけれども、今、委員がご指摘のとおり、環境計画の案に対して、区としては、住民の方の考え方がありますので、ルートに対して再検討していただきたいということは申し上げております。","id":"exchange-087"}]},{"id":"topic-09","title":"東品川四丁目地区地区計画の変更","agenda":"東品川四丁目地区地区計画の変更","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"３点ですけれども、今、ご説明の中で、具体的な内容に変更があったというお話だと思ったんですけれども、何がどういう感じになったのか、ちょっとそこだけ教えていただきたい。総事業費と補助金の関係を教えていただきたい。最後が、鹿島建設開発計画と住友不動産開発計画、素朴な疑問であれなんですけれども、なぜ鹿島建設と住友不動産の開発に区が協力するんですか、教えていただけますか。","respondent":"青木都市開発課長","answer":"１点目の変更というお話ですけれども、資料の表の説明の中で、５番のこれまでの経緯のところでの私の説明だったんですが、まず、地区計画を定めまして、実際には、今もう既にイオンとか、ホテルとかが入っているところは、既に開発が、平成１０年当時から進みましたので。","id":"exchange-088"},{"speaker":"中塚委員","kind":"意見","question":"誘導して、企業に対して環境への配慮を義務づけると、その分高い建物になるわけですよね。環境への配慮はむしろ悪化するんじゃないかと、私は思うんですけれども、何かＣＯ２だ、植える樹木だ、その関係があるんであれば、ご説明いただけますか。","respondent":"青木都市開発課長","answer":"繰り返しになりますけれども、例えば駅前での、より高度利用を図るべき地区として、例えば五反田駅周辺でありますとか、大井町駅周辺、これは既に古い時代から用途地域も商業地域にしておりまして、容積率も５００％とか、７００％という指定があります。","id":"exchange-089"},{"speaker":"宮崎委員","kind":"質問","question":"さっきのこととも絡むんですが、これはオフィスだと思うんですけれども、まあこれは民間ですので、民間が勝手にやっているんだということなんですけれども、需要の予測というのは一体どういうふうになっているのかというのが、区のほうはどういうふうに見ているんですか。","respondent":"青木都市開発課長","answer":"そういう中で、品川区として就業人口、あるいは居住人口のバランス、就業機会の確保とかというようなまちづくりの視点から考えますと、幸い、都が掲げますセンターコアエリアという中に、ぎりぎり大崎あたりはかかっておりますし、東品川は若干はずれてしまうんですけれども。","id":"exchange-090"},{"speaker":"宮崎委員","kind":"質問","question":"都心回帰というのは、今あると言われているんですけれども、私も今、港区と品川区でこれだけ違うというのは、正直言って非常にびっくりしたところなんです。そこら辺のアクセスだとか、そういうところの新たな需要だとか、そういう見込みというのは、どういうふうに見ていらっしゃるんですか。","respondent":"青木都市開発課長","answer":"ご指摘の青物横丁からの予測ですが、青物横丁方面からの交差点等の飽和度という形で交通量を見込んでおりまして、ちょうど品川シーサイドのイオンショッピングセンターに至るところの、交差点名がちょっとわからないんですけれども、海岸通りと補助２８号線。","id":"exchange-091"},{"speaker":"宮崎委員","kind":"意見","question":"今の見通しは、ちょっとどうかなと思うんです。やっぱり朝晩の、特に朝は、私なんか、とっくに飽和しているんじゃないかという感じもするんですけれども、それが０.７５で、これから０.８６ということですと、相当増えるかなという感じがします。それは埋まればの話ですけれども。ちょっとそういう感想も持ちました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-092"}]},{"id":"topic-10","title":"小関橋架替整備工事の契約変更","agenda":"小関橋架替整備工事の契約変更","exchanges":[{"speaker":"阿部委員","kind":"質問","question":"このままそれを２年間使っていくのかと思いますと、安全性が著しく損なわれることはないのかなと思うんですけど、１年が２年に延びたら、もうちょっとしっかりした仮設橋が欲しいなというのが率直なところなんですが、いかがでしょうか。","respondent":"青木都市開発課長","answer":"そういった形で、滑りどめがはげているというような不適切な状況があるとすれば、安全管理の点からも、これは指導を徹底しなければなりませんので、私どものほうから、再度確認させていただいた上で、指導を徹底して皆様の安全を確保するように努めてまいります。","id":"exchange-093"}]},{"id":"topic-11","title":"品川区葬祭場の設置に関する環境指導要綱の改正","agenda":"品川区葬祭場の設置に関する環境指導要綱の改正","exchanges":[{"speaker":"井上委員","kind":"質問","question":"これは、指導要綱ということで、こういう形で改正をされたことはすごくよかったことなんですが、たびたび問題になる、要綱である以上、どれだけの効力があるのかというところでは、どういうふうなものでしょうか。","respondent":"齋藤住宅課長","answer":"前提といたしまして、条例で、建築基準法に上乗せはできないことになっておりますので、地区計画では住民協定で決めたから、こういったものは建てられないという決めはできません。アッパーでできるのが要綱だというふうに、まずご理解をお願いします。","id":"exchange-094"},{"speaker":"井上委員","kind":"質問・要望","question":"要望です。こういった指導要項とか、設置の要綱なんかで、今実際に問題になっている部分もありますので、ものによって行政の対応の仕方が違うというようなことではなく、区がつくった要綱ですから、最大限、そちらを尊重して事業者に当たるという姿勢を貫いていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-095"},{"speaker":"中塚委員","kind":"質問","question":"今回の指導要綱の改正の背景に、中延の葬祭場の問題が、おそらくあったのかなと推測するんです。２点目ですけれども、今度、要綱が改正されますけれども、ここの趣旨や区の考え方、それを、住民はもちろん業者にも示すような、いわゆるパンフレット的な、例えば紛争予防条例みたいな、ああいう橙色のパンフレットというんですか、そういうのをつくる考えはあるんでしょうか。","respondent":"齋藤住宅課長","answer":"２番目のご質問ですが、周知の方法、要綱を改正しますと、要綱を窓口で配っております。今までのところ、葬祭場を設置したいという相談はありませんが、業者が建てられるときは、必ず要綱があって、区の窓口に来られますので、建てる方に対しては説明ができていると思っています。","id":"exchange-096"},{"speaker":"中塚委員","kind":"質問・要望","question":"ＰＲのパンフレットですけれども、例えば、今回の変更点の、景観を損ねる公告物とありますけれども、公告物って何を指すのかという例示というんですか。それから、２番目の商店街等、これはわかりやすいんですけれども、営業の妨害になるような行為というのは何を指すのか、今現在、区が何を例示として考えているのか、あわせて教えてください。","respondent":"齋藤住宅課長","answer":"というのは、そのまま商店街に流れて、店の前にずらっと並ばれるようなことは控えるように、あるような場合があったとすれば、必ず人を配置をして、商店街の営業を妨害するような行為にならないようにといったことを想定しております。","id":"exchange-097"},{"speaker":"中塚委員","kind":"質問・要望","question":"ぜひそういう例示も含めて、ちゃんと冊子をつくったほうがいいんじゃないかなと思いますので、その考え方を伺いたい。品川区のには入っていないんですけれども、建てるときに、周辺関係住民から求めがある場合は、協議した内容について協定をし、締結をし、遵守すると、これは京都市の指導要綱で、これが品川区で盛り込まれなかった理由というのはどういうものなのか、教えていただけますか。","respondent":"齋藤住宅課長","answer":"ただ、そういった商店街が近所にある場合については、極力、他の自治体との整合もありますので、そういったところも照会しながら、これから考えていきたいと思います。なかなか葬儀自体を抑止するような形での指導というのは難しいというのが、正直なところです。","id":"exchange-098"},{"speaker":"中塚委員","kind":"質問","question":"今の品川区の要綱は、建てるときではなくて管理運営事項、京都の場合は、建てるときに、こういう計画で進みますよと、その時点でいわゆる協定を結びなさいという、さらに踏み込んでいるんですね。その内容を、今回、盛り込まなかった理由が何かあるのかなと思ったので、そのことを伺ったんですんですけれども、僕の理解が間違っていたら。","respondent":"齋藤住宅課長","answer":"そういう意味で言いますと、京都より、私どものほうが厳しくなっております。要するに、事実上、立地させませんから。","id":"exchange-099"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/668670?Template=document&Id=3876#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2007-01-01&TermEnd=2007-12-31"}],"sourceMeta":{"pages":0,"characters":81454,"voices":291}},{"id":"h19-20070227-9","meetingId":"h19-cm02","date":"2007年2月27日","dateIso":"2007-02-27","committee":"文教委員会","time":"午前１０時０２分～午前１１時１１分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を16件抜き出しています。","topics":[{"id":"topic-01","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"公私立保育園・幼稚園との交流事業を行って、それを通して就学前プログラムをつくっていこうということだと思うんですけれども、こういった交流事業を始めようというふうに、この事業を行おうという、その動機といいますか、２枚目の資料に小一プロブレムということも書いていますけれども、どういった必要性というか、声をつかんで。","respondent":"河野指導課長","answer":"そのような子どもの変化に対応するための就学前教育のあり方ということで、このような検討が進められるようになってきたという経緯です。","id":"exchange-001"},{"speaker":"安藤委員","kind":"質問","question":"わかりました。品川区内でも、そういった実態というのはやっぱりあったということなんでしょうか。","respondent":"河野指導課長","answer":"この問題につきましては、どこそこで特定の区域、あるいは地域ということではなくて、全国的な傾向ですので、品川区内におきましても、そういう傾向は見受けられているところです。","id":"exchange-002"},{"speaker":"安藤委員","kind":"質問","question":"交流事業の点で、低学年担当教諭と保育士、幼稚園教諭の交流ということがありますけれども、教職員が交流して現状を指導に生かすというふうに２枚目の資料にもありますが、これは、例えば佐賀に視察に行ったときには、あそこは地域が、まだ人口も品川区よりは少ないということもあると思うんですけれども、幼稚園で見ていた子どもの様子を、こういう子どもを。","respondent":"河野指導課長","answer":"そういう交流とは別に、先ほど、小学校の教員と幼稚園・保育園、各公立私立の代表でもって組織するというふうに申し上げたのは、就学前プログラムを策定するための、いわば一つの委員会というような内容で説明をさせていただきました。","id":"exchange-003"},{"speaker":"林（宏）委員","kind":"質問","question":"だいぶ前から行われていた、説明だと六、七年前から行われていたということなんですけれども、この辺の、既にされてきたことの成果というか、その辺はつかんでいらっしゃるのかな。この文章を読むと「時代の要請を受けて自主的に」近隣の小学校がやり出したと。その自主的にやられたころの状況というのは、教育委員会では把握をされていたんですか。","respondent":"河野指導課長","answer":"今回こういうような形で、ブロックごとに２校ぐらいずつ特に指定をして、いわゆるモデル校、モデル園ということで取り組みを進めていくという背景は、それぞれがやっていた取り組みについて、もっと広くすべての幼稚園・保育園に情報提供をして、さらに活性化を図っていこうと。","id":"exchange-004"},{"speaker":"林（宏）委員","kind":"意見","question":"そうすると、されていた現場の担当に、今からでも、校長、園長あるいは今の副校長、あるいは低学年を受け持つ先生方は同じ１、２、３年ぐらいの先生方というのはだいたい決まっているとすれば、そういう現場からの、せっかく六、七年続けてこられた成果、実りを聞くというところから僕は始めるべきだと思うんだな。いろいろなことをしなきゃならない。その中に入ってしまう。","respondent":"河野指導課長","answer":"それで、平成１４年度からかなりそのあたりが改善されまして、いわゆる幼稚園自身も、今のままではよくないのではないかというようなことも含めて、小学校との連携、あるいは小学校側のほうも幼稚園との連携というようなことがかなり意識的に浮上してきたという。","id":"exchange-005"},{"speaker":"林（宏）委員","kind":"質問・要望","question":"１月ごろから始めて９月だから、５月ごろになると、１カ月ぐらい、もう幼稚園に行かないで学校に通うぐらいの比率で、子どもたちが行ってみる。そうすると１日１時間、１時限だけ受けてくるということも大事なことだろうと思うんだけれども、どの辺まで踏み込んで、ここには「疑似的兄弟姉妹関係、児童による模擬授業」とあるけれども、実際の授業を受けるという、そういうところまで入るんですか。","respondent":"河野指導課長、古里学務課長","answer":"ただ、先ほど申し上げたように、そういうことが体系的に行われているのではなくて、あくまでも個々の交流の中で展開されているという実態がありますので、これからモデル校を中心として取り組んでいく中で、子どもたちの様子を見ながら。これらも、先ほど申し上げた来年度に検討する就学前教育プログラムの中で、具体的な内容が詰められていくというふうに聞いてあります。","id":"exchange-006"},{"speaker":"林（宏）委員","kind":"質問・要望","question":"そのページをあけてあるので、ちょっと言葉を説明しておいてほしいのは、上の「目的」という中の下から２行目に「将来の児童の現状を知り」ということは、どういう意味なんですか。それから、いわゆる幼稚園・保育園に行っている子が今８割超えるのかな。行っていて、幼保に上がらず、在宅から小学校に上がる子どもたちへ向けての何か考えがあるのかどうかを聞かせてほしい。","respondent":"古里学務課長、河野指導課長","answer":"マイスクールのところについては、ちょっとこれは私は説明を聞き損ねておりまして、状況を把握してございません。申しわけございません。これはわからないです。そのことから考えると、１校当たり平均の数ですけれども、１名いるかいないかですので、今のところは個々に対応できる実態かなというふうに私どもはとらえております。","id":"exchange-007"},{"speaker":"林（宏）委員","kind":"意見","question":"だから中学校が、今おっしゃられるような、いろいろ子どもたち、中学生にとって幼児にとっても大事な部分かもわからないけれども、特に中学生にとって。それは、これと切り離し、切り離しというか別の場所で続けていく、それは教育委員会としても支援はしていくというふうに理解しておいていいんですね。","respondent":"河野指導課長","answer":"そのとおりです。","id":"exchange-008"},{"speaker":"武内委員","kind":"質問","question":"モデル校の選定ということなんですけれども、各ブロックで小学校２校ということなんですけれども、すると例えば小学校２校でＡ校Ｂ校とあって、その１校に対して幼稚園、もしくは保育園それぞれ１校ずつというふうになるのか、それとも複数の幼稚園・保育園がその１校に対して連携していくのか、その辺のところを教えてください。","respondent":"河野指導課長","answer":"具体的にどことどこがどういう連携をしていくのかということが、これから具体的に固まってくると思いますが、１対１ではなくて、１校対２園とか３園とかというケースも出てくる可能性はあります。","id":"exchange-009"},{"speaker":"武内委員","kind":"質問・要望","question":"逆に言うと、自分は、いろいろな理由でＢという小学校に行きたいんだけれども、Ａとしかその保育園・幼稚園は交流していないという中で、Ｂとも交流したいんだという、そういうようなところの、これはやってみないとわからないと思うんですけれども、そういうような保護者のお考えとか、そういうことも出てくるのかなと思ってお聞きしたんですけれども、非常に難しいところだと思うんですけれども。","respondent":"河野指導課長","answer":"したがいまして、Ａ小学校との交流という形はとりますが、前提としては、あくまでも就学のための準備ということでご理解をいただければなというふうに考えております。","id":"exchange-010"},{"speaker":"築舘委員","kind":"質問","question":"小学校における公私立保育園・幼稚園との交流事業ということで、公立、私立ということが書いてあるんですけれども、実際はお話を聞いていると、公立保育園・幼稚園との交流になっているような感じがするんですね。その辺の現状をどうするんですか。","respondent":"河野指導課長","answer":"こういうことをやりますよということも常々連絡はしていますが、現状からいうと、そういうのがあるということは、おそらくすべての幼稚園のほうも、私立の幼稚園ですが、ご理解はいただいているとは思うのですが、それぞれの実態に応じて対応するということで。","id":"exchange-011"},{"speaker":"築舘委員","kind":"質問","question":"これは大変心配しているのは、やっぱり保育課で一元化されてくると、どうしても保育課、要するに区立保育園を中心にやってきた課ですから、偏重というのはないとは思いますけれども、平等にはもちろん見てくれているとは思いますけれども、どうしても保育園のほうを重視していくとか、幼保一元化の場合はいいですよ。","respondent":"古里学務課長","answer":"この件につきましては、保育課とも相談をしながら、今、委員のおっしゃったような垣根があるような就学前教育の充実というのはあり得ないはずですから、すべて公立の小学校に上がってくるお子さんたちが大半ですので、そうした観点から私立。","id":"exchange-012"},{"speaker":"沢田委員","kind":"質問","question":"さっき、未就園児が２１名という話があったんですけれども、全体像、公立保育園、私立保育園、それぞれ幼稚園、もしどんな割合でどれぐらいというのがわかったら教えていただけますか。","respondent":"河野指導課長","answer":"平成１８年の私どもでいただいている統計的なデータで申し上げますと、幼稚園のほうの就園率が、公立と私立合わせまして、５歳児ですが６１.７％。それから保育園の園児数が、公立と私立を合わせまして３５.６％という割合になってあります。","id":"exchange-013"},{"speaker":"沢田委員","kind":"質問","question":"さっき、未就園児が２１名ということで、こんなに少ないのかというのを改めてびっくりしましたけれどもね。これは、品川区の単独なのか、あるいは教育再生か何かでもうちょっと全国的にこれを進めていこうとする中で品川区が取り上げているのか、全国の流れとの関係で、もしあったら教えていただけますか。","respondent":"河野指導課長","answer":"これは全国的にそういう傾向があるというふうに認識しております。","id":"exchange-014"},{"speaker":"沢田委員","kind":"質問","question":"だけれども、今はいろいろなメニューが出てきて、授業研究もままならず、子どもたちとの接触もかなり制約される上に、またこの、こういう新たな事業を取り組む、これ自体を否定するわけではもちろんないんですけれども、本来の業務というか、先生の授業研究だとか子どもとのスキンシップだとかということ、先ほどもちょっと話があったんですけれども。","respondent":"河野指導課長","answer":"ただ、このプログラムによって、いわゆる小一プロブレムということの解消につながっていけば、現状において１学期の前半部分、かなりの時間がこういう傾向を持っている子どもたちの対応に追われているという実態を考えると、ここは。","id":"exchange-015"},{"speaker":"林（宏）委員","kind":"質問","question":"ちょっといいですか。今日は時間がありそうだから、２回目ですが、すみません。やっぱり私立のほうが教育委員会に縛られたくないという意識が強いと思うので、柔軟に受け入れていける、提言がちゃんと取り入れられるかというと、そうもなかなか難しい面もあるだろうけれども、受けていくという第一歩が必要なのかなというふうに思うんですけれども、そういう意味でやってほしい。","respondent":"河野指導課長","answer":"疑似体験をすることによってカルチャーショックを受けるのではないかというご心配ですが、いきなり小学校へ連れていって、教室へ入れて、さあ椅子に座れということでは、当然そういうようなことも予想されるかと思いますが、今回、予定をしております交流事業は。","id":"exchange-016"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/169946?Template=document&Id=4600#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2007-01-01&TermEnd=2007-12-31"}],"sourceMeta":{"pages":0,"characters":19259,"voices":55}},{"id":"h19-20070227-5","meetingId":"h19-cm02","date":"2007年2月27日","dateIso":"2007-02-27","committee":"総務委員会","time":"午前１０時０２分～午前１０時５０分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を14件抜き出しています。","topics":[{"id":"topic-01","title":"平成１９年請願第２号、ＪＲ不採用問題の早期解決に関する意見書の提出を求める請願にかかる意見書","agenda":"平成１９年請願第２号、ＪＲ不採用問題の早期解決に関する意見書の提出を求める請願にかかる意見書","exchanges":[{"speaker":"菊地委員","kind":"意見","question":"正副のところでまとめられた案文ということで異存はないですけれども、ちょっと寂しいかなという気がしまして、請願の中には別に入っていなかったんですけれども、ＩＬＯ勧告のことをちょっと文言として入れるほうがいいのかなというふうな気がしましたけれども、そこは改めて正副に一任をします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-001"}]},{"id":"topic-02","title":"の２、報告事項","agenda":"の２、報告事項","exchanges":[{"speaker":"山村委員","kind":"質問・要望","question":"補助事業の一部を移管するということなんですけど、どういったものなのかということをもう少し聞かせていただければということと、それと、特別区交付金の算定が不明瞭とおっしゃっていたと思うんですけど、そこら辺をもう少し教えていただいて、あと品川区としてはどういうふうに求めていくのか教えていただきたい。","respondent":"日下部企画財政課長","answer":"それから平成２０年度以降も５％拡大したままでいくのかどうかを含めて、平成２０年度以降の取り扱いについてしっかりと都区間で、きっちりとお互いが合意できるように協議をすべきだと、そういう姿勢でこれから取り組んでいくです。","id":"exchange-002"},{"speaker":"塚本委員","kind":"質問","question":"資料に沿ってうかがいますけれども、都区財政調整方針ということなんですけれども、この方針を示したのはだれですかということについてお答えください。","respondent":"日下部企画財政課長","answer":"この都区財政調整方針につきましては、協議は都側から、ずっと財調協議が続くわけですね。それをもとにしまして、都側で案を整理します。","id":"exchange-003"},{"speaker":"塚本委員","kind":"質問","question":"物事というのは、こういう大事なペーパーが出て、だれが発言した、交渉事なら両者が合意したとかいろんなこと、あるいはある機関でやったものは機関。権限上は、東京都がこの方針で今年はやるんだぞというふうに解釈すべきなのか、都区間がいろんなやりとりの中で、今年はこういうふうに行動したよというふうに解釈すべきなのか、大きく分けてその二つがあると思うんですね。どっちだという意味なんですか。","respondent":"日下部企画財政課長","answer":"ただ、財調の中身については、都区間で合意がなされることが前提でありますので、提案権は都にありますけど、最終的には先ほど申し上げましたが、都区協議会の場において、両者合意がされる。そのことによって効力が発効する。そういう仕組みです。","id":"exchange-004"},{"speaker":"塚本委員","kind":"意見","question":"余計なお世話、１％上げれば自治の拡充の助けになるだろうなんて、だれがどういうつもりで言っているんだという、ちょっと腹の立つような表現でもあるわけですけれども、上から物を言っている。そっちのほうじゃないだろうという、こっちは思いがあるわけ。合意が何だというような思いがあるわけですよ。この文書はだれの責任で、どういうふうに出てきたんだということを改めて聞きます。","respondent":"日下部企画財政課長","answer":"だれの責任でということでありますけれども、東京都の責任において原案が提出された。それに対して、都区の正式な法定機関であります都区協議会の場におきまして、両者で合意を見たです。","id":"exchange-005"},{"speaker":"塚本委員","kind":"意見","question":"都区協議の機関で合意を得たというなら、やはり、そういうことをどこかで表現すべきときに来ているんじゃないか。","respondent":"日下部企画財政課長","answer":"先ほどちょっと冒頭でご説明申し上げましたけれども、あくまでも財調のいろんな経過がありますけれども、最終的な合意確認、都区間でしっかりとした内容を踏まえて、一つのゴールとしては都区協議会でありますので、先ほどもちょっと触れさせていただきましたけれども。","id":"exchange-006"},{"speaker":"菊地委員","kind":"質問","question":"これはまだ２３区の枠組みの中で、区のお話なんだと思うんですけれども、こうやって数字が決まったときに、これの配分というのは話の中で、例えばこうやって数字が決まっちゃうとある意味、東京都そのものは関係ないとなっちゃうと、区だけの、東京２３区という協議の中での話になっていくのか、ちょっとそういう枠組みのところを教えていただけますか。","respondent":"日下部企画財政課長","answer":"先ほど申し上げましたが、まず当初算定が出てきます。これは要するに１年間の全体の財調三税、入りの関係、それから出の関係を双方照らし合わせまして、当初の段階で、これもあくまでも予算といいますか、一つの見込みでありますので、これを立てる。","id":"exchange-007"},{"speaker":"菊地委員","kind":"質問","question":"何となくわかるんですけれども、これで確定をしているという数字、再調整の中で、確定してしまった数字ととらえていいんですか。","respondent":"日下部企画財政課長","answer":"それはそういうことです。","id":"exchange-008"},{"speaker":"山村委員","kind":"質問","question":"今ビラが公費負担で無料で頒布できるとおっしゃったと思うんですけど、これは首長だけなんですか。","respondent":"野田口選挙管理委員会事務局長","answer":"ローカル・マニフェストということで、知事選挙あたりについても、そういうことをしたらどうだということが検討されてきて、最終的にはビラを頒布するということに今回の法改正で決まったです。","id":"exchange-009"},{"speaker":"山村委員","kind":"質問","question":"区議選のほうも同じですけど、投票所一覧で、投票区名第１３投票区はシティコート目黒とあるんですけど、これはふつうのマンションですか。","respondent":"野田口選挙管理委員会事務局長","answer":"そこを建てるときに、選挙管理委員会と協議いたしまして、その１室をそこに住む人たちの利便と同時に、地域の人たちのために選挙があるときには開放してほしいということで、そのシティコート目黒のマンションの１室を使用させていただいている、そういうものです。","id":"exchange-010"},{"speaker":"山村委員","kind":"質問","question":"シティコート目黒に住まわれている人とも話し合いがついているというのはわかったんですけど、ほかの投票所と比べると、知名度というわけじゃないんですけど、場所を本当に周りの人は理解しているのかなというのが、ちょっと小学校とかに比べるとあるので、その辺はどういうふうになっているんでしょうか。","respondent":"野田口選挙管理委員会事務局長","answer":"もう４年ぐらいたちますので、結構周知はされてきているというふうに思います。","id":"exchange-011"},{"speaker":"山村委員","kind":"確認","question":"こういう投票所一覧とかは区のホームページとかで場所を確認できるようになっているんでしょうか。","respondent":"野田口選挙管理委員会事務局長","answer":"投票所の一覧はホームページに載せていると、たしかそう思いました。","id":"exchange-012"},{"speaker":"山村委員","kind":"意見","question":"本当だったら、やっぱり特に新しく入ってくる人というのは若い人が若干多いと思うので、ホームページ上に投票所一覧で住所があるんだったら、例えばそこの住所のところをクリックすれば、何らかのちゃんとした地図に飛ぶとか、そういう仕組みというのはすぐできるわけだから、そういう工夫をなされたほうがよろしいんじゃないかと思いますので、もう間に合わないのかもしれないですけど。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-013"},{"speaker":"山村委員","kind":"意見","question":"投票用紙の色というのは、どういう基準で何色だとか、さっきと色が違うのか。それからあと、区画面数が６０名というお話だったんですけど、今のところ、予定６０名で足りそうなのか。","respondent":"野田口選挙管理委員会事務局長","answer":"見やすければいいなという程度です。それから、板面については、一応５５人出て足りるかなという程度でつくってありますので、現時点では飛び込みが入ったとしても、十分対応できるかなというふうに思ってあります。","id":"exchange-014"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/396657?Template=document&Id=1748#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2007-01-01&TermEnd=2007-12-31"}],"sourceMeta":{"pages":0,"characters":16060,"voices":67}},{"id":"h19-20070228-11","meetingId":"h19-cm02","date":"2007年2月28日","dateIso":"2007-02-28","committee":"自治制度特別委員会","time":"午前１０時０２分～午前１１時４８分","status":"正式会議録","sourceType":"formal","overview":"自治制度特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を31件抜き出しています。","topics":[{"id":"topic-01","title":"議案審査","agenda":"議案審査","exchanges":[{"speaker":"林（宏）委員","kind":"質問","question":"会計管理者という方のポジションなんだけど、部長級なのか、そういうことをお聞きしたいのと、それから収入役がやっていた仕事、収入役室をこの会計管理者という方が全部受け継ぐということになるんだけれども、その辺の、なぜという意味はわかるんだけど、内容の部分。ちょっと聞きたいんだけれども、品川区はどういう組織になるのか聞かせてくれますか。","respondent":"中山資源循環推進課長、堀越行財政改革担当課長","answer":"一部事務組合のほうにかかわる会計管理者についてですけれども、これは一般職の会計管理者というのが法に定められておりまして、後ほど組織改正のご説明もする予定なんですが、ここにもありますけれども、会計室というのを置いて。会計管理者については今のところの予定では部長級を充てるという形で予定をしております。","id":"exchange-001"},{"speaker":"林（宏）委員","kind":"質問","question":"それだけの権限というかそういうところにあった者が課長級、部長級というところになって、仕事のやり方というか、口出しの部分で権限が薄れているというか、チェックというか、そういう部分での、収入役というから入るお金の管理というふうにとらえがちなんだけれども、出るお金の管理が非常に大事な部分であるわけですから、そういう意味で、きちんと責任が果たせるポジションになっているのかどうかという。","respondent":"中山資源循環推進課長","answer":"組織の位置づけとしましては、会計室の中に新たに会計管理者を置くという組織構成が予定されているということでございましたので、ご質問がありましたように、あくまでも会計そのものの適正な執行を行うために設置するものですから、当然。","id":"exchange-002"},{"speaker":"林（宏）委員","kind":"確認","question":"今、中山課長さんにあれするのは大変なのかもわからないけれども、説明するにはきちんとその辺を確認をした上でしておいてもらわないと困るし、もともと収入役という職責が生まれた経緯があって、時代の流れとともに収入役というポジションが必要でないと言ったらちょっとおかしいかもしれないけど、なくても行政としては。","respondent":"中山資源循環推進課長","answer":"それで今のご質問の収入役制度そのものが、これは記録によりますと明治２１年ぐらいですから、特別職としての設置がされているようですけれども、一組の今回の説明においても、電算化の進展だかといろいろな事務について。","id":"exchange-003"},{"speaker":"林（宏）委員","kind":"質問","question":"今、中山課長が答えていただいたんだけれども、この順序でいくと、区として組合に品川区議会がどういう態度をとったかというのを伝えていくという仕事になるわけで、制度が廃止されたから変えるという、その制度がいいほうに出るように、首長の権力が非常に大きく、ひとつ大きくなっていくということになるわけですから、そういうのもできれば申し添えながら、品川区としても同じ立場にいるんだろうけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"}]},{"id":"topic-02","title":"特定事件調査","agenda":"特定事件調査","exchanges":[{"speaker":"沢田委員","kind":"質問・要望","question":"区側の要望なのか、あるいは区側の中でも小さなところと大きなところといろいろあるんですけど、あるいは都側のあれで入ってきているのか。ちょっとそこらをもう少しわかる範囲で説明を願いたい。それは自由ですから何を言おうといいんですけれども、何かそういうのが公然と言われているだけに非常に不安なところなので、ちょっと説明願いたいんですが。","respondent":"日下部企画財政課長","answer":"都が行う必要があるとされた事務を除いては基本的に都から特別区へ事務の移管を進める。そういう前提のもとで検討委員会の検討が進められるというものでありますが、都側の認識としては事務を移管する。","id":"exchange-005"},{"speaker":"沢田委員","kind":"質問","question":"すさまじい市町村合併が全国で展開しているというのは事実ですし、今回のこの区域のあり方ということがその線上で出てきているのではないかということをすごく心配するんですよね。２３区の中で公然と議論はしていないけれども、区域のあり方を合併も含めて考えようというような実際の動きというのはあるんでしょうか。","respondent":"日下部企画財政課長","answer":"私どもが承知している限りでは、この間、２３区内部として公然とというようなことでお話がありましたけれども、例えば区長会でありますかと、そういうところで正式にこれを検討の俎上に上げて議論をしてきたというような経緯は今のところないというふうに承知をしています。","id":"exchange-006"},{"speaker":"石田委員","kind":"質問・要望","question":"逆に、だれかが間に入ってつなぎをする意味で、都のほうが総務局長を入れているのか、それであるならば区側のほうもそういう形のものをおいておくべきだったのではないかなと思うわけですけれども、そこら辺の考え方はどういう形で総務局長は両方なっているのかなという部分が１点。その区側の対応の説明が今全然なかったんで、この部分の説明をしていただきたいというふうに思います。","respondent":"日下部企画財政課長","answer":"ですから、これはおそらく今まで以上に区長会で２３区の区長さん方が議論をしっかり集約をして、こちらの検討会に臨むということになる。","id":"exchange-007"},{"speaker":"石田委員","kind":"質問・要望","question":"これはこういう形で見るよ、これはこういう形で見たいという。この実務的な部長会、助役会、ここに課長会が入るのかどうかそれはわからないんだけれども、そこの実務的な部分を整理するこの３パターンなのかな、基本的には部長会、助役会とするならば、ここに物事を上げていく実務的な整理をする部分の意見調整は、だれがどのようにやろうとしている部分なのか。それを教えていただきたい。","respondent":"日下部企画財政課長","answer":"区長会がどういう政策的なあるいは政治的な観点から１つの調整、判断をするか。ですから、さっき申し上げましたように、今回のあり方検討委員会を２年間の間しっかりと進めていく上でやっぱり重要な役割、キーになるのは区長会だというふうに私どもは思っているところです。","id":"exchange-008"},{"speaker":"石田委員","kind":"質問","question":"そういうことをもちろんわかって言っているんですが、先ほど言った実務的な部分と区長会は政治的な部分も入ってくると思うんですね、もちろん区を代表しているわけですから、もちろん区長会は最終判断をする。それを１回皆さんで出し合って、じゃあこれをどういうふうに取り扱っていくのか。事務局次長がやるのはわかるけど、その今ここにすぐ第１四半期からやっていこうというこの整理を実際はどこがやるか。","respondent":"日下部企画財政課長","answer":"さっき申し上げましたように、まだこれからどういう手順で詰めていくかというのは関係のところでいろいろ整理をしているというところになっておりますけれども、いろいろな課題がかなり事務配分、スタートは、事務配分の検討ですから。","id":"exchange-009"},{"speaker":"石田委員","kind":"質問","question":"これで最後にします。その議論は１回置いておきますが、その先、これは議会は議会として対応するものは議長会もあるわけですから、また違う場面で議長にお願いをしていきますが、今のところ、各区の考えをぶつけていくんだという部分が必ず部分的に出てくる。議会に対して、どの程度、どこの部分で、この幹事会の報告は議会に対してどういう形で来るのか。幹事会だとある程度まとまったものになる。","respondent":"日下部企画財政課長","answer":"これから非常に重要なこういう制度的な問題について検討を進めていくわけでありますので、これも前回、濱野区長のほうから申し上げましたように、議会にいろいろバックアップいただく必要があるだろう。これはもう当然のことです。","id":"exchange-010"},{"speaker":"石田委員","kind":"意見","question":"区長会である程度できたものをぽっと報告したって、部長会なんて紛糾したらそのまま終わりかというようなところが出てくる可能性だってあるし、品川区議会だってそれなりの対応をするとなれば、それなりの準備期間なりいろいろな動きが必要になってくると、非常に早目というか、どうしていったらいいんだということを、それこそ例えば品川区議会だって全体でいろいろな形の会を持って。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-011"},{"speaker":"土井委員","kind":"質問","question":"特に始まりのところが大事だなと思うので、そこら辺が見えてくると少し今の話も見えてくるんじゃないかなというふうに思うんですけれども、そこら辺のところはどうなんですか。","respondent":"日下部企画財政課長","answer":"確かにある区にとっては不本意なことも、場合によったら２３区全体の利益として、これはある程度我慢してもらうということがあるかもしれませんし、そういったことを早目早目に２３区間の水平調整をやれるような体制づくりはこれから非常に重要なところだろうと考えておりますし。","id":"exchange-012"},{"speaker":"土井委員","kind":"意見","question":"２３区が全体にそのような格好でやっていかなきゃいけないとすると、品川はどうなるの、まず。品川は率先してこうこうこうだから、皆さんもやってくださいというふうな形になっていかなきゃいけないんじゃないかなと思うので、品川はどうするのか。","respondent":"日下部企画財政課長","answer":"そういった意味では、特に区の私どもそれぞれ所管の部課長も含めまして、その辺、何からどういうふうに入っていくのかというのはこれからでありますけれども、品川区としても２３区の議論をできるだけ率先して推進していけるような。","id":"exchange-013"},{"speaker":"土井委員","kind":"質問・要望","question":"そこら辺を、やはりこの中でもまとめる役をどこかできちんとやってもらって、それをどういう形でまとめていくんですよというのをつくってもらって、この部長会なり何なりに臨んでいくという形にぜひしていってもらいたいと思うので、その段階等でも我々のほうにも場合によっては意見を求めていただければ本当はありがたいんだけれども、それは必ずしも時間的にそうはいかないのかもしれませんけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-014"},{"speaker":"本田委員","kind":"意見","question":"１点ですけれども、その区域の問題ですが、濱野区長の施政方針でその姿勢は明確に出ているわけですね。それはもういいんですが、一方都議会では、区長の基本姿勢とは異なって、一体区域をどうするんだと、早くしろというような発言が都議会では出ている。そういう中で一般都民、一般区民から見れば、どうなっているんだろうと。その点をお尋ねしたいと思います。","respondent":"日下部企画財政課長","answer":"一般区民の皆さんにということで、確かに都と区の今のお互いの認識のずれというのは非常に大きいわけでもありますし、その辺どうなのかというのがまず１つ重要なことはそのとおりです。","id":"exchange-015"},{"speaker":"本田委員","kind":"質問・要望","question":"２３区がいろいろ言われるように、水平調整だけではなくていろいろな組織のあり方について違いがある。都と合意する前に２３区の中で合意を図らなければならないために難しい課題を抱えているわけですよね。ですから、これまでのようなことではなくて、もっと歯切れよく２３区の統一区長の見解を随時発表して進めるようにしていただきたいということを強く感じますので、この辺はお願いをしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"},{"speaker":"原委員","kind":"質問","question":"この資料５のスケジュールのことなんですが、スケジュール（案）という形で検討委員会あるいは幹事会が平成２０年度の第３四半期の最終的な調整に向かっていろいろな形で、あるいは区域も含めて受け持ったということだと思うんですが、今まで皆さん方の意見も含めて非常に大事な具体的な事務配分、それから区域のあり方についても、この１年ぐらいの間に最終的な調整をしたりということなんですが。","respondent":"日下部企画財政課長","answer":"２年間という限られた時間でありますので、確かに中身が中身ですので都と区のあり方の一番根っこをどうするかということを進めていくわけですから、そういう意味では非常に２年間というのはきついなという感じもしておりますけれども。","id":"exchange-017"},{"speaker":"原委員","kind":"質問・要望","question":"ただ、内情的なものとすればかなり詰められていなければならないものもあるし、それから今お話のように７年間やってきたところであるので、あるいはこれから２年間の中でやはりちゃんとした形で結論が出るのかという疑問があるのではないかなと思ったんたけれども、一生懸命やっていくというところで、しっかりやっていただきたいなというふうに思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"},{"speaker":"林（宏）委員","kind":"質問","question":"幹事会の区側、都側のほうはこちらでどうこう言える立場にはないので、区側のほう。考え方として、品川以外の２２区の色分けというのは、品川区役所の企画では持っているんですか。","respondent":"日下部企画財政課長","answer":"色分けということでちょっと難しい面がありますけれども、今、委員のほうで外のほうの区が多いんじゃないかというお話がありましたが、これは別にそういう目で見るわけじゃないんですけれども、比較的、これだけで見ますと。","id":"exchange-019"},{"speaker":"林（宏）委員","kind":"質問","question":"スケジュールの中に入っていって、もうあとすぐ人事異動があったりして担当者が変わる場合もあるだろうし、区側の考え方をまとめるということについて、区長会はどういうコメントを発しているんですか。","respondent":"日下部企画財政課長","answer":"それで、いずれにしろ、都区のあり方について抜本的な検討をしっかりやっていこうということで、これはもう２３区それぞれ立場の違いはあってもお互いに意志統一を区長会でやったわけですよね。","id":"exchange-020"},{"speaker":"林（宏）委員","kind":"確認","question":"だから、これ暫定的なんだよね、非常に。そのことも都側に見すえられている部分もあるのかなという。その次にどういう事務をという、ここに出ている移管事務の選定基準なんていう話に入っていけるわけで、そういうことをここで言っていても、いやいやこんなのやらないで今のままで行こうよという議会もあるだろうと思うんだけど、事務局にはそういう情報はないですかね。","respondent":"日下部企画財政課長","answer":"東京都に対してそういう強い姿勢を持っていくことについては一致できるのではないかと考えていますので、難しいことでありますけど、非常に重要なことだというふうに考えております。","id":"exchange-021"},{"speaker":"林（宏）委員","kind":"確認","question":"ちょっと中身に入ります。６ページの５項目があるんだけれども、１番目が移管対象になる事務の選定基準の基準づくりをする。２番が具体的な事務移管の是非を判断する。移管の是非を判断する。前２段は総論的、抽象的、事務ということになると総論的な仕事が進められるのかなというふうに思うんだけれども、その辺の確認を説明してください。","respondent":"日下部企画財政課長","answer":"実は非常にこの表現、私自身もこれを見たときに非常にわかりにくい面があったんですね。ですから区長会のほうにも確認したような経緯もありますが、１、２、３というのはある種の三段論法なんですよね。","id":"exchange-022"},{"speaker":"林（宏）委員","kind":"質問","question":"そうすると１と２が決まると３は自然に決まるというふうに理解しておいていいんですか。今、言っているように公園の広さで決めるのか、あるいは用途で決めるのか、そういう基準が決まったら３番は決まってくるじゃないですか。そういうふうに理解すればいいんですか。","respondent":"日下部企画財政課長","answer":"そうですね。１で大きく、２で少し具体的にしっかりと絞るとなれば、当然それを踏まえて３に自動的にといいますかね、最後にどういう整理をするか、精査をするかという面もあろうかと思いますけれども、そういう流れでいくのではないかというふうに考えております。","id":"exchange-023"},{"speaker":"林（宏）委員","kind":"意見","question":"具体的な事務について全体の線引きがあって、事務を具体的にするかしないかの判断が決まってきたら、この図の今の事務の中からピックアップしていけばこれは来る、これは来ない、これは今のままというように、２番の考え方で全部チェックができていくようになっていっちゃう。線上にあるというのが出てくるかもわからないけど、自然となっていっちゃうので、その辺を僕らはどう考えていくか。","respondent":"日下部企画財政課長","answer":"ちょっとこれ、もう少し具体的な事例としてご説明させていただきませんと、正直言いまして私自身も十分整理できていない部分もありまして、この辺はもう少しまた具体的な事例も含めて、その辺はまたご説明するような機会を持ちたいというふうに考えております。","id":"exchange-024"},{"speaker":"林（宏）委員","kind":"質問","question":"４番なんだけど、区域のあり方に関する検討の視点ということは、検討するときの考え方とか見方とか、例えば財政上のことからいく、人口的なこと、面積あるいはこれは大事なことだけど、東京都が首都であるという考え方で東京都が今進めている大都市圏構想とかもかかってくると、２３区だけの話ではなくなってくる問題もある。そういうことを検討するということなんですか。","respondent":"日下部企画財政課長","answer":"視点ということでありますので、今、委員がおっしゃったような人口、面積はもとより、そういう今の区を取り巻く首都の問題とかいろいろそういうお話もございましたけれども、その辺を視野に入れての視点という表現になっていると考えます。","id":"exchange-025"},{"speaker":"林（宏）委員","kind":"意見","question":"そうすると、その前にこれは２３区として話し合いを進めていくということであるわけで、自立した自治体である品川区はこれにかかわっていくときに、我々もどういう考えを持っているのかという議論を始めなきゃならない。自立的に考えていかなきゃ国だとか都からの押しつけで、あるいは２３区の総合的な考え方の中で品川区がぐしゃっとなっていっちゃう。それは品川区としてどう考えていらっしゃるのか。","respondent":"日下部企画財政課長","answer":"非常に難しいところでありますけれども、確かにおっしゃるように品川区としてどうなんだ。そういう主体的な考え方をはっきり整理するということは非常に重要なことだと思うんです。","id":"exchange-026"},{"speaker":"林（宏）委員","kind":"質問","question":"それを何も検討しないまま事務の移管を待ってというのは僕は怠慢だと思う。基本構想、４次長計を検討していく、変えると区長はおっしゃられているわけだから、だったらこの問題を品川区としてどうとらえる。考え方を早急にということじゃないけれども、入っていかなければいけないと僕は思うんだけれども、その辺いかがでしょうか。","respondent":"日下部企画財政課長","answer":"平成１９年度、２０年度で基本構想、それから４次長計の改定ということで進めていくわけでありますけれども、今、委員ご指摘のようにこの区のあり方といいますか、制度上の都区制度のあり方がどうなのかということは構想計画策定の大きな１つの柱にもなるものでありますので。","id":"exchange-027"},{"speaker":"林（宏）委員","kind":"意見","question":"当然のことじゃなくて、やりますと言ってもらわないと困る。当然のことと思っていてもやらなきゃ始まらない。だから、やらなきゃいけないと言っているんだから、始めなきゃおかしい。例えばさっきも言ったけど、千代田区みたいに独立市になるという区長さんが、すぐにはいろいろな法的な部分もあるんでしょう。きちんと品川区の考え方をまとめる作業に入っていかなきゃいけない。決意を述べますか。","respondent":"日下部企画財政課長","answer":"しっかりした議論を検討してまいりたい。","id":"exchange-028"},{"speaker":"石田委員","kind":"確認","question":"今の話で１点だけ確認したいんだけど、さっきも言ったんだけどはっきり聞いておきたいのは、相差の部分をしっかりやっていくにはという部分なのか。そこをどうするか。国際フォーラムが来たら受け取った区はどうするんだという話にもなるわけだから、そういう受け取れる、受け取れないその基準、そういう相差の部分をここでやっていくという理解をしていたんだけど、そういう理解でいいのかね。","respondent":"日下部企画財政課長","answer":"今回の仕切りは、これはそういう高橋前区長のいろいろなお考えも、昨年の検討会の中で大分入っていたんですが、基本的には一定の整理はもちろん今回、区切りを３％アップでしたわけでありますけれども、今後の検討委員会の検討にあたっては。","id":"exchange-029"},{"speaker":"林（宏）委員","kind":"意見","question":"予算がこれから審議されるんだろうと思うんですけれども、終わったのかな。決まったんだな。新会社に幾らで委託をするのか。それから、２３人の退職をされる方が新会社へどういうふうに動くのかとか、そういうようなことも含めて、今期はこの委員会だろうと思うんだけれども、所管する委員会へ僕は報告をすべきだと思いますけれども、その辺はだれが答えるの。","respondent":"中山資源循環推進課長","answer":"大田清掃工場に関しては、体制としてどういう形になるのかということを概略で聞いたところ、４６人の減とご説明申し上げたわけですが。","id":"exchange-030"},{"speaker":"林（宏）委員","kind":"質問","question":"この表にある出先機関の清掃工場でマイナス２３という方々がいらっしゃって、この人たちともその新しい会社に行くんですかって聞いているんです。","respondent":"中山資源循環推進課長","answer":"今年度の退職の中で新会社には何人かということは今手元に把握はしておりませんけれども、いわゆる行政ＯＢが先ほどのところだと１３～４名になるですから、一定人数はこの中に行っていると思いますけれども、全体の中での現実の数は２３です。","id":"exchange-031"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/240034?Template=document&Id=5612#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=11&TermStart=2007-01-01&TermEnd=2007-12-31"}],"sourceMeta":{"pages":0,"characters":32439,"voices":88}},{"id":"h19-20070228-16","meetingId":"h19-cm02","date":"2007年2月28日","dateIso":"2007-02-28","committee":"街づくり特別委員会","time":"午前１０時０２分～午前１１時１０分","status":"正式会議録","sourceType":"formal","overview":"街づくり特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を20件抜き出しています。","topics":[{"id":"topic-01","title":"本日は、災害に強い街づくりに関することのうち、密集住宅市街地整備促進事業","agenda":"本日は、災害に強い街づくりに関することのうち、密集住宅市街地整備促進事業","exchanges":[{"speaker":"南委員","kind":"質問","question":"しかし、前回の委員会で質問させていただいたのは、道路の拡幅のところがかなり強調されたように、私としては受けとめて、やっぱりそこだけを先行させるという進め方というのは好ましくないんじゃないかということで質問させていただいて、きょう、改めて総合的にというふうなお話だというふうに受けとれたので、それはそれとして、了解していきたいとは思っておりますけれども、やっぱり道路建設というのは。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-001"},{"speaker":"菊地委員","kind":"質問","question":"前回、２９号線のことでお聞きしまして、今、５５０棟ぐらい、５００棟ということですか、２９号線にかかわるところの皆さんがいらっしゃるということですけれども、まちづくりのこのニュースの中で、明確に補助２９号線の整備を関係部局に働きかけるということで打ち出されているわけですから、５００棟の皆さんのところの、実際、この計画に賛成なのか反対なのかっていうのは。","respondent":"伊勢住環境整備担当課長","answer":"こちらの地元の協議会では、３名ぐらいの方が反対の意思表示をされたと。それから、全体の説明会ですけれども、そこで反対の意思表示をされたのは、もちろん発言の機会が全員にあるわけではありませんけども、１名ございました。の方は、特にその意思表示はされていないです。","id":"exchange-002"},{"speaker":"菊地委員","kind":"質問","question":"すみません、私がお聞きしたのは、さっきも言ったように、２９号線の整備を担当部局に働きかけるという以上は、実際に２９号線の線引きをされた中にお住まいの皆さんの賛否というのは、当然、聞いているということなんだと思うんですけれども、そこをちょっとお聞きしたんです。","respondent":"伊勢住環境整備担当課長","answer":"それで区としては、この２９号線については、都のネットワークはもちろんですけれども、防災性も非常に大事な面があるということで、関係機関に働きかけるというようなことでございまして、ここに係る方のご意思がどうかということは考えていないというのが状況です。","id":"exchange-003"},{"speaker":"菊地委員","kind":"質問","question":"考えていないというのは非常におかしな話だと思うんですよ。前回の委員会のときもそうですし、今回の本会議でも、うちの宮崎議員が質問したときも、詳しく説明をして理解を得るというのは、区長も事業部長のほうも答弁の中でおっしゃられていましたけれども、そうすると、そのことはやらないよという話なんでしょうかね。","respondent":"伊勢住環境整備担当課長、福田まちづくり事業部長","answer":"こちらの計画（案）は、まだ密集事業を導入するための計画でございまして、そのために地区の皆様、特にその２９号線に係る方だけ特別に呼んでとかということは考えてございません。所定の手続に従って決定されている、そういうものでございまして、私ども再三申し上げておりますように、関係する住民の皆さんには、できるだけ丁寧に説明をし、その理解を得るために十分努力したいというふうには思っておりますが。","id":"exchange-004"},{"speaker":"菊地委員","kind":"質問","question":"実際にここに働きかけをしますよというふうに書かれていて、これからの計画を見れば、もう４月には事業実施というんでしょうかね、もう２月に、都ですか、国ですか、都に対して計画を上げていくという話ですから、どうも今の話だけでは納得しかねるんですけれども、働きかけをするというのは、じゃあ一体どういうことなのかを、ちょっともう少し詳しく教えてもらえますか。","respondent":"福田まちづくり事業部長","answer":"したがいまして、この計画案ですとか、それから案がとれた計画の中にこの都市計画道路を盛り込むのは当然でございまして、この都市計画を無視、軽視をして、このまちの将来を語ることはなかなか難しいだろうという意味で書き込んであるものです。","id":"exchange-005"},{"speaker":"菊地委員","kind":"質問","question":"このまちづくり計画案の説明にしても、１月２５日と、あとあしたですか、２７日にやるというわけですから。これ、一体いつ、どこで、だれが、理解を得るために説明をし、論議をするんですか。","respondent":"岩田まちづくり事業部次長","answer":"ここの２９号線の線の中の地権者の方々の土地の対応をどうしていくかというのは、これは前回も申し上げましたように、今後の東京都なり国と私どもの協議事項になっておるわけですけれども、道路事業としてはできません。","id":"exchange-006"},{"speaker":"菊地委員","kind":"質問・要望","question":"だから、さきの本会議での答弁でもあった、理解を得ると言うけれども、一体いつ、だれが、どうやって説明し、論議する機会をつくるのかというのを、もっと明確にして進めていただきたいんですよ。ですから、一体いつ、どこで、だれが話をし、論議するのか、ここだけは徹底的に決めていただきたいなというふうに思います。","respondent":"岩田まちづくり事業部次長","answer":"実際、説明会をやりますと、表向き反対というのは若干ありましたけれども、やっぱり思ったほどではない。やっぱり住民の方々に、この都市計画道路、地権者の方に必要ですか、必要でないですかと言えば、まず９割９分、必要ない、反対だとおっしゃいます。","id":"exchange-007"},{"speaker":"菊地委員","kind":"質問","question":"これも、この間、だから、ほかに移したらどうなるんだみたいな話を次長はされていたけれども、だから、今の話というのは、これもやっぱり単に品川区は決められないということ。でも、実際にそこに住んでおられる皆さんの意見が主体にならない限りは、実質的にはそこにいらっしゃる方たちを追い出すわけですから、今のお話だと、全く民主主義という基本概念がないまま推し進められるという感じがしますけどね。","respondent":"岩田まちづくり事業部次長","answer":"先ほども言いましたように、この２９号線を含めて、広域ネットワークの一部ですから、ここの沿線の方たちが困ると、はずしてくれという気持ちは十分理解できるんですけれども、それを受けた行政側として、東京都に、国に、これ住民が反対されているので廃止してくれと。","id":"exchange-008"},{"speaker":"菊地委員","kind":"意見","question":"最後にしますけども、要するに、今の２９号線、ここで事業促進をするという地域にお住まいの皆さんというのは、犠牲者なわけですよね。今の次長の話でいえばね。私、都心の道路の形成が必要ないなんて言っているわけじゃないんですよ。だからこそ、本会議でも答弁されていたように、住民に理解を得る体制づくりをしてくださいということをお願いしているんです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-009"},{"speaker":"須貝委員","kind":"確認","question":"ちょっと確認なんですが、都市計画道路２９号線ですが、これはもう数十年前に都市計画道路ということで図面上に点々と表示されているんですが、実際、あれですよね、もう建て主が建物を建てるときには、あらかじめ都市計画道路ですよということを了解の上で建てているということではないんでしょうかね。それだけちょっとお聞かせください。","respondent":"片田建築課長","answer":"ただ、先ほど次長が申し上げましたように、平成１６年４月から緩和された形で、今、３階まですべてを認めるということになっていますので、そういう中で、きちっと建て主の方にご認識していただいた中で建築許可をしているというような状況です。","id":"exchange-010"},{"speaker":"須貝委員","kind":"質問・要望","question":"都市計画道路の中に入ってたの？」とか、そういうちょっと困惑などで、行政にちょっと不満を持たれる方もあるかと思いますが、あらかじめこういうときは、そういうのは了解のもとでやっているんですから、その辺はぜひきちんと説明していただいて、ご理解を得るようにしていただきたいと思います。私、ちょっと１点、不燃領域率っていうのがありますが、これは、中身としてどういうことでしょうか。","respondent":"伊勢住環境整備担当課長","answer":"空地の場合は、庭先の狭いところだとかそういうことではなくて、基本的には幅６メートル以上の道路、それから、半径１０メートル以上の土地、これらを空地といっております。","id":"exchange-011"},{"speaker":"須貝委員","kind":"意見","question":"そういう意味合いですね。わかりました。今回の２９号線もそうだと思うんですが。そのときに、多くの方は、できればそこに住み続けたいという希望があるかと思うんです。これから区のほうで一軒一軒おそらく交渉していくのかと思うんですが、本当に今、２０年、３０年、場合にすれば５０年、１００年かかる事業だと思うんですね。このままいけば。それをちょっと希望として言わせていただきます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-012"},{"speaker":"堺委員","kind":"質問","question":"それで今度は、あしたですか、第１１回目のまちづくり協議会がある予定になっておりますけれども、それを踏まえて、この資料によりますと、平成１９年４月に密集事業の実施となっていますから、そういう手順でもう、要するに尽くすべき説明はもう全部これで終わったので、もう皆さんにご理解とご協力いただいているという前提で、４月から実施しますよというふうに我々、理解するのか。","respondent":"伊勢住環境整備担当課長","answer":"事業開始前にニュース等でお知らせをするという形で、説明会は特に予定しておりません。","id":"exchange-013"},{"speaker":"堺委員","kind":"意見","question":"そうすると、事業は、もう説明すべきことはしたと。事業は始めると。必要に応じて、ニュースで伝えるんだと。全体的に集まってもらって説明することはもうないと。何かあれば個々にというふうにとれたんですが、もう１回、ちょっと。","respondent":"伊勢住環境整備担当課長","answer":"尽くすべきかどうかというのは、出席者が全体からするとそんなに多くありませんので、そういう面では、ニュース等でまたお知らせするということはありますが、全体の方に、またお呼び立ててやることはないんですが、ニュースでは、問い合わせ先だとかそういうこともありますので。","id":"exchange-014"},{"speaker":"堺委員","kind":"質問","question":"なるべく手短にと思いますが、今お話しされていましたように、総事業費３０億という予算をかけてやるについても、今お話しのように住民の皆さんのご理解とご協力をいただかなかったら、遅々として進まないわけですから、そういう意味での、これからこちら側として進めていくには丁寧にというふうに思います。どういうふうなお答えをこのときされておりましたか。","respondent":"伊勢住環境整備担当課長","answer":"それで、また広げるだけではなく、不燃性の建物への建て替え、耐震性の高い建物に改善することで防災性の向上につながるということを説明するとともに、４メートル道路の幅員じゃ難しいんですけども、６メートルに拡幅した場合の電線地中化については今後。","id":"exchange-015"},{"speaker":"堺委員","kind":"質問・要望","question":"要するに、ここ６メートルに幅員拡幅するわけですから、ぜひそういうことを前提に、念頭に置いてお願いをしておきたいなと、こういうふうに思います。地元としては、もう大歓迎。１日も早く、そういう形で整備していただきたいと思うんですが、この地図の中に、そういうあるところが示されておりますけれども、見通しというんですかね、腹案というんですか、大体この辺でと、そんなものはあるんですか。","respondent":"伊勢住環境整備担当課長","answer":"それで、協議会の方々にもそういう土地情報、こういうものをできるだけ寄せていただいて、例えばですけれども、どこかで引越しで建物を壊してどこかへ行ってしまうとか、あるいは区のほうとしては駐車場のところで公園にならないかとか、地域に入ってやっていく予定です。","id":"exchange-016"},{"speaker":"堺委員","kind":"質問","question":"そうすると、積極的にあの辺も、土地情報というのは、不動産屋が持っているんですかね。それで、要するにお願いしたいのは、こういうところについては、やっぱりこの計画どおり、防災上というんですかね、いろんな面からやっぱりこういうふうにとらえて進めていくことが必要だろうということを思いますので、ここに住んでおられる方々の意向はどうなんでしょうか。","respondent":"伊勢住環境整備担当課長","answer":"それで、区としては、ここがなかなか一軒一軒を訪ねるのは難しいですので、基本的には共同化ということを考えてありますが、８０戸以上ありますので、そういう面では、一遍に８０戸というのは難しいですので、その辺の進め方、皆さんどういう、積極的な方もいらっしゃいますし。","id":"exchange-017"},{"speaker":"堺委員","kind":"質問","question":"ですから、今の例えば大井町の駅の東急の向こう側でしたか、忘れちゃったんだけど、今、密集地帯がありますが、元のイトーヨーカ堂の周辺。Ｃ地区と言うんですか、あそこもそういう計画があったけれども、なかなか地権者のご理解とご協力をいただけなかったというふうに言っていいのかどうかわかりませんが、計画は計画なんだけれども、現実には進まないというか、進められない。","respondent":"伊勢住環境整備担当課長","answer":"これと類似したのが、例えばここの一番下の延焼遮断帯形成ゾーンとかというのも二国通り沿いで、基本的にはその高層というと、条件といいますか、容積だとかそういうのもありますから、そういうのを追認と言いますか、現状を踏まえた形でゾーンの位置づけをしたということです。","id":"exchange-018"},{"speaker":"堺委員","kind":"質問","question":"おわかりでしょうか。公園というふうに位置づけているのかどうかわかりませんが、あそこに、駅に行く人なんでしょうか、ごみを捨てていってしまって、大変な悪臭と合わせて大変なことになった。できれば、あの辺もちょっとよく商店街の方とご相談いただいて、そういうことのないような形で、何か工夫されていったほうがいいかなという気がするんで、その辺、いかがでしょうか。","respondent":"伊勢住環境整備担当課長","answer":"そのときに、具体的にどうこうというようなご提案は特にありませんでしたけど、例えばベンチを置くのかとかいうようなお話が出ましたけど、今後、協議会でまたその話が出ると思いますので、そういうときは、どういうご希望があるのかを所管に伝えて。","id":"exchange-019"}]},{"id":"topic-02","title":"の２その他","agenda":"の２その他","exchanges":[{"speaker":"鈴木（ひ）委員長","kind":"質問・要望","question":"皆さんからご意見をお伺いしたいのは、本委員会に付託された２つの調査項目である災害に強い街づくりに関すること、および安心・安全のまちづくりに関することについて、これまでの委員会活動を踏まえて、調査を完了すべきか、または継続にすべきかという点です。何かご発言ありますでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-020"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/900262?Template=document&Id=6342#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=16&TermStart=2007-01-01&TermEnd=2007-12-31"}],"sourceMeta":{"pages":0,"characters":20671,"voices":53}},{"id":"h19-20070301-14","meetingId":"h19-cm03","date":"2007年3月1日","dateIso":"2007-03-01","committee":"行財政改革特別委員会","time":"午前１０時０２分～午後１時４６分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を69件抜き出しています。","topics":[{"id":"topic-01","title":"１の特定事件調査を行います。 （１）の民間委託等に関すること","agenda":"１の特定事件調査を行います。 （１）の民間委託等に関すること","exchanges":[{"speaker":"井上委員","kind":"質問・要望","question":"確認をさせていただきたいと思うんですけれども、これ、モニタリングは、今回、策定に当たり、区の中のメンバーが策定をしたものなのか、それとも委託でベースのものがあって、それを参考にしているものなのかということが１点と、今回、この行財政改革特別委員会に提示をし、即決定ということで、先ほど、平成１９年度より運営されるということをおっしゃっていましたけれども。","respondent":"堀越行財政改革担当課長","answer":"そういったことを踏まえて、このＰＤＣＡのサイクル、このモニタリングのサイクルをきちんと確立をしていきたいということがあります。ですから、平成１９年度より運用を開始していきたいというふうに考えております。","id":"exchange-001"},{"speaker":"井上委員","kind":"提案","question":"そういう意味では、もうこれが今期最後ですけれども、こういった外部評価のときの冊子もそうですけれども、ぜひ議会として提案をする必要があるかと思いますけれども、２日前の資料提供ではなく、こういったもの、ただ追認機関ではないわけですから、資料提供を早くしていただくような形で、行政にも今後の課題としてお願いしたいということを、一応。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-002"},{"speaker":"中塚委員","kind":"質問・要望","question":"井上委員から資料のお話がありましたけれども、僕も同感です。具体的な質問ですけれども、この資料自体は、おそらく区と指定管理者との共通認識をつくるためのガイドラインなのかなとは思うんですけれども、この中で議会の位置づけというんですか、これがちょっと見る感じ浮かんでこないんですよね。","respondent":"堀越行財政改革担当課長","answer":"もちろんこれまでもいろいろ議会のほうからご意見もいただいていますし、必要に応じてご報告するべきものはご報告していくというような考えは変わってございません。","id":"exchange-003"},{"speaker":"中塚委員","kind":"質問・要望","question":"必要に応じて報告とありましたけれども、例えば具体的に５年間の指定管理者の期間であっても、８ページにありますけれども、指定期間の３年目が終了した事業については評価をしますというふうに述べられていますけれども、では、少なくとも３年目以外に対して報告をするというものはあるのか、それもなくして適宜という、それではちょっと議会の位置づけはどうなのかなと疑問に思ってしまうので。","respondent":"堀越行財政改革担当課長","answer":"このガイドラインをやっていく中で、３年目終了時評価というお話がありましたけれども、その中でいろいろやりながらまた必要に応じてと先ほど申し上げましたのは、やりながら適宜といいますか、ご報告をするという考え方はまず基本のベースであります。","id":"exchange-004"},{"speaker":"中塚委員","kind":"質問","question":"ただ、そういうところを一般的に適宜だけでくくられてしまうとどうなのかなという気がして否めないんですよね。適宜というお話で、具体的に例えば伺いますけれども、例えば、３４ページ、３５ページ、３６ページ、３７ページに記されている総括シートや事故報告書、その個人情報部分は除いて、行政情報の部分は公開の対象として考えているのか。","respondent":"堀越行財政改革担当課長","answer":"情報公開については、情報公開の条例にのっとって対応していくという形で考えてあります。","id":"exchange-005"},{"speaker":"中塚委員","kind":"確認","question":"情報公開のほうは、３４ページから３７ページのこの報告書の中身は基本的な行政情報部分に関しては開示をしていくということでよろしかったのか確認をさせてください。ということは、指定管理者のそこの人員配置、例えば管理職が何人で、一般職員が何人で、それを含めた人員配置なのかどうかちょっとわかりませんけれども、その職員配置の状況は、今後つかんでいきますよということなんでしょうか。","respondent":"堀越行財政改革担当課長","answer":"情報公開の話です。この総括シートの部分については、条例に基づいて公開をするです。それから、人員の部分についてですけれども、これについては、先ほどから繰り返しの答弁ですけれども、そういった部分は必要に応じてという形で考えているところです。","id":"exchange-006"},{"speaker":"中塚委員","kind":"質問・要望","question":"要は、指定管理者を決めるときの人数と、１年たって、２年たって、実は中身の人員配置が変わっていて、行政はそれでいいと思っているかもしれないけれども、議会のほうでいいのか悪いのか意見を求められますと、僕らの知らない間で人員配置、安全の最も重要な機構ですから、そこがいつの間にか変わってしまっているというのは、見過ごせる話ではありませんので、適宜というよりも。","respondent":"堀越行財政改革担当課長","answer":"それによって何か重大な欠陥等、取消事由につながるようなことがあれば報告ということはあり得るでしょうけれども、一定のモニタリングの中で必要に応じてご報告等は考えていきたいというのは、先ほどからご答弁させていただいているとおりです。","id":"exchange-007"},{"speaker":"中塚委員","kind":"意見","question":"最後にちょっと、人員配置を把握するというお話ですけれども、人員配置と一言で言っても、数なのか、それとも事業によっては資格を持っている者、持っていない者のその数もあるでしょうし、いわゆる人員配置を把握するとは何を具体的に把握をすることを意味しているのか、ちょっと具体的に人員配置とは何を指しているのか、最後にご説明いただけますか。","respondent":"堀越行財政改革担当課長","answer":"社会福祉の関係のそういった福祉施設設置基準等があるところと、それから、わりと価値観的なところと、そういった部分、いろいろ施設の特性に応じて把握をしていくという、そういうことです。","id":"exchange-008"},{"speaker":"安藤委員","kind":"質問","question":"今の中塚委員の質問にちょっと関連するかもしれないんですけれども、同じ２７ページの人員配置、２６ページのところの趣旨でもありますけれども、公共サービスの質や量を維持・向上させていくため、あるいは、業務の適正執行を担保するためには、それに対応した組織や人員の配置が確保されていることが前提ということで、一定。","respondent":"堀越行財政改革担当課長","answer":"労働条件については、それぞれ法人が労働関係法令にのっとって適正に行うということが基本ですので、区としては、業務、より良いサービスの向上と、それから効率的な執行がどのように図られているか。","id":"exchange-009"},{"speaker":"安藤委員","kind":"質問","question":"本日付の新聞でも、地方自治体の側で偽装虚偽があったというような報道もありましたけれども、そういったことにのっとって行われるのが当然だと思うんですけれども、必ずしもそういったことが行われていない場合もやっぱりあると思うので、やはりそれは民間委託する側の行政がしっかりとそういったことが絶対ないようにきちんと管理といいますか、状況を把握して。","respondent":"堀越行財政改革担当課長","answer":"ただ、それに対して日常的なチェックといいますか、指導等については、その法人のほうで対応すべき問題というふうに考えております。","id":"exchange-010"},{"speaker":"安藤委員","kind":"質問","question":"これはあってはならないことなんですが、万が一、法令順守がなされていないということが判明した場合の区の対応だけ教えていただければと思うんですが。","respondent":"堀越行財政改革担当課長","answer":"労働基準監督署等によりまして対応がなされるものと考えております。その対応状況等を見ながら、また必要があればその時点で判断をしていくという、こういうことになろうかと思います。","id":"exchange-011"},{"speaker":"伊藤委員","kind":"質問・要望","question":"質問は、このガイドラインの位置づけ、つまり、今日いただいたものを区はどういう位置づけとして、どう活用していくかということの説明がなかったように思われますので、そのことについて改めて説明をいただきたいのが１つと、それから、最も大切なことは、今度は指定管理者、業者側から出てきたいろいろなものを品川区は的確に測定をして判断しなければいけない責任が出てきたわけです。","respondent":"堀越行財政改革担当課長","answer":"このガイドラインの位置づけですけれども、区の指定管理者に関する考え方ですが、まず基本方針といたしましては、この後ろの部分についてあります指定管理者制度活用に係る基本方針、これが基本原則になるものです。","id":"exchange-012"},{"speaker":"伊藤委員","kind":"質問・要望","question":"そのところの最終的な力量を判断する仕組みを品川区が責任をとっていくわけですから、実はそのことをきちんと担保しなければいけないと思っていますので、そのことについて再度確認の答弁をいただきたいのと、それから、こういう評価等々をしていくことによって、今度は結果として次年度の契約につなげていかなければ意味がないわけですよね。いろいろ自分で評価していました。","respondent":"堀越行財政改革担当課長","answer":"次年度へつなげていくという部分ですけれども、こちらについては、指定管理者の場合、品川区の場合、基本的には基本協定で５年間という形で協定を結んでいる、指定期間が５年間という形ですけれども、その中で先ほどご説明した３年目の終了時評価ですとか、それから。","id":"exchange-013"},{"speaker":"伊藤委員","kind":"質問","question":"これで最後にしますが、もう１つは、２５ページにある再委託、これが新しい項目として出てきたんですね。これも本当に大きな問題だと思います。ある程度実績を踏んだ上でまた別のことを考えていくとか、そんなことはできないと思いながら言っているんですけれども、そこまである程度縛りをかけていかないと、立ち上がるまではちょっと怖いなという感じがするんですが、このことについてはいかがでしょうか。","respondent":"堀越行財政改革担当課長","answer":"それで、再委託の部分についてですが、施設の中で例えば設備的な部分ですとか、専門的なノウハウの部分については、どうしても再委託という形にならざるを得ないというか、これはもうどうしても避けられない部分だと思いますので、ここの部分について。","id":"exchange-014"},{"speaker":"川西委員","kind":"質問・要望","question":"ですから、さっきの所管職員との関係があるんですが、やりっ放しというのはいけないと思うんです。そういう点で、しっかりちゃんとした組織をつくるべきだというふうに思います。ですから、日常的に適切な運営なり、区民サービス、利用者サービスが行き届いているかどうかというのは、やはりこういうものを通して日常指導だというふうに思っていますので、これは最後は意見です。２つだけお答えください。","respondent":"堀越行財政改革担当課長","answer":"今回、全庁的な検討会を設けて指定管理業務にかかわる担当課長、それから係長等を集めまして議論をしながら進めてきたというところです。","id":"exchange-015"},{"speaker":"川西委員","kind":"意見","question":"この中にもありますけれども、異動とか新任時の研修とか書いてあるんです、何ページでしたか、そのように企画財政課で担当なさる場合でしたら、課長、係長だけが承知していたのではだめです。担当職員のところへ行って指定管理者の指導をするだけの研修が必要だと思います。新任、異動の場合の研修、これをぜひ考えていただかないと、温かい指導ができないと思います。よろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-016"},{"speaker":"須藤委員","kind":"質問","question":"指定管理者の制度が入ったんだけれども、指定管理者に最初、こういう事業をお願いしますということをお願いしておいて、それが今度、拡大、いろいろ行政の施策の中で拡大してくるような場合には、その辺の考え方がどうなのかということと、逆に縮小していきますよと、それから、もっと言えば、５年の計画をしたけれども３年でやめてもらわなければいけないよと、あるいは。","respondent":"堀越行財政改革担当課長、新美企画部長","answer":"指定管理者の業務の拡大の部分ですけれども、施設の設置条例がございまして、その中の設置目的等がございまして、その中で指定管理の区として管理をお願いするという部分で、その中で、先ほどご説明した年次協定の中で。それは事例事例で適切に対応していくということになるかと考えています。","id":"exchange-017"},{"speaker":"須藤委員","kind":"質問","question":"ですから、そういったことがこの指定管理者制度と議会との関係というもののありようが、管理者にどうのこうのというのではなくて、もう少しこの点は詰めていかないと、新しい制度なので、いろいろなことが出てくるなと思っているんですよね。そういったいろいろな難しさが今後議会との関係で出てこようと思うんだけれども、そのあたりについてはどういうふうに考えているか。","respondent":"新美企画部長","answer":"今、ご質問のありました新規に、特に施設を新設、新築する場合は、一定の候補者の期間が一定期間あるということで、それが最終的に条例で指定の議決をいただくまでの間に数年間の時間がある場合につきましては、導入時ですが。","id":"exchange-018"},{"speaker":"藤田委員","kind":"質問・要望","question":"ですから、その受けた業者がどういうサービスをノウハウを使って知恵を絞って実施をしていくか。そのチェックというのは、今回、今日ありましたけれども、その中に私は大事なのは、区民の意識、受け手をどういうふうに吸い上げていくかというのが大事だと思うので、その辺はちょっとどういうふうにお考えなのかをお聞きしたいと思います。","respondent":"堀越行財政改革担当課長","answer":"いろいろ苦情とか、要望とか、そういうものも十分にお受けして、そういった部分を吸い上げて、それをどう生かすかによって、よい施設運営のためのきっかけにもなりますので。","id":"exchange-019"},{"speaker":"藤田委員","kind":"質問","question":"ですから、これは例えば５年なら５年、業者にお願いをして、やはり中間的にも利用者会議でも何でもいいと思う、検討会議でもいいと思うんですが、全部が全部できるとは限りませんので、そうしたものを定期的にこれは区としてもお願いをしていくというような、そうした体制をぜひとれないものかどうかと。これは区としても大事な作業だと思うんですが、それだけお伺いしておきます。","respondent":"堀越行財政改革担当課長","answer":"そのほか、今、ご指摘のありました部分について、直接利用者の方の意見を聞くとか、そういった部分もこのガイドラインを運用していく中で十分に検討していきたいというように認識をしております。","id":"exchange-020"},{"speaker":"飯沼委員","kind":"質問・要望","question":"この間、よく、あってはならないんですが、特に人にかかわる、高齢者のところ、障害者のところ、あと子どもたちの施設で、労働条件が悪くて虐待が行われているというニュースもこの間たびたび出ていますけれども、そういった面で人にかかわる部分で、ご本人が言えない、発言できない問題とか、見えない問題とか、そういう部分をどうつかんでいくのかが大事で、私は、そういった意味では。","respondent":"堀越行財政改革担当課長","answer":"年間を通じた評価ですけれども、まず第１点目といたしまして、その部分については、もちろん日ごろからの意見交換ですとか、それから、日常的な協議、それと、場合によっては、先ほどもご説明しましたけれども、現場を区のほうで視察するという。","id":"exchange-021"},{"speaker":"飯沼委員","kind":"質問","question":"その辺で議会が直営と同じような状況でチェックができるのかどうか、その辺をちょっとお伺いしたいのと、あと、情報公開のところなんですけれども、２５ページの、先ほど、再委託先管理についてというところで、原則禁止をしているけれども、やむを得ず使うところもあるということだったんですが、この再委託先の状況についても同じようにきっちりと情報公開がされて。","respondent":"堀越行財政改革担当課長","answer":"再委託先管理の情報公開の部分については、必要に応じて再委託先のほうでそういう指定情報については区のほうで情報を求めていくというような、そういった区と協議を進めながら対応していくという形になるのが基本だと思います。","id":"exchange-022"},{"speaker":"飯沼委員","kind":"質問・要望","question":"不正防止のところなんですけれども、適宜議会に報告ということなんですけれども、議会が直営と同じようにチェックができることになるのかどうか、そのところを再度お尋ねをします。","respondent":"堀越行財政改革担当課長","answer":"先ほどご説明をいたしましたけれども、いろいろな委員会の場、それから予算特別委員会、決算特別委員会の場等もありますし、例えば事務事業概要の中でそういった施設についてご質問いただくですとか、いろいろな場面でご報告をするというふうに考えているところです。","id":"exchange-023"},{"speaker":"飯沼委員","kind":"質問・要望","question":"最後のところが、直営と同じようにチェックができる仕組みになるのかという、そこを答えていただきたい。","respondent":"堀越行財政改革担当課長","answer":"繰り返しになりますけれども、予算特別委員会等の中でご意見、ご質問いただく形で十分チェックしていただけると考えています。","id":"exchange-024"},{"speaker":"中島委員","kind":"質問","question":"このモニタリング・評価のプロセスの中でアンケートの実施というのがあるわけなんですが、これを見ていますと、このアンケートの実施というのは、指定管理者が行うということでしょうか。","respondent":"堀越行財政改革担当課長","answer":"基本的には指定管理者側のほうで行うです。","id":"exchange-025"},{"speaker":"中島委員","kind":"質問","question":"そのアンケートなんですが、利用者に対するアンケート調査でしょうか。それとも、それ以外の方なのか、利用者を面倒を見ていらっしゃる方、家族とか、そういったところからもアンケートをとるのでしょうか。","respondent":"堀越行財政改革担当課長","answer":"施設の性格にもよると思うんですけれども、基本的には利用者の方を考えています。福祉施設等によっては、利用者の家族の方ですとか、そういった部分についても考えられるかなです。","id":"exchange-026"},{"speaker":"中島委員","kind":"質問","question":"そこのところが一番難しいかなと思うんですが、指定管理者がアンケートをとると、中には利用者がそこでお世話になっているという立場になっている場合もありますので、果たして自分が思っていることを十分にアンケート調査に答えられるのかどうか、その辺に対する配慮はどういうふうにしていらっしゃるかお伺いします。","respondent":"堀越行財政改革担当課長","answer":"今ご質問にありましたけれども、福祉施設などについては、そういったことは考えられると思いますので、そういった面につきましては、サービス向上委員会ですとか、第三者の評価ですとか、活用できる部分は活用しながら。","id":"exchange-027"},{"speaker":"中島委員","kind":"質問","question":"第三者評価の方がアンケートをとるということですか、そういった場合は。","respondent":"新美企画部長","answer":"ただ、確かに福祉施設については、その利用者と運営者の関係が大変密でありまして、今ご質問にあったような現実的な意見を聞かれるとか、要望を聞かれるということがある実態もありますので、それは品川区としてはサービス向上委員会でこの間さまざまな形で、具体的に、じゃあ。","id":"exchange-028"},{"speaker":"中島委員","kind":"質問・要望","question":"確かに今、この福祉の施設に対しては、そこを利用されている方の声を何か区のほうでほかの形で吸い上げてあげなければいけないんじゃないかなというのは、やはり私たち現場の中でいろいろな形で情報が入ってきているわけです。ですから、その辺はしっかり情報を集めていただいて、また、より良い運営ができるように指定管理者に指導していただきたいと要望しておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-029"},{"speaker":"伊藤委員","kind":"意見","question":"それについての指導はこれに基づいてどういうふうにしていくのか。落札した後、これが見られるということになると、いろいろな大変な努力が生じてくる可能性がありますし、むしろこういう評価があるからということを先に区側が情報提供した上で、業者側のいろいろなプランをつくってきていただいた上で応札したほうが、と思われますので、その２つをお答えください。","respondent":"堀越行財政改革担当課長","answer":"それとあと、協定書のほうにもモニタリングという項目を入れて対応をしていくという予定です。","id":"exchange-030"},{"speaker":"井上委員","kind":"提案","question":"だから、その辺のところを考え方としてそれがたくさん起こってくるという状況は好ましくないと思うので、その辺をどういうふうに考えていらっしゃるのかということと、あと、先ほど要望として終わらせたんですけれども、資料提供の段階でこれで十分だという委員の意見もありましたが、区長の方針である区民の声を聞くとか、そういった意味では情報提供があってそういうことにつながると思いますので。","respondent":"堀越行財政改革担当課長","answer":"その定着をさせ、より良い施設運営を図っていく中で、その公表の部分についてはまた検討をしていきたいというように考えています。","id":"exchange-031"},{"speaker":"井上委員","kind":"提案","question":"一番最初のところの公表の部分、定着をさせていきたいということはもちろんだと思いますし、先ほど、飯沼委員が言ったように、これがまた改訂というところまでは行かなくても、やっていく上で見直しも含めて議論が必要であるというところの認識があっていただければそれでいいと思うんですけれども、しかし、どういう改善があったのかということを私たちも区民の方から伺って。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-032"}]},{"id":"topic-02","title":"の特定事件調査のまとめ","agenda":"の特定事件調査のまとめ","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"ですから、ここを変えるか、それとも一致できなければ両論併記をすべきか。それとあと、一番下の４の小中一貫校６校構想のところを、若干文言は変わりましたけれども、跡地の活用、やっぱり学校の統廃合が前提になっている内容ですから、これは私たちと意見は違う。この２点を含めて、どうして両論併記にしなかったのか、そこを委員長のご意見も伺いたいんですけれども、いかがでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-033"},{"speaker":"中塚委員","kind":"質問","question":"「原則社会福祉法人」であれば、その辺の意向をちょっと伺いたいのと、４のところですけれども、小中一貫校６校構想のほうですよね。これは学校跡地の議論を学校統廃合をやっぱり前提にすべきではない。だから両論併記をすべきではないかというのが私の意見であります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-034"},{"speaker":"井上委員","kind":"質問・要望","question":"それで、こういう意見もあったことは事実、そういうことをおっしゃる委員もいることは事実でしたから、ここの４番、この間も言いましたけれども、これが既成事実としてここに載っていくべきではないし、本当にこのまま６校構想を行政は推進しようと思っている立場で区民ニーズがそれに合うかどうかというのは議論がまだこれから分かれるところなので。","respondent":"本多委員長","answer":"前回さまざまな意見をいただいた上で、検討した結果、このような文言修正をさせていただきました。","id":"exchange-035"},{"speaker":"川西委員","kind":"質問・要望","question":"小学校２校、中学校１校があくわけですから、それと同時に、例えば今、要望されている老人施設、子どもの施設はもう要りません。空き状況ですから。ですから、要らないと思うんですよね。何て言うんですかね、ああいうの。ですから、品川区はどっちが重点なのか、私はどっちでも構わないんですけれども、どっちが重点に今の企画部を中心に区がお考えになっているか、それだけ聞いておきたいなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-036"},{"speaker":"須藤委員","kind":"質問・要望","question":"それから４番目も先ほど来いろいろご意見が出ておりますけれども、前回もこの辺で整理をしたと思うんですが。それから、下から２行目のところで、「住民の声を広く求めるとともに、全体的な視点で」というのが、品川区全体的という意味なのか、行政全体的という意味なのかと、とれてしまうので、「区政全般的な視点で」というような表現にしたほうがいいかなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-037"},{"speaker":"飯沼委員","kind":"質問・要望","question":"私、ここはしっかり確認をしていかなければいけないなと思っています。そういった面では、こういうふうに直してほしいんですが、「今後生ずる公有地跡地の活用について」というふうに、もしどうしても学校を入れたいのだったら、（学校等）という言葉で付加をしていくという意味で、あくまでも今後生ずる公有地の跡地についての活用について論議をしてきたというまとめにしていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-038"},{"speaker":"須藤委員","kind":"質問","question":"今の４番目は、全体でまとまるなら、いわゆる学校跡地の利用なので、それはそれで今後生ずる学校跡地にというので、いわゆる６校構想云々という前提でとかといろいろ話があるけれども、あれは基本計画の中に構想として出てきているんですから、それはもう当然前提の話だろうと我々は認識しています。この６校構想とまた違った考え方が。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-039"},{"speaker":"井上委員","kind":"意見","question":"今のところでは、６校構想の計画というようなところを削除して、今後生ずる学校跡地ということで飯沼委員の言ったところに対して、他の委員からもそれでというようなご意見だったと思うので、私もその部分で言えば、今後生ずる学校跡地というのは、本当に適正配置の設置の検討会も始まるという意味では、子どもたちの数も減っているという意味で、そこら辺は先のこととして予測されることでもありますので。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-040"},{"speaker":"藤田委員","kind":"提案","question":"この（２）については、これは丁寧な意味で（社会福祉法人等）という委員長のほうでご提案されたのではないかと思うんですが、もしどうしてもこの「等」に異議があるのであれば、これはとっても私は差し支えないと、民間事業者というふうにしても、それは一向に構わないというふうに私は思うんですが、しかし、委員長が丁寧に括弧して、その「等」というのを提示されたということ。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-041"},{"speaker":"伊藤委員","kind":"質問","question":"中身に入るつもりはありません。ですから、上の部分、前書きの部分で、例えばそういう意見もあったという表現はできるかもしれませんが、あくまでまとめは、当委員会として１つの方向性を示すべきでもあると思っていますので、最終的には正副委員長に一任していこうと思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-042"},{"speaker":"中島委員","kind":"意見","question":"先ほどから６校構想を入れるか入れないかというお話が出ているんですが、６校構想と決めつけると、やはりアレルギーがあるような感じも受けるんですが、今のところ、品川区では６校構想により学校跡地という問題が出ているのは現実なんですね。ですけれども、６校構想と決めつけるのではないということであれば、「６校構想などにより生ずる学校跡地」と、こうすれば少し気持ちが違うかなと、こう思うんです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-043"},{"speaker":"西本副委員長","kind":"提案","question":"それと４番目については、小中一貫校６校構想ということ自体を議論する場はこの場ではなくて、文教委員会という場がありますので、その場できちんと話をしている段階のものですから、ここをもうちょっと広い意味でのところでということであれば、先ほど須藤委員の提案がありましたように、今後生ずる学校跡地という形で、もうちょっと含みのある。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-044"},{"speaker":"川西委員","kind":"意見","question":"正副委員長にお任せで結構ですが、先ほど発言された須藤委員のご意見で、今後生ずる学校跡地ということに賛成です。それから、言うならば、（２）番目、西本副委員長のご意見ですと、要らないんじゃないかと思います。これであとは正副委員長にお任せします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-045"},{"speaker":"中塚委員","kind":"提案","question":"例えば、４のところで、飯沼委員から先ほど具体的に提案がありましたけれども、「今後生ずる跡地（学校等）の活用については」と、そういう方向で考えていますよとか、あと、この（２）のところで「等」をとるとか、原則社会福祉法人に、やっぱり僕は「等」をとるのが一番いいですけれども、その方向で進めていきたいとおっしゃるのであれば、それはそれですけれども、今のままの報告で。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-046"},{"speaker":"藤田委員","kind":"質問","question":"そうしましたら、「社会福祉法人を含め、民間事業者に委託するにあたっては」とされたらどうですか。ちょっと私の意見ですが。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-047"},{"speaker":"飯沼委員","kind":"質問","question":"今の「社会福祉法人等を含む民間事業者」と言ったら、全く先ほど私が言っている中身に反してしまうわけですよね。ここは本当に厚生委員会の部分でまた突っ込むといけないというのだったら、そっくりこの（２）は削除をしていただくほうが一致するのではないでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-048"},{"speaker":"川西委員","kind":"質問","question":"この括弧を全部とるということは、かえって正副委員長が最初にまとめられたものをまた別の方向でということになりますから、それだったらかえってこのまま入れておいたらいかがでしょうか。だって、社会福祉法人を退いてしまったら、区というのは民間業者で、株式会社中心なのかという意向をこの委員会でまとめたということになりまして、それですと私は承服できない。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-049"},{"speaker":"須藤委員","kind":"質問","question":"民間事業者の中には社会福祉法人も入ってくるんですから、もっと大きな視野に当委員会ではという考え方ですから、それがまるっきり抜けてしまうよという考え方ではないので、民間事業の中には社会福祉法人もあれば、医療法人もあれば、企業もあればという考え方になってこようかと思うので、そういうことを今、ここで１つ「等」を入れる、入れないをやってしまうと大変なので、今。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-050"},{"speaker":"川西委員","kind":"提案","question":"全国的にも、全都的にも、社会福祉法人の存続ということは、別の意味で大変大きな課題になっている。ですから、やはり括弧書きは最初の提案なんだから、むしろ入れておいたほうがいいと、含むということですからというふうに思います。多数決のところですから結構ですよ、このまま通していただいても。それはこだわりませんから。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-051"},{"speaker":"中塚委員","kind":"意見","question":"だから、基本的な僕の意見は、社会福祉法人に限定すべきだと思っているんですけれども、だから、「民間事業者（社会福祉法人）」が嫌であれば、じゃあ、「民間事業者」をとって「社会福祉法人に委託するにあたっては」でないと、もっと悪くなってしまうというのが私の意見です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-052"},{"speaker":"中島委員","kind":"質問","question":"ここの趣旨は、民間事業者にとか、社会福祉法人にとかと、これを決めるところでは、さっき西本副委員長もおっしゃっていたけれども、そういう場ではないと思うんですね。「民間事業者に委託するにあたっては」という、その後の文章が問題だと思うんですよ。ですから、その前のところで論議するのは、この委員会ではなじまないのではないかなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-053"},{"speaker":"須藤委員","kind":"提案","question":"ただ、この議案だけに全部イエス、ノーかというのは、ちょっととり方が乱暴過ぎてしまうのではないかなと思うので、今まで何分間か議論をしてきているので、そのあたりを整理をして、それでいかがでしょうかというご提案をしないと、これを持ってきた、最初からイエス、ノーというのだったら、最初にそういうふうに言ってくれれば、こんなに時間がかからなかったねという思いが出てきてしまうので。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-054"},{"speaker":"井上委員","kind":"質問・要望","question":"今、４番のところでは、大方の合意が得られたのかなというふうに思っていたにもかかわらず、案でと言われたので、また戻ったのかなという、この案に対して賛成ですか、反対ですかと言われれば、反対ですと言わざるを得ないのですが、修正をかけたところは生きるのか生きないのかが、今の委員長の仕切りではわからなかったので、須藤委員のおっしゃるように、合意が少し持てたところについては。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-055"},{"speaker":"須藤委員","kind":"提案","question":"ですから、そういったものを斟酌していただけるのかどうかということも含めて討論していただかないと、そのあたりは私自身は、せっかくの提言ですから変えていったほうがいいかなという思いがあるので、最初にどうしても合わないからこの文でという形になれば、集約的にはそうならざるを得ないだろうけれども、できるだけこういった議会全体的には。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-056"},{"speaker":"伊藤委員","kind":"意見","question":"結果としてまた委員会が午後になるかもしれませんけれども、ここまでそれぞれ意見が出ている中でやって、採決の方法も出てきた、それから文言の整理も出てきた、そういうものを整理していただいた上で、再度委員会を開いたほうが私はいいと思いますので、これは意見として述べさせていただきました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-057"},{"speaker":"須藤委員","kind":"提案","question":"ですから、それはそれで了として、今一番決をとったりどうなのというのは、民間事業者という言葉でいいのか、そこに括弧して（社会福祉法人等）を入れていくのがいいのか、まるっきり社会福祉法人にしなさいというのが共産党のご意見なので、それがいいのか、そこだけが今、引っかかっているところだけなので、あと私が何点か文言を変えてくださいというようなご提案をさせていただいているので。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-058"},{"speaker":"飯沼委員","kind":"意見","question":"「今後生ずる公有地跡地」と入れるならば（学校跡地）を入れたらどうかということで、もろ学校跡地という意味で言ったのではないので、ちょっとこの表現では納得いかないなと思うのが１つと、あと、１の（２）のところ、（社会福祉法人等）をとっていただけなかったので、これだと本当に民間事業者、民間、営利の企業も含めて進めていくという中身になるので、申しわけないんですが。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-059"},{"speaker":"須藤委員","kind":"質問","question":"私たちは、全体的な先ほど来議論させていただいて、最大公約数の集約をしていくということで、我々も４番目の現在云々という６校構想というのを削除してもやむを得ないでしょうというような考え方で歩み寄ってきていますので、先ほどお話がありました１の（２）のところについては、福祉施設がいわゆる民間委託する場合には、ノウハウを最大限に生かせる仕組みづくりをしなさいということなので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-060"},{"speaker":"中塚委員","kind":"質問・要望","question":"ほかの特別委員会、委員会を見ましても、いわゆる議長から求められているものは、活動現況報告ですよね。それに対して、あえて今回、提言というふうに踏み込んだその意図は、委員長自身にもお伺いしたいんだけれども、審議を通じて一致したところで提言を出す。委員長に一言伺いたいのは、先ほどの提言をまとめる、そこを今回、活動現況報告ではなくて提言に至ったと、それはなぜなのか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-061"},{"speaker":"中塚委員","kind":"意見","question":"みんなの意見を集約するという委員長のお考え、そのとおりだと思うんですよね。であるならば、なおさらこの「等」の言葉は、単に言葉の問題ではなくて、私たちはここに株式会社が含まれていると、だから一致できないという、そういう意見なんですよね。だから、一致できないところは提言として上げるのは正しい形ではないのではないのかなと私は思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-062"},{"speaker":"中塚委員","kind":"提案","question":"この民間委託に関することの、今回も「提言いたします」という中身ですけれども、この前文の「真の住民サービスの向上を図る必要がある」と、そのいわゆる具体化として下に１、２、３、とありますけれども、じゃあ、いわゆる議会が提案するんだけれども、議会がどうチェックするのか、その担保が具体的にここに記されていないと思うんですよね。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-063"},{"speaker":"飯沼委員","kind":"質問・要望","question":"今の続きなんですが、一番最後のところに、４として、ぜひ議会としてのチェックの担保を書き込んでほしいし、この間、再三申し上げているように、民間委託をすべてよしとするのではなくて、メリット、デメリットを検証するということもたびたび申し上げていたんですけれども、ぜひ４点目で加えていただきたいのが、議会と区民に情報を公開するとともに、民間委託で生ずる問題点の検証を行う。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-064"},{"speaker":"須藤委員","kind":"質問","question":"前回、たたき台をやって、ある程度、そういうご意見等は前回に出してくるべき話なので、そこで文言訂正を今回されてきているので、新しい項目、新しい項目と、こうやり出すと、また今日まとまらなくなってしまうのだろうと思うので、今のご意見等を踏まえると、３番に「委託効果が区民に十分発揮できる」というような、「区民に」というところを入れていただくと、そういった。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-065"},{"speaker":"中塚委員","kind":"意見","question":"議会がどうのというお話がありましたけれども、議会として行政にいわば注文をつけるわけですよね。ちゃんと議会に報告してください、徹底してください、区民にも情報を開きなさいと、その仕組みの担保をつくりなさい、そういうのがなければ、じゃあ、委員会の提言とは何なのかと、行政がつくったルールをそのままどうぞという、そういうわけには私はいかないなというふうに思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-066"},{"speaker":"中島委員","kind":"質問","question":"議会がチェックというお話が今出ているんですが、情報を議会に全部提示して果たしていいのかどうかということもあります。ですから、それとチェックのところというのは、予算でも、決算でも、また意見を申すところはいっぱいあるわけです。ですから、そういった意味では、やはり区民の意見がしっかり反映されるようにという、今、須藤委員のお話、私はいいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-067"},{"speaker":"飯沼委員","kind":"意見","question":"態度表明をしますけれども、先ほど来、この間もずっと申し上げてきたことだし、前回もかなりはっきりとご意見申し上げたんですが、特にこの特別委員会で１年間論議してきたという意味では、議会のチェック機能をしっかりとこの中に担保していくというのが最も大事であるし、あと、民間委託すべてよしではなく、メリット、デメリット、この検証こそが大事であったと思うんですね。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-068"},{"speaker":"西本副委員長","kind":"質問","question":"皆様、１年間ありがとうございました。副委員長という大役をどこまで果たせたかはわかりませんけれども、皆様の活発なご意見をいろいろお聞きしまして、ますますこの特別委員会が発展していくのではないかなという、そういう感じを受けました。今後とも継続的に理事者の皆様と一緒にこの委員会が発展できることを祈りつつ、感謝を述べてお礼を申し上げたいと思います。本当にありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-069"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/190566?Template=document&Id=5816#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2007-01-01&TermEnd=2007-12-31"}],"sourceMeta":{"pages":0,"characters":49025,"voices":132}},{"id":"h19-20070305-3","meetingId":"h19-c-budget","date":"2007年3月5日","dateIso":"2007-03-05","committee":"予算特別委員会","time":"午前１０時０４分～午後５時５９分","status":"正式会議録","sourceType":"formal","overview":"予算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を134件抜き出しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"中塚副委員長","kind":"質問・要望","question":"第１項、理事および理事会の設置についてです。１人当たりの質問時間は、答弁時間も含めて、１０分、１５分、２０分のいずれかとし、会派で割り振ることとしております。なお、無所属の委員の質問時間は、答弁時間も含めて１０分といたします。終了時間のお知らせにつきましては、残り時間がなくなった時点で振鈴を２回鳴らしますので、質問の途中でありましても直ちにとりやめていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-001"},{"speaker":"大沢委員","kind":"確認","question":"おはようあります。第１点目なんですが、子どもすこやか医療費助成、これは新規事業ということで、本年の１０月から実施をされるということになりました。これは１,４００万円ということで増額をされているわけですが、確認といたしまして、この増額分は中学生の拡大された部分の増額と考えてまずいいわけでしょうか。確認をさせてください。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-002"},{"speaker":"大沢委員","kind":"質問","question":"すみません。間違いました。ちょっとチームワークが乱れました。申しわけありません。じゃあ、すみません。約１,４００万円の追加になるわけですけれども、この追加分、自己負担額と入院時の食事の負担金ということなんですけれども、どういうふうにこの金額が算出をされたのか教えてください。","respondent":"諸岡児童課長","answer":"そういったことで算定をいたしまして、約１,４００万円強の補正ということで、このたびお願いしているわけです。","id":"exchange-003"},{"speaker":"大沢委員","kind":"質問","question":"１２.７回ということが基準になっているということなんですけれども、１２.７回、この数字に関しては、他の区と比べて多いほうなんでしょうか、少ないほうなんでしょうか。","respondent":"諸岡児童課長","answer":"１人当たりの受診回数におきまして、他区との比較というのはちょっとしてございませんけれども、概ね同程度というふうに考えてあります。","id":"exchange-004"},{"speaker":"大沢委員","kind":"質問","question":"自己負担額が３割、これが区からということで無料になるということですけども、先ほどちょっとお伺いしました入院時の食事の標準の負担金というのは、幾らなんでしょうか。","respondent":"諸岡児童課長","answer":"入院時の自己負担額ですけれども、保険適用のほうで算定をやっていまして、今ちょっと金額は具体的に把握してございませんが、それについて自己負担額がなくなるように助成をしているというものです。","id":"exchange-005"},{"speaker":"大沢委員","kind":"質問・要望","question":"ちょっとすみません。その次に、入院時食事標準負担金ということですから、標準ということで今お伺いをさせていただいたわけですが、この数字が出てくるからには、負担額というのも数字が出ているだろうと思いますので、おわかりになりましたら、また後ほどでもいいので教えていただきたいと思います。その充実をしていただくようにこれは要望して、次の質問に移りたいと思います。","respondent":"谷田部健康課長","answer":"１点目の不妊治療の減額ですけれども、平成１８年度新規事業で取り組んだ事業でございまして、平成１８年度当初におきまして、一般不妊治療にかかわる検査も含めた治療費、それから人工受精という二つの助成内容に分けて制度を組み立てたものでして。","id":"exchange-006"},{"speaker":"大沢委員","kind":"意見","question":"不妊治療のほうで、２５０名あるだろうという予想で、実際なかったということで、そのなかったということ、決して揚げ足をとるわけじゃないんですが、知らない方もかなりの数いらっしゃると思うんですけれども、区の事業を区民の方に広報する場合に、私思うんですけれども、広報の仕方、確かに区のほうは一生懸命されているんでしょうけれども、一つ最後の何かコショウ、味の決め手。","respondent":"谷田部健康課長","answer":"それと、不妊治療に取り組める医療機関というものを私ども独自に調査いたしまして、そういうリストで私どももご案内をすると同時に、これは平成１９年度予算の中身の話になってしまいますけども、１年間やった結果を。","id":"exchange-007"},{"speaker":"大沢委員","kind":"質問・要望","question":"所得制限の撤廃とか、もろもろいろんな使いやすい制度にしていただいて、それをより充実して皆さんに周知できるような体制をつくっていただきたいと思います。すみません、あと３分ちょっとになりましたので、次の質問に移らせていただきます。最初からそのような形でわかっていれば、何も補正をプラス・マイナスしなくてもいいのではなかろうかと思いますけれども、そこのあたりのやりくりを教えてください。","respondent":"原国保年金課長","answer":"今年は、この平成１８年１２月までやりますと、月４７人ということで、出生の数が若干減ったり増えたりということで、ここのところ増えてありますので、そういった背景の中で２４人の分を追加させていただいたということでご理解いただきたいと思います。","id":"exchange-008"},{"speaker":"大沢委員","kind":"意見","question":"２４名分の追加ということで、すみません、時間が短くなっちゃいましたけども、会計の処理の、あくまでも子どもが出生するというのは神のみぞ知ることなんですけれども、予算書にする場合に、常にこのような補正の計算を立てる場合に、プラス・マイナスすることがいいのかどうか、ちょっとご見解をください。","respondent":"日下部企画財政課長","answer":"当初予算以降のいろんな事情の変更もありますので、できるだけ最小限にこしたことはないんですが、必要なものについては増減計上すると、その辺はご理解いただきたいと思います。","id":"exchange-009"},{"speaker":"宮崎委員","kind":"質問","question":"私は５９ページの公共施設整備基金積立金の追加分と、これに関連して基金についてもちょっとお伺いしたいと思います。今時点で取り崩し可能な基金の額はどうなっているのか。それとあと、積立額のところの主な財源ですね。どういうふうなものが積み立てになってきているのかというところをまずお伺いしたいと思います。","respondent":"日下部企画財政課長","answer":"その財源でありますけれども、今回の９２億円の、確かに額が大きいことは事実でありますけれども、これにつきましては、基本的に年度末までの財源の見通しがはっきりいたしましたので、これに基づいて最終補正をさせていただいているわけでありますけれども。","id":"exchange-010"},{"speaker":"宮崎委員","kind":"質問","question":"その全体の増額が５６億円なんですけれども、積み立てが９２億円ということで、普通の家計から考えると、この積み立てる額が非常に大きいというのは、いわゆるやりくりがどういうふうにやるのかというところが非常に私もよくわからなくて、何回聞いてもよくわからないんですけれども、改めてやりくりの考え方、そして基金積み立てのあわせて公共施設整備だけじゃなくて、基金の積み立ての考え方といいますか。","respondent":"日下部企画財政課長","answer":"ただ、最終段階で、これは非常に単純なちょっと説明で申しわけないんですが、そういう形で予定をしてまいりますけれども、それだけでは必ずしも十分に基金の積み立てに回るとは限りません。","id":"exchange-011"},{"speaker":"宮崎委員","kind":"質問・要望","question":"それとあと、基金については、いろいろ出入りもあるんですが、大体このぐらいは置いておくんだとか、そういう目標額はあるんでしょうか。毎年これだけは積み立てるんだと、そういう目標額というのはあるのかどうか、教えていただきたいと思います。","respondent":"日下部企画財政課長","answer":"ですから、そういったことも含めまして、別に青天井ということではありませんが、当面する施設需要に対応していくためには、もうしばらくはできる限りの積み増しをしていかないと、なかなかこれに対応し切れないんではないか、このように考えてあります。","id":"exchange-012"},{"speaker":"宮崎委員","kind":"意見","question":"そういうやり方なのかなというふうに思うんですけれども、今の２０年間かけて、毎年四、五十億円かかっていくというお話なんですけども、そもそも区の財源を先行で使って進めていくと、そういう考え方というのをなぜとるのかなというのが私よくわからないんですけども、国あるいは東京都の予算化を待ってそういうものを進めていくということではなくて。","respondent":"日下部企画財政課長","answer":"起債につきましても、最大２割程度であります。起債は当然借金で返すものですから、そういった意味では、財源２５億円で１校を建て替える、そのうち１割ぐらいしか補助金というのは見込めません。それ以外のものは区が負担するわけです。","id":"exchange-013"},{"speaker":"宮崎委員","kind":"質問","question":"いろいろ負担軽減だとか、そういうところにもやっぱり財源の考え方というのがいっていいんじゃないかと思うんです。先ほどちょっと聞き忘れたんですが、基金の積み立てのところでは、区税、財調、いろいろな財源がありますというお話だったんですけど、今回の９２億円のところでいくと、おおよそどういう財源が何パーセントぐらいなのかというのが何かわかったら教えていただければと思うんですが。","respondent":"日下部企画財政課長","answer":"先ほど申し上げました９２億円に関しましては、基本的には一般財源が大半です。つまり、特定財源が増える、そうすると、その分一般財源の負担が減りますので、そういったいわば残余の余裕の出た一般財源を基金に積み立てると、それが基本的な考え方です。","id":"exchange-014"},{"speaker":"宮崎委員","kind":"提案","question":"特に今回も、私も一般質問でも、例えばお年寄りの医療費無料化なんかも区でもやれるんじゃないかと、そういう提案をさせていただいたんですけれども、ちょっと改めて伺いたいんですが、今回子どもたちの医療費無料化、中学校まで拡大になりましたけれども、そういうこっちのほうの財源と、例えばお年寄りのほうの医療費無料化とか、そういうところに考えようによっては回すのも可能、この基金は。","respondent":"日下部企画財政課長","answer":"単純な物の言い方をしますれば、一般財源で予算を計上するものについて、特段そういう一つの制約というものは具体的にはないと考えています。最後はやはり政策判断以外の何物でもないと考えております。","id":"exchange-015"},{"speaker":"宮崎委員","kind":"質問・要望","question":"もう一つ、やっぱり今の格差が広がっているというふうに言われておりますが、代表質問のところでもなかなか格差が広がっているという認識があまり聞かれなかったんですけども、やっぱり暮らしのところでは、非常に格差が広がっております。そういう立場で、今後の活用のところもいろいろ検討していただければということで、今日は要望させていただいて、終わりにいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"},{"speaker":"武内委員","kind":"質問・要望","question":"私は７ページの歳入、それから４７ページの安全・安心な学校づくり交付金、それから４８ページの小中学校改築事業特別交付金、それから６９ページの不妊治療相談・助成事業更正減額、８３ページの大間窪小学校用地取得減をお聞きしたいと思います。この辺の理由というか、傾向というか、この辺をまず教えていただきたいと思います。","respondent":"日下部企画財政課長","answer":"これにつきましては、先ほどもちょっとご説明を申し上げましたけれども、一つには再開発事業、やはり、これも主要５課題の関係で、平成１８年度の当初の段階では計上できませんでしたけれども、財調協議の最終段階で市街地再開発事業に対する補助金について。","id":"exchange-017"},{"speaker":"武内委員","kind":"質問","question":"そうすると、都の支出金のほうは、都市計画交付金に再開発事業が対象になって、これが大幅に増えてきたと、こういうことだと思うんですけれども、そうすると、再開発事業というのは、今までは都のほうからは支出されていなかったということで、それが支出されるようになったと、こういうことでよろしいでしょうか。","respondent":"日下部企画財政課長","answer":"結果からすれば、都市計画交付金の対象になるわけですから、その分２３区側にとっては財調全体の算定の一つのパイが広がるというような効果を見込めるというものです。","id":"exchange-018"},{"speaker":"武内委員","kind":"質問","question":"続きまして、４７ページの安全・安心な学校づくり交付金、これについてお伺いします。これは先ほど平成１８年度新設というご説明がありましたけれども、この辺の経緯、背景と、それから関連しますので、４８ページの小中学校改築事業特別交付金、これも先ほどの説明で過去の清算分２００億円のうちの品川の分がこれだという説明があったので、その辺のところをもう少し詳しく教えてください。","respondent":"市川庶務課長、日下部企画財政課長","answer":"具体的に申し上げますと、この事業の中で従来の校舎改築、それから耐震補強の工事、こういったものが事業の対象として見られるようになった、こういうものです。最後にどーんと平成１８年度分で約６００億円近くが来ることになりましたので、その相差の１５０億円に若干それにプラスアルファで２００億円、これを小中学校の改築の交付金として。","id":"exchange-019"},{"speaker":"武内委員","kind":"質問","question":"そうしますと、今後耐震補強、また耐震改修、また学校改築、それぞれ違うとは思うんですけども、国と東京都と、また区がそれぞれ予算を出し合う配分比率というのは今後どういうふうになっていくのか、教えていただけますか。","respondent":"日下部企画財政課長","answer":"今申し上げました特別交付金の２００億円というのは、あくまで一時金でございまして、今回１回限りです。ですから、東京都からこういう形での交付金は今後はおそらく来ることはないと思います。","id":"exchange-020"},{"speaker":"武内委員","kind":"質問","question":"そうしますと、今回補正で幼稚園、小学校、中学校それぞれありますけれども、あとどれぐらいでこの小中学校、幼稚園、例えば保育園とか、この辺のいわゆる教育施設とか、区有施設はどれぐらいの予定で終わるという予定になっているんでしょうか、教えていただければ。","respondent":"市川庶務課長、小林保育課長","answer":"これの設計を来年度、平成１９年度に行います。実質所要経費については、その実施設計を待って確定される、こういった今後の見通しです。最終的には平成１９年度、平成２０年度と品川保育園の建て替えを除きまして、それぞれ５園、７園、実施を予定しておりまして、合計２０園で、平成２０年度までにすべての耐震を完了する予定です。","id":"exchange-021"},{"speaker":"武内委員","kind":"質問","question":"わかりました。続きまして、６９ページ、先ほど大沢委員のほうからもちょっと質問がありましたんですが、私もこれをちょっと聞こうと思っていて、理由についてはわかったんですけど、そうしますと、平成１８年の当初予算では、２５０組ということで予算組みがされていたわけですけど、実際まだ３月途中でありますけども、何件ぐらい不妊治療の件数があったのか、実績を教えていただければと思います。","respondent":"谷田部健康課長","answer":"２月末での申請の受け付けですけれども、１６件の申請がございまして、助成額は約５０万円という状況です。","id":"exchange-022"},{"speaker":"武内委員","kind":"質問・要望","question":"そうしますと、２５０件の予算組み、東京都にあわせて検討して、それで、実際にはやっぱり１６件ということで、かなりまだ少なかったなという気はするんですけども、その辺はやっぱり理由としては、見込み違いということもあるんでしょうけれども、そのほかに何かもし理由があれば教えていただきたいと思います。","respondent":"谷田部健康課長","answer":"先ほど申し上げましたけども、件数につきましては、特定不妊治療にかかっている東京都の助成事業を受けている方、これは品川区民の方は大体６０件から７０件ありまして。","id":"exchange-023"},{"speaker":"武内委員","kind":"質問","question":"最後に、８３ページの大間窪小学校の用地取得についてですが、これが平成１８年度の当初予算ではたしか２３億円ほど計上されておりましたが、今回約１３億円ぐらいですか、減になっておるわけですけども、そうすると、大体１０億円で購入できたということで考えておけばよろしいんでしょうか。","respondent":"市川庶務課長","answer":"したがいまして、今年度当初におきまして、先ほど申し上げたような計算で出しました２３億円という額で計上いたしました。結果、２分の１の減額ということで、９億３,８００万円という購入価格で、その差額について今回補正をお願いする次第です。","id":"exchange-024"},{"speaker":"大西委員","kind":"質問・要望","question":"私は、まず４４ページ、こっちのほうで、先ほどの企画財政課長のほうの話の中で、温水プールというのがありましたけども、このことについてと、それとあと６０ページ、選挙費、それと区民施設費、その部分についてちょっとお尋ねをしたいと思います。","respondent":"富田生涯学習課長、野田口選挙管理委員会事務局長","answer":"学校温水プールにつきましては、現在は日野学園温水プールと戸越台中学校温水プール、２校です。それと、一般開放につきましては、本年５月から伊藤学園温水プールをオープンする予定でおります。給料の差です。更正した理由ですけれども、予算を編成した１０月１日時点では再任用職員が選挙管理委員会事務局の職員として１名いましたけども、４月１日正規職員に変わったために必要な額を更正したものです。","id":"exchange-025"},{"speaker":"大西委員","kind":"質問・要望","question":"それとあと、選挙費のことですけども、これは昨年区長選挙ならびに区議会議員選挙の補欠というのがありましたけども、これは４年ごとにこういう形で選挙が行われてくるという形になると、その部分の費用等も通常の自治体よりも統一地方選でなくなってくるので費用がかかってくるというふうに考えるわけですけれども、そういう部分は、当然品川区の税金がなくなっていく部分があろうかと思いますけど。","respondent":"日下部企画財政課長、野田口選挙管理委員会事務局長","answer":"例えば、荏原文化センターにも温水プールはあります。そういったことも含めまして、地域バランスに配慮した上でこれは考えていくべき、そういう性格のものだ、このように考えてあります。国政選挙とか都知事選挙というのは、それぞれ国で持つとか、都で負担するとかということになりますけれども、これについてはやむを得ないものというふうに理解しております。","id":"exchange-026"},{"speaker":"大西委員","kind":"質問・要望","question":"これは議員としても同じような形で、選挙をこのわずかな期間で２回もやらなきゃいけないというのは、資金的なものであったり、いろんな面で負担があるということなんかがありますので、これを解消するには、それではどういう働きかけをしていかなければならないかというのを品川区としても少し考えるべきで、よその自治体と協調しながら、何らかの圧力をどこかにかけていって改善を図っていけるものなのか。","respondent":"日下部企画財政課長、野田口選挙管理委員会事務局長、市川庶務課長","answer":"温水プールの関係でありますけれども、先ほどお答え申し上げましたが、この間地域バランスに配慮をして。それで、委員がお尋ねのように、半年ぐらい違うものについて、任期を統一しようとすると。そのほかはすべて解体工事の対象となりました。方角で申し上げますと、旧校舎の立会道路側の一部分です。","id":"exchange-027"},{"speaker":"大西委員","kind":"質問","question":"今選挙管理委員会事務局長の話の中で、私からすると、公職選挙法を変えないと、このこと自体はできないんじゃないかというふうに考えているんですけど、それと別個に今の考え方というのは、選挙管理委員会の考え方によって、このことを変えて、同一にできるという、その余地があるようにも少し感じたんですけど、その辺はどうでしょうか。","respondent":"野田口選挙管理委員会事務局長","answer":"選挙は任期満了の３０日前に地方選挙についてはやるべきだということで定まっております。ただ、その特例法として、４年に１回の統一地方選挙については、２月から５月までの満了については、統一するよと、これも法律で定まっております。","id":"exchange-028"},{"speaker":"大西委員","kind":"質問・要望","question":"それとともに、全国の自治体で同じようなケースも存在すると思うんですけども、そういう点からすると、選挙管理委員会と品川区、同じだと思いますが、同一歩調をとっていって、国に対して法制度の変換を迫っていく、法の変更というんですかね、時代に則した形で変えていく形で、品川区にとっては当事者であろうと思うので、そのような形を要望していって、それを実現すれば。","respondent":"野田口選挙管理委員会事務局長、蓼沼高齢福祉課長","answer":"法律で改正すれば、それは可能です。ただ、先ほども言いましたように、議員の資格、任期が４年なのが３年になるとか、あるいは５年にするとかしなければ、なかなか法改正ができないわけですね。今のところ、地域バランスを考慮しながら、例えば都南病院跡地であるとか、原小学校跡のようにケアホームを整備し、あわせてグループホームも整備していこうというふうに考えて。","id":"exchange-029"},{"speaker":"大西委員","kind":"質問","question":"今グループホームのことにつきましては、現在品川区で認知症ということにおいて、入所したいというニーズをとらえてのグループホームをどれぐらいつくっていかなきゃいけないのかという認識をされているのかどうか、ちょっと薄かったように感じるんですが、そのところをもう少し詳しく教えていただけますか。","respondent":"蓼沼高齢福祉課長","answer":"今現在そういった認知症高齢者の増加の状況を踏まえ、あるいは特養等施設を申し込まれている方の状態などを勘案しますと、これからやはり計画的に一定程度地域バランスを考慮して、計画を進めていくということで、今現在、まだ整備を進め始めたような段階ですので。","id":"exchange-030"},{"speaker":"大西委員","kind":"質問・要望","question":"要するに品川区内６カ所しかないわけですから。耐震をやっていく中で、子どもを預かる場合のですね、そのスペースの確保ということと、この耐震ということを一緒の形で考えていく余地はあるのかどうかをちょっと教えてください。","respondent":"蓼沼高齢福祉課長、小林保育課長","answer":"ニーズにつきましては、例えば小山のグループホームが今月オープンの予定ですけれども、１ユニット９人のところに申し込みをされた方が約３０人というような状況です。保育園は児童センターと併設しているため、一緒に耐震改修、大規模改修をやることもあります。こうした場合には、児童センターの関係等も含めまして、全体の施設計画として考えてまいりたいと思います。","id":"exchange-031"},{"speaker":"藤原委員","kind":"質問","question":"５９ページの生活安全推進事業更正減額の防犯拠点整備事業についてお伺いしますが、まず、ここで３６５万２,０００円の減額をしておりますが、その内容と減額した理由をお尋ねします。","respondent":"金子生活安全担当課長","answer":"内容と理由ですが、荏原町駅前の跡地に建設予定の荏原町安心安全ステーションのことです。東急電鉄と警察との協議に時間を要しております。年度内の着工が難しいと、このために補正予算を打ち切りまして、来年度予算に再計上いたしております。","id":"exchange-032"},{"speaker":"藤原委員","kind":"質問","question":"それで、今課長のご答弁の中に東急と警視庁といいますか、荏原署でまだ話し合いがついていないということですけれども、何で区民の安全を守るという最重要的な施策なのに時間がかかっているんでしょうか。その辺の協議の内容についてもう少し具体的な答弁をいただけますか。","respondent":"金子生活安全担当課長","answer":"これは安心安全ステーションの敷地等の調整のためのものです。双方言い分を持っての調整ですので、交渉のようなものです。したがいまして、交渉の経過というものにつきましては、相手にも言い分がありますので、先ほどの答えでご理解いただきたいと思います。","id":"exchange-033"},{"speaker":"藤原委員","kind":"質問・要望","question":"課長にそれでご理解してくださいと言われちゃうと、これから質問ができなくなっちゃうかもしれないんですけれども、相手の言い分というのは東急側の言い分だと思うんですけれども、私たちとしては、大前提である区民の安心安全という形でいろんな意味で推進しているわけですけれども、そろそろ交渉の解決を見ないといけないという思いがあるんですけれども、その中で、まず見通しについて。","respondent":"早津区民生活事業部次長","answer":"この安心安全ステーションですが、ちょっと説明が足りない部分がありまして、新しいステーションができるためには、ちょっと敷地の問題等があるので、今まだ協議中だということなんですが、４月１日からは、当初予定どおり安心安全ステーションは立ち上げます。","id":"exchange-034"},{"speaker":"藤原委員","kind":"質問","question":"今私が初めに質問した形になるのは、具体的にはいつごろになるんでしょうか。","respondent":"早津区民生活事業部次長","answer":"相手のあることではありますが、なるべく早目にやりたいと考えていますので、年度が明けましたら、速やかに着工できるようにこれから進めてまいりたいというふうに考えてあります。","id":"exchange-035"},{"speaker":"藤原委員","kind":"質問","question":"それで、金子生活安全担当課長が、警視庁から品川区に派遣といいますか、来てくださって、いわゆる現場という形でお仕事をしてくださって２年たちますが、警視庁だと都民の安全なんですけれども、もうちょっと細かく区民の安全ということで現場に接していただいたと思うんですけれども、その辺で警視庁にいて仕事をなさっていたときと、本当の身近な自治体に来てくださって、そこで仕事をしたときの違いとか。","respondent":"金子生活安全担当課長","answer":"これにつきましては、私の能力も不足していたと反省しておるんですけれども、もう少々時間をかけないとこの問題は解決できないなという点もあります。もし、警視庁のほうへ帰りましたら、警察側には、区に対する柔軟性、こういったものを持ちなさいよと言っていきたいと思います。","id":"exchange-036"},{"speaker":"山内委員","kind":"質問・要望","question":"よろしくお願いします。確認なんですが、観光アクションプラン推進事業追加分、これが３３３万５,０００円ついておりますが、すみません、４８ページに都の補助金で産業経済費の補助金の２番で、観光案内標識設置事業補助金が３３３万５,０００円、これは収入という形でありますけれども、これと同じものなのかということをまず最初に確認させていただきたいんですが。","respondent":"金子産業振興課長","answer":"観光アクションプラン推進事業のお尋ねですが、委員ご指摘のとおり、歳入のほうの分とこの分がイコール、つまり、東京都の１０分の１０の補助でこの歩行者用案内標識を設置したものです。","id":"exchange-037"},{"speaker":"山内委員","kind":"質問・要望","question":"先ほど企画財政課長のほうから観光案内標識設置事業補助金で天王洲の水辺に標識をつけるというご説明があったんですが、これはまずどういうものなのかというのをちょっと具体的に教えていただきたいんですけど。","respondent":"金子産業振興課長","answer":"東京都としては、天王洲地域で案内標識を設置したいということで、私どもに照会がありました。私どもとしましても、天王洲地域で少し距離を延ばせば、旧東海道まで含めた形で可能かということで、これについて検討を進めてまいりました。","id":"exchange-038"},{"speaker":"山内委員","kind":"質問・要望","question":"多くなってきたというか、品川区のほうでもアピールをして、観光客を呼び込もうではないかという形でいろいろとしていただいておりますけれども、例えば街角サインというものはどうかなというのがありまして、例えばほとんど観光に来ていただく方というのは、品川にゆかりのない方が結構多いかとは思うんですけれども、その人たちが、例えば五反田に来ました。","respondent":"中川原広報広聴課長、金子産業振興課長","answer":"観光客の方にまちの案内を、サインをというお話ですが、品川区の場合、戸籍住民課でつくっている住所案内と、それから都市計画のほうでまちを案内する駅ごとにつくるサインにそういった観点を取り込みまして、ご案内をしています。案内板につきましては、来年度平成１９年度の事業でこの観光客の皆様にどういうふうに案内したらいいか、それは例えば駅におりたときの広域な案内図から、街角の小さな案内図まで。","id":"exchange-039"},{"speaker":"山内委員","kind":"質問・要望","question":"時間もなくなってきてしまいましたので、続きまして、商業地リフレッシュ推進事業の更正減額について、ちょっとお尋ねをさせていただきたいんですが、約１,４００万円が減額になっているということなんですけれども、これはどういう、もともと事業がありまして、それで結局事業が行えなかったという考え方でよろしいのか。","respondent":"金子産業振興課長","answer":"このうち、今ご指摘の小規模保育ルームについては、昨年の１１月にオープンしたわけですけれども、もう一店舗の予定については、計画を実施できなかったということで、主としてこういうような要因から減額したものです。","id":"exchange-040"},{"speaker":"山内委員","kind":"質問・要望","question":"北品川だけではなく、ほかにも空き店舗対策ということで、商店で空き店舗のところをうまく活用していただいた形でこのような事業をどんどんやっていただきたいと思っているんですけれども、今後何店舗ぐらいの予定というか、そういう計画があるのかというのを最後に教えてください。","respondent":"金子産業振興課長","answer":"各商店街に対しては、空き店舗のあるところについて、さらににぎわいが損なわれないような形でさまざま考えて計画していただいて、それについては、私どもとしましては、積極的に支援していく考えです。","id":"exchange-041"},{"speaker":"井上委員","kind":"質問・要望","question":"私のほうからは、８２ページの学校施設建設費と７６ページの都市開発費、それから６８ページの保健衛生を伺いたいと思います。最初に、先ほど来、ほかの委員の方の質問でちょっと確認をさせていただきたいのがあるんですが、４８ページの都支出金の都補助金の教育費補助金があるんですが、この補正額については、これはどこの歳出のほうに回っているのかということを教えていただきたいと思います。","respondent":"日下部企画財政課長","answer":"東京都の補助金のうち、教育費補助金、先ほどちょっとご答弁申し上げました小中学校の改築事業の特別交付金でありますけれども、こちらは８２ページのほうの学校改築の経費、こちらの財源として充てているものです。","id":"exchange-042"},{"speaker":"井上委員","kind":"質問","question":"８２ページの学校施設、今のところになるんですけれども、まず大井第一地区小中一貫校のこの補正なんですけれども、どういう理由で、このような補正に至ったのかということを詳しく教えてください。","respondent":"市川庶務課長","answer":"本体工事につきましては、平成１７年７月から昨年１２月までの１７カ月で本体工事を予定してございました。ところが、この本体工事、幾つかの事情があります。","id":"exchange-043"},{"speaker":"井上委員","kind":"意見","question":"解体事業の状況でということですが、解体に対してどうしてそれが本工事に至らなかったのかということをご説明ください。","respondent":"市川庶務課長","answer":"解体工事の実施時に、特に近隣の方からさまざまな苦情、陳情をいただきまして、それの調整に大変時間を要しました。解体工事は済んだものの、いわばその余波が残っておりまして、本体工事の着工時にその辺の、近隣との特に調整を改めてせざるを得なかった、こういう事情です。","id":"exchange-044"},{"speaker":"井上委員","kind":"質問","question":"余波というのがちょっとよくわからないんですけど、その解体工事をするに当たって、解体物が校庭に埋められてしまっていたというようなうわさとか、本当に設計どおりに基礎部分を解体していなかったとか、何かよくわからないうわさがあって、その辺のところで、この保護者の方たちの説明にも工事と調査がおくれているというような説明で。","respondent":"宍戸施設担当課長","answer":"それらの１カ月ぐらいの着工早々のおくれの部分がその後取り戻せなかった、そのような事情で本体工事の完成がおくれたというものです。","id":"exchange-045"},{"speaker":"井上委員","kind":"質問","question":"近隣住民との関係で言いますと、解体業者から建築業者まで一貫して行われることが、非常にそういった意味では長丁場、近隣の住民の方との関係をつくっていかなければいけないということで必要だと思うんですけれども、この工事の場合には、解体業者と建築業者などは一体だったのか、それとも別の業者がされていたんでしょうか。","respondent":"宍戸施設担当課長","answer":"今回の場合、本体工事の契約議案等がございまして、着工の時期がどうしても８月になってしまうということがございまして、やむなく解体工事は別の発注にしたというものです。したがって、別の業者です。","id":"exchange-046"},{"speaker":"井上委員","kind":"質問","question":"こういった問題で一番不利益を受けるのは子どもたち、本来であれば１２月、新学期から引っ越しができるという状況だったはずなのに、１月末に引っ越しをせざるを得なかったというところで、子どもたちに影響が出てきているわけですが、そのことについて、今後はどのような対応を、契約よりも、子どもたちとか教育現場の環境を優先するのか、契約のほうを優先せざるを得ないのかというところでは。","respondent":"市川庶務課長","answer":"今後、いろいろ工事の規模等によってまだまだ検討すべきことはあろうかと思いますけれども、基本的な考え方としては、そのように臨んでいきたいというふうに思ってあります。","id":"exchange-047"},{"speaker":"井上委員","kind":"質問・要望","question":"それから次は、先ほど来出ていたんですが、大間窪小学校の学校用地取得についての更正減額ですが、大変大きい金額だなというふうに思いますけれども、当初予算の２３億円というものの裏打ちというか、先ほど庶務課長が路線価と係数を掛けてということでしたけれども、この計算に至っては、一般財源であるのかどうなのかということと。","respondent":"日下部企画財政課長","answer":"大間窪小学校につきましては、先ほど庶務課長のほうからご説明させていただいたとおりですけれども、財源としましては、これは基本的には学校の国有地の買収につきましては、起債が適用されますので、かなりの部分について起債の活用を図ってあります。","id":"exchange-048"},{"speaker":"井上委員","kind":"質問","question":"かなりの部分というのは、具体的にはどのぐらいというふうに理解したらよろしいんでしょうか。","respondent":"日下部企画財政課長","answer":"失礼いたしました。実際には９割、取得価格の９割です。","id":"exchange-049"},{"speaker":"井上委員","kind":"質問","question":"それで、結果的には９億円ぐらいで取得ができたということは、予算立てとして結果的に先がわからないという状況はあるにしても、この後、更正減額の１３億円というのは、公共施設の基金に入っているのか、どこに繰り入れられているのかということをちょっとお伺いしたいんですが、そこら辺は。","respondent":"日下部企画財政課長","answer":"いずれにしろ、そういったトータルの中で今回の約１３億円の減というのがあるわけでありますけれども、一応基本的には先ほども出てまいりましたけれども、基金への積み立ても含めて、そういう形で活用したということでご理解をいただきたいと思います。","id":"exchange-050"},{"speaker":"井上委員","kind":"質問","question":"すみません、ちょっと質問が違ったかな。１３億円というのは、使わなかったわけですから、どこかに収入として組み込まれていると思うんですけど、どこに入るんでしょうか。","respondent":"日下部企画財政課長","answer":"先ほど全体の９割が起債でということでありましたけれども、当初の段階でも、要するに９割ほど見込んでおりました。","id":"exchange-051"},{"speaker":"井上委員","kind":"質問","question":"ちょっと先ほどの基金のところで疑問があったので伺わせていただきました。次は、７６ページの都市再生総合整備事業更正減額についてですけれども、それぞれ理由を、小関橋はいいですから、大崎駅東口歩行者デッキから３項目の更正減額について説明してください。","respondent":"青木都市開発課長","answer":"西口デッキにつきましては、現在施工中ですけれども、これは駐輪場とあわせまして、出来高を年度ごとにチェックしている中で予定どおりの出来高が上がっていないということで減額更正したものです。","id":"exchange-052"},{"speaker":"井上委員","kind":"質問","question":"夕張市のことも含めて、そういう意味では、こういう資料提供の中で既にわかっているようなものの変更、都市開発の部分だけではないですけれども、結構都市開発の部分で言うとわかりやすく提示できるのかなというふうに思うんですけれども、そういった資料提供などはどんなふうにお考えなのかお伺いします。","respondent":"日下部企画財政課長","answer":"冒頭で、私のほうから全体の概括的なご説明をするということで審議をお願いしているところでありますので、その辺はご理解いただきたいと思います。それから、予算特別委員会の資料ということで今回も出しています。","id":"exchange-053"},{"speaker":"井上委員","kind":"質問・要望","question":"６８ページの保健衛生なんですけれども、先ほども質問で出ていました不妊治療相談・助成事業の更正減額で、更正とした理由が２５０組を当てにしたところが、１６件であったとか、そういったところは理解をしていますけれども、相談人数のほうでは、これは決算になってしまうかもしれませんが、補正で出ていますので、ちょっと伺いたいんですが、相談人数がどれくらいあったのかということと。","respondent":"谷田部健康課長、倉橋品川区保健所保健サービス課長","answer":"２点目のほうのご質問にお答えいたします。先ほど人工受精、それからその他検査治療、それぞれ分けて制度を設定いたしました。相談の人数ですが、１６名ということで、６回程度の回数で１６名、予約がそれ以上何例かございましたけれども、実質１６名ということで実施しております。","id":"exchange-054"},{"speaker":"原（雅）委員","kind":"質問・要望","question":"８３ページの大井地区小中一貫校の解体につきまして、先ほど質問が出ていましたので、関連をします。どういう形にしろ、解体あるいは新築工事がちゃんといっているか、いっていないかということは、周りの住民が見ていながら、よく知っていないというのが現状であったと思うんです。ですから、今後の中でも、それは十分気をつけていただきたいのと、更正減額の中の解体なんですが、今既に始まっています。","respondent":"宍戸施設担当課長、市川庶務課長","answer":"今委員ご指摘のとおり、工事工程の変更については、住民説明会等行っておりません。そういう意味では、周辺住民の方々へのご説明は不足していたと反省しております。３点目のただいま行ってあります第２期の解体工事と外構・校庭の整備ですけれども、特に４月の伊藤学園の開設当初と時期的に合致するということがありますので、学期初めの、特に新入生の対策を含めまして。","id":"exchange-055"},{"speaker":"原（雅）委員","kind":"質問・要望","question":"この工事そのものが今見ていますと、相当やっぱりある程度大がかりな形で解体が進められていますよね。それが前回のような形にならないように、やっぱり工程どおりに進むような、前のところと違ったところと契約されているんだろうと思うんですが、その辺の状況だけもう一度教えていただきたいと思います。","respondent":"市川庶務課長","answer":"本体工事の遅延から一連の経過を十分に承知しておる事業者ですので、そのことも含め、また特に今回の４月のぎりぎりの工期の設定というのがどういう意味を持っているか、先ほど私が申し上げた学校側の負担を極力軽減し、近隣への負担も軽減する方向で調整に努めてまいります。","id":"exchange-056"},{"speaker":"飯沼委員","kind":"確認","question":"耐震補強等の交付金については、午前中も質問がありましたので、ちょっと確認の意味で、この国庫補助金のところでは、３分の１ずつで、工事費は毎年これからも確保されるのかどうか、その点と、小中、あと幼稚園も含めて耐震診断は平成１８年度ですべて済んでいるのかどうか。補強工事、残っているところが、先ほど２０校かなと思うんですが、平成２０年度までに補強工事を行う。","respondent":"市川庶務課長、宍戸施設担当課長","answer":"今後の工事の耐震補強が必要となる学校の校数ですけれども、これについては、来年度、新年度の予算に関係する分が出てまいりますが、現状来年度の補強工事、小学校で６校、中学校で２校予定しています。耐震診断、児童施設ですが、平成１８年度ですべて耐震診断を終わっておりまして、平成１９年度、２０年度で工事はすべて終わる予定です。","id":"exchange-057"},{"speaker":"飯沼委員","kind":"質問・要望","question":"助成率がなかなか思わしくなくて、力を入れて何とか早く耐震工事を進めたいという国の思いがあるということがわかりましたけれども、昨年、文部科学省のところで公立学校施設の耐震改修状況調査結果というのを区町村レベルのところで発表して、そのときに品川区の耐震状況がすごくレベルが低いというのが載って、あと、品川区のホームページを見たらば。","respondent":"市川庶務課長","answer":"第２期、平成１５年度から耐震診断を実施した部分につきましては、これは文部科学省の基準としています０.７という基準値を用いて耐震補強を行って現在に至ってあります。","id":"exchange-058"},{"speaker":"飯沼委員","kind":"質問・要望","question":"だから、きっとどこかに予算が入ってはいると思うんですが、私は具体的にこれがどう行われたのかなというのをちょっと今日お伺いしたいなと思っていたので、例えばいつの時期に何年ぐらいかけて、だれがここを担当して調査をしたのかということと、耐震診断の１校の額とか、耐震工事の額とかが、今現在やられているのと比較して、どのぐらいの金額で行われていたのかというのが。","respondent":"市川庶務課長","answer":"第１期のときの耐震診断、これは平成８年度、９年度、２カ年にわたって実施をしています。このときの診断を担当いたしましたのは、区の技術系職員が診断を担当しています。","id":"exchange-059"},{"speaker":"飯沼委員","kind":"質問・要望","question":"学校は子どもたちの１日の結構長い時間を過ごす大切な場でもあるし、地域の防災拠点という面では、より本当に安全性が求められていくと思うわけなんですけれども、今、区の職員が図面を見て診断をしたということなんですけれども、この辺の調査をするに当たっての基準の設定というのは、品川独自のものだったんでしょうか。","respondent":"市川庶務課長","answer":"したがって、当時実施いたしました耐震補強工事については、一切国庫補助は受けてございませんし、それがわずか数年の違いとはいえども、平成１５年度から私どもが第２期として対応しているところの事情としては、大きく違っている。","id":"exchange-060"},{"speaker":"飯沼委員","kind":"質問・要望","question":"４９ページの改築事業特例交付金のところに移るんですが、冒頭に伺った、今までなかなか耐震補強が進まないというところにおいて、全面改修から建て替え方式に、国のところが改修方式に転換をしていったという話も聞いたことがあるんですけれども、この辺で、品川区はかなりここのところ、学校改築も進んでいるわけですけれども、耐震補強との関係で、改修にするのか改築にするのかという。","respondent":"市川庶務課長","answer":"一切その点では問題はないという認識を持ってあります。それと、２点目の耐震補強に当たって、補強なのか、建て替えなのかですけれども、これは補強工事のできる施設については、原則補強工事で対応する、こういう考え方を持ってあります。","id":"exchange-061"},{"speaker":"飯沼委員","kind":"質問・要望","question":"それが一つと、あと最後になったんですが、認証保育園の運営助成のところなんですけれども、利用者増による助成増というところなんですけれども、助成の基準のところなんですけれども、品川区内に住んでいらっしゃる方と区外に住んでいらっしゃる方の違いがあって、保育園が足りなくて、よそから来たり、よそに出たりという方が助成を受けられなくて運営が大変だという声を聞いているんですが。","respondent":"市川庶務課長、小林保育課長","answer":"今後の学校の改築、それから改修、これにつきましては、現在進めております耐震補強、これに喫緊の課題として取り組んですので、その次の段階で検討すべきもの、そういう認識です。そういった意味では、他区の方に対しては、補助金の交付外となっております。ただ、この認証保育所の制度の基本が、東京都で制度設計されたものですので、２３区ほぼ同様の対応、基本は同様になっております。","id":"exchange-062"},{"speaker":"飯沼委員","kind":"質問・要望","question":"品川区内の認証に入れなくて、お隣の区に出っ張ってしまった方がいらっしゃるので、そういう方にも助成を受けられるようにしていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-063"},{"speaker":"原（浩）委員","kind":"質問・要望","question":"午前中にお二方、午後またお二方、非常に耐震のことについて、この委員会、中心的に話が集中しておりますけど、実は私も耐震経費のことについてお伺いしたいと思います。それはページ数が４７および８１です。それからもう一点、目黒川右岸低地部の排水設備整備の関連についてお伺いしたいと思います。これが耐震の経費についてのご質問です。","respondent":"宍戸施設担当課長、原田下水道河川課長","answer":"横浜方式です。民間対象の方式かと思いますけれども、区有の施設の場合は、適切に民間に委託化しながら効率よく進めているということで、ちょっと横浜方式とは違うやり方でやっているかと思います。平成２１年度完成予定ですけど、これは完全に区のスケジュールで区が検討した結果、平成２１年度末完成予定ということにしております。","id":"exchange-064"},{"speaker":"若林委員","kind":"質問","question":"小関橋の架け替え工事の債務負担行為です。総務委員会に出されました案件の中でご説明がございまして、平成１７年９月に起きた都内の集中豪雨、これはたしか中野区、杉並区方面だったと思いますけども、これに関連をして要請があったです。そこで、もう少し詳しく、平成１７年９月の事例がどういうものか、また、なぜこれが目黒川においても適用されてしまうのかというところをお聞きしたいと思います。","respondent":"青木都市開発課長","answer":"平成１７年に契約されて以降、準備工等あるいは現場、仮設の橋をかけるという工事等進めてきたんでありますけれども、このたび、平成２０年、当初予定しておりました工期までには、どのみち完了できないということが明らかになりましたので。","id":"exchange-065"},{"speaker":"若林委員","kind":"質問・要望","question":"そうしますと、ここまでやってきた品川区の努力というものが、東京都に対しては、関係機関というのは東京都というふうにお聞きしましたけども、どのように理解をされて、その強い要望に対しては品川区として、区の立場からの事情説明、これは１カ年延びるわけですので、そこら辺のお話し合いの様子というのをお聞きしたいと思います。","respondent":"青木都市開発課長","answer":"私どもも強く当初の計画どおりにやりたいという協議は進めてまいりましたけれども、中野区や杉並区の被害状況を見ますと、やはり川に突起物があったような橋の部分などでの決壊等という報告がありましたので、そういったことを勘案しますと。","id":"exchange-066"},{"speaker":"若林委員","kind":"質問・要望","question":"はい、わかりました。債務負担行為によって１カ年延びるです。それで、今後は目黒川、さまざまな水とみどりのネットワーク構想等、公園等がまた整備をされていくわけですけれども、今回の東京都の指導が、今くいを打つというような表現もありましたけれども、今後の目黒川の再生について、どのような影響があるか、想像できるものがありましたらお教えいただきたい。","respondent":"青木都市開発課長","answer":"東京都の指導というのは、施工においての安全性確保というところに主眼が置かれておりますので、私ども今進めております目黒川周辺での整備、環境整備等については、何ら今後も支障があることはないと考えています。","id":"exchange-067"},{"speaker":"若林委員","kind":"質問","question":"船のことにまで言及していただいて、ありがとうあります。それから次に、財政全般の問題、昨年夕張市の財政破綻のニュースが飛び込んでまいりまして、自治体がまさか破綻をするということは想像もしていませんでしたので、大変に大きな、各自治体にとってはニュースだったわけだと思いますけれども、自治体が財政破綻をするということは、どういうふうに受けとめればよろしいんでしょうか。","respondent":"日下部企画財政課長","answer":"人口もたしか１２万人が１割ぐらいにまで激減してしまった。しかも、離職率が非常に高くなりましたから、生活保護の割合も高くなった、高齢化の割合も高くなった。そういう中で、税収が減って、行政需要が大幅に増えましたので、そこで借金に頼ろうとした。","id":"exchange-068"},{"speaker":"若林委員","kind":"質問","question":"大変ご丁寧な答弁、ありがとうあります。最終的には今ご説明があったようないわゆる予算の中であらわれてこない一時借入金というんでしょうか、そういうもの、これは議会もいわゆるチェックしようがなかったという記事も読ませていただきました。もう一重、品川区の今後の健全財政についてのご努力、取り組み、また議会への説明等ご説明いただければと思います。","respondent":"日下部企画財政課長","answer":"三位一体改革で、トータルでいけば２０億円ぐらいの減収という問題も出てきますし、今後少子高齢化に伴う財政需要の問題とか、いろいろ要因的にはそう楽観できない状況ではありますので、さらに一層今後とも行財政改革を徹底していく必要があると、このように考えております。","id":"exchange-069"},{"speaker":"木下委員","kind":"質問・要望","question":"こちらの差のある部分といいますと、現場の部分、民間企業で技術の継承ということで、定年後もそのまま継続して働いてもらって、若い方々の後進指導に当たってもらうという形で、その２００７年問題と言われている部分を乗り切ったりですとか、いろいろな採用状況だとか、いろいろな形でご努力されていると思いますけれども、区としてはその問題に対してどのような対策等。","respondent":"榎本人事課長","answer":"１点目の給与費のほうの関係ですけれども、冒頭に企画財政課長のほうから説明がありましたように、平成１８年度の当初予算の経費につきましては、平成１７年１０月１日の現員現給をもとに見積もりを立てているところです。","id":"exchange-070"},{"speaker":"木下委員","kind":"質問","question":"かしこまりました。続きまして、６６ページ、生活保護費の部分について、ちょっとお尋ねしたいと思います。そういう意味では、減の中身ですかと、原因ですとかをお教えいただければと考えています。それから、今後の生活保護の将来的な状況というか、品川区で、将来的にはどういう形で推移していくと見ていらっしゃるのか、そこら辺を、ちょっとお聞かせ願えますでしょうか。","respondent":"志村生活福祉課長","answer":"こうした関連で、今回、大きくこうした扶助費の減ということになってきております。これにつきましては、平成１８年度当初予算の策定に当たりまして、これからの増加が見込まれておりましたので、平成１７年度予算から扶助費を３％ほど伸ばしたものです。","id":"exchange-071"},{"speaker":"木下委員","kind":"質問・要望","question":"急に元気になるというのも、ちょっと考えられないんですけれども、そこら辺の原因というか、その中身、どのように考えていらっしゃるのか教えていただきたい。それから、先ほど、就業支援ということで、効果が上がったんじゃないかというお話をお伺いしましたけれども、どのような効果が上がっているのか、もうちょっと詳しく説明していただければありがたいと思います。","respondent":"志村生活福祉課長、青山品川区保健所長","answer":"１件１件個々に当たってはございませんけれども、私どもからしますと、かかっているお医者さんから退院ということになりますと、この後は居宅で受け入れということで、ケースワーカー等で対応しているものです。これは、精神障害者の方たちの社会的な自立支援という意味をも含めてなんですけれども、一方において、精神科病床を維持していくことが、病院にとっても難しくなっている現状もあります。","id":"exchange-072"},{"speaker":"木下委員","kind":"質問","question":"今、ちょっとご説明をお伺いして、要するに、経営が成り立たないので、そういう病床を閉鎖しているというようなことなのかなと。閉鎖というか、だんだん少なくされていらっしゃる。だから、入院されている方が減っている。逆に言ったら、悪いですけれども、追い出されているというふうな感じでも聞き取れたんです。時間がなくなっちゃったので、これで終了します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-073"},{"speaker":"伊藤委員","kind":"確認","question":"私は、８３ページの第一日野小学校基本設計更正減額について。それから、ページは全体にわたる話ですけれども、品川区事業の外部委託、指定管理等々、広い意味で、そのあり方について質問しようと思います。改めて、なぜ計画を見直ししたのかという背景を、確認してお伺いしたい。それから、今後の計画のスケジュールについてお聞かせください。お願いいたします。","respondent":"市川庶務課長、日下部企画財政課長","answer":"平成１８年度に、第一日野小学校の校舎改築の基本設計への着手を予定してございましたが、並行して、小学校の改築敷地となる。そうした中で、当初は、平成１８年度の段階で基本設計、それから実施設計ということで手順を踏んでまいりましたけれども、今。今後のスケジュールですけれども、来年度、平成１９年度に第一日野小学校の校舎改築、文化センターの改築、教育総合会館の改修。","id":"exchange-074"},{"speaker":"伊藤委員","kind":"確認","question":"品川区本体の行財政改革を進めるということは、もちろん結構なんですが、ただ結果として、こういう方々が品川区の仕事を一部負担しているわけですから、具体的に個々の事例を挙げると大変膨大になると思われますので、ざっくりとした部分で確認したいのが、そういう事務事業を外に出す場合には、関係する団体とどういう協議を行い、あわせて財政の手当。","respondent":"日下部企画財政課長","answer":"その辺については、個々のケースもありますけれども、今後、一つの大きな流れとして、地域との連携を進めていく上でいかにあるべきかと、その辺についても、今後の検討課題として受けとめていく必要があるのではないかと、このように考えております。","id":"exchange-075"},{"speaker":"伊藤委員","kind":"質問・要望","question":"ですから、これからの品川区の仕事を進めていくに当たっては、もし地域との連携を進めていくんであれば、いろいろな関係する団体に対しては、さらにその財源の調整、それから権限の移譲は難しいかもしれませんけれども、でも、大きく言えば、品川区の仕事の一端を担ってくださっているわけですから、責任は公務員と同時にどんどん重くなっていく可能性があるわけですから、やっぱりそういうことに対して。","respondent":"日下部企画財政課長","answer":"実は、これにつきましては、明日以降の平成１９年度予算の中でも、またご提案をする予定でございましたが、例えば、今ご指摘にありましたように、地域の団体に、いろいろ地域の環境整備ということでご協力をいただいております。","id":"exchange-076"},{"speaker":"伊藤委員","kind":"質問・要望","question":"これからは、ほかの考え方かもしれませんけれども、要望ですけれども、２００７年問題、団塊の世代の方々が入ってくる。当然、こういう方々のパワーも地域につなげていくことが大きな課題となっていくわけですから、入り口は非常に小さい話かもしれませんけれども、これは相当根が深い問題だと、私は思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-077"},{"speaker":"安藤委員","kind":"質問・要望","question":"私からは、８７ページの生涯学習施設費の図書館経費更正減額、職員給与費のところで、お尋ねしたいと思います。２,９９６万円余の減ということなんですけれども、まず、この中身を教えていただきたい。","respondent":"工藤品川図書館長","answer":"図書館経費更正減額の中身です。こちらのほうは、私ども、平成１７年度から平成１８年度にかけて定数減がございました。内容としましては、正規職員のマイナス２名、そして、再任用職員のマイナス２名、嘱託員のマイナス１名のトータルのいわゆる人件費分の減です。","id":"exchange-078"},{"speaker":"安藤委員","kind":"質問","question":"そういった定数減になった部分というのは、いわゆるその業務は、かわりに違うところに依頼になると思うんですけれども、それは区長の所信表明演説にもございましたけれども、図書館窓口の民間委託ということでよろしいんでしょうか。","respondent":"工藤品川図書館長","answer":"民間委託による減か、どうかというお尋ねです。私ども、民間業務委託は平成１６年４月からやっております。平成１６、１７年度という形で、業務委託による、いわゆる人員減というのをやっております。","id":"exchange-079"},{"speaker":"安藤委員","kind":"質問","question":"委託先の職員数というのは把握してございませんという答弁がよく返ってくるんですが、あわせまして、一般的な区内の図書館が開館して閉館まで何時間かあると思うんですが、その１日の業務内での職員の配置の数といいますか、一般的な区内の図書館で、正規の職員は何人で、非常勤は何人で、委託会社の窓口を担っている派遣社員は何人ぐらいで、平均的に一日の業務を回しているかというか。","respondent":"工藤品川図書館長","answer":"それぞれ、いわゆる現状に応じた配置をしているということで、１館当たり幾らという部分は持ってございませんけれども、品川図書館の正規職員数で言いますと、今、１０館あるわけですから、正規職員が７１名ということですから、１館当たりそれに応じた数を配置しているです。","id":"exchange-080"},{"speaker":"安藤委員","kind":"質問","question":"平成１６年度から窓口の受付業務を民間に委託を始めて、平成１７年度に全館に広げたということで、今年度、さらに広げるということなんですが、窓口業務をどうして民間委託させるのかという、その基本的な考え方をお伺いしたい。","respondent":"工藤品川図書館長","answer":"委託導入の目的ですけれども、さまざまな施策を推進するに当たりまして、効率的、効果的な執行体制を目指すということは、従来から区の方針だと考えております。","id":"exchange-081"},{"speaker":"安藤委員","kind":"質問","question":"そういったことであれば、やはり私は、ふさわしい均等待遇というんですか、そういう高度なサービスを提供している皆さんにも、きちとした待遇というのを保障してあげるべきだと思うんです。そういう方が、いわゆるワーキングプアの状態に置かれているということに対して、やはり区はきちんとした待遇を保障するべきだと思うんですけれども、この点に関しての認識はいかがでしょうか。","respondent":"榎本人事課長","answer":"これは、本会議でも答弁いたしましたように、民間企業が雇用条件等を決めるのは、契約によって決まっているものですから、区が実際に働いている人の賃金等を云々すべき問題ではないと、考えております。","id":"exchange-082"},{"speaker":"須貝委員","kind":"質問","question":"私は、５９ページ、公共施設整備基金積立金追加分と、８１ページの学校管理費についてお聞きしたいと思います。そのために、経常収支のほうが、今回、２５億円前後プラスになっていますが、９２億円は残ったわけですから、それをどうして一般会計のほうに、いわば経常収支がさらにプラスになりましたよと報告しないのか、その処理についてお聞かせください。","respondent":"日下部企画財政課長","answer":"９２億円の対応の仕方ということでありますけれども、私どもは、基本的にこういうふうに考えています。","id":"exchange-083"},{"speaker":"須貝委員","kind":"意見","question":"それをちょっと第１点。本来は、国とか都のほうでお金を出して、学校というのは改築を進めるべきものだと思います。私たち品川区のほうでは、本当に皆さんの財産を大切に使っていますよというような、目で見えるような意思表示を子どもたちにも、区民にも、そういうことを訴えるような態度、行動も必要じゃないかと思うんですが、その辺、ちょっとご見解をお聞かせください。","respondent":"日下部企画財政課長、市川庶務課長","answer":"先ほどの９２億円の話でありますけれども、ちょっと繰り返しになるかもしれませんけれども、逆に積立金として、つまり公共施設の整備基金という明確な目的がはっきりしているわけですから、そこに積み立てをすることによって。ただし、実際に、これまで改築の対象としてまいりました学校について見ますと、建築年次なり、あるいは棟の続き方なり、立地環境といったものを総合的に見て。","id":"exchange-084"},{"speaker":"須貝委員","kind":"質問・要望","question":"今、原則のほうはわかりました。ちょっと周りの自治体を見たら、どうでしょうかね。その辺を考えたときに、やっぱり、今、大変な自治体もあるわけですから、品川区としても、その辺はちょっと考えることが必要じゃないかなと思います。その中で、じゃあ、そのお金がどういうふうに流れたとか、そういうことまでは、果たして読み取れるものでしょうか。終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-085"},{"speaker":"本多委員","kind":"質問","question":"５９ページの退職手当追加分を聞いていきます。その後で、７１ページの職員給与費追加分。いろいろなページに載っているんですけれども、主に７１ページの環境清掃事業部あたりを中心に聞いていきます。初めに、５９ページの退職手当追加分。当初予算では１８億円に対して、補正額６億９,０００万円ということで、まず理由ですとか、人数ですとか、状況を教えてください。","respondent":"榎本人事課長","answer":"ということで、その追加分６億９,０００万円ということで、補正で組まさせていただいたものです。","id":"exchange-086"},{"speaker":"本多委員","kind":"質問・要望","question":"予定よりも５０人の追加ということなんですけれども、退職される方には、当然さまざまな理由があると思います。当然あいてしまったところを補うという部分で、組織力を挙げて努力されている点について、ちょっと教えていただきたいと思います。","respondent":"榎本人事課長","answer":"その対応としては、係長、係内主査等の異動の年次が重ならないようにするとか、所属課長との異動の年次が重ならないようにするとか、そういう人事異動での対応の中での適材の中でも、組織力を維持していこうという考え方に基づいております。","id":"exchange-087"},{"speaker":"本多委員","kind":"確認","question":"いろいろなケースがあって、本当にご苦労されたり、努力をされたりして、組織を挙げていろいろご苦労されているんだろうなと考えています。前倒しをすることによって、そういう手当ですとか、なければいいなと思っています。そういう視点から、以前は、５７歳までの勧奨退職がありましたけれども、今、もろもろの手当等、そういうものがないか、確認をさせてください。","respondent":"榎本人事課長","answer":"そういった意味でも、きちんと定年まで勤めていただくという前提のもとに、区の職員の活動を図っていくという考え方です。","id":"exchange-088"},{"speaker":"本多委員","kind":"質問・要望","question":"これからも、先ほども出ていましたけれども、行革での視点で、定数削減等をされていくんだと思います。２００７年問題等も出ておりましたけれども、これから新しい人材を採用していくに当たりまして、これからの人事考課の制度がどう変わるかはわかりませんけれども、基本的には、一般論としては、定年まで勤めるというか、その辺の考え方について教えていただきたいと思います。","respondent":"榎本人事課長","answer":"特に新規採用につきましては、今後、１００名を超える定年退職者がここ１０年間続きますので、同じ数ではありませんけれども、それに見合う、今までのレベルとは違うかなりの新規採用を考えなければならないときにきております。","id":"exchange-089"},{"speaker":"本多委員","kind":"質問","question":"その人事考課の制度は、これから時代とともに変わりつつあると思いますが、やはり住民本位ということで、勤め上げるといいますか、そういう方針といいますか、よろしくお願いしたいと思います。その中で一番目立ったのが、７１ページの環境清掃事業部の６,５９９万３,０００円の増と、７３ページのまちづくり事業部の２億６,６２３万９,０００円の減ということで、まずこの内容について教えてください。","respondent":"榎本人事課長","answer":"職員給与費が減した部分を、先ほどの退職手当の部分が補っていますので、昔で言う職員給与費の全体でいきますと、７,８００万円ほどの減という形になってあります。","id":"exchange-090"},{"speaker":"本多委員","kind":"質問","question":"一つだけ、ちょっと聞きますが、６１ページの地域センターの職員費が、ここでも減になっているんですけれども、この辺の理由といいますか、教えてください。","respondent":"田村地域活動課長","answer":"もう１点は、武蔵小山のサービスコーナー設置に当たりまして、研修という形で地域センターに配属しておりました。","id":"exchange-091"},{"speaker":"本多委員","kind":"確認","question":"当初予算のときに、先ほどの図書館ですとか、地域センターですとか、見積もりというか、もう少し読めなかったのかなと思って、ちょっと確認で聞かせていただきました。結構です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-092"},{"speaker":"山路委員","kind":"質問","question":"精神障害者施設の「たいむ」ですが、平成１７年度に区独自の事業としてスタートされ、昨年、三位一体改革の補助金がなくなる中で交付金として交付金化され、福祉施策の包括補助金としての、区の独自事業にこっちの補助金が入るようになって、地域にも受けいれていただきまして、非常に全国の先陣を切ったといいますか、地域と障害者の家族の方がうまくいって、スタートして約１年半ぐらい経ちますが。","respondent":"西島障害者福祉課長","answer":"当初は、区の独自の施設として開設をしたわけですけれども、東京都との交渉の中で、都が半分を補助金としての独自に拠出するということで、平成１８年度で言いますと、まだ確定はしてございませんが、生活支援センターの事業費が約２,１８０万円余ですが。","id":"exchange-093"},{"speaker":"山路委員","kind":"質問・要望","question":"まだ具体的には財政の見通しはついてないのでしょうか。そのまま都の包括補助金が充てられる可能性は高いんでしょうか。その辺を、もう少し掘り下げて聞かせていただきたいと思います。","respondent":"西島障害者福祉課長","answer":"本来ですと、自立支援法ということで、３障害、身体、知的、精神ということで、同一の枠組みになります。同一の枠組みになりますと、いわゆる精神障害者の生活支援センターは、地域生活支援事業の枠組みに入ってまいります。","id":"exchange-094"},{"speaker":"山路委員","kind":"質問・要望","question":"款別がちょっと違うところで聞きまして、申しわけございません。いわゆる地域における障害者の就労支援と、精神障害者の「たいむ」の拡充と、自立支援法によりまして、非常にいろいろな区民の方のご意見、ご要望聞いておりますと、まだまだ悩みは深いところがあるようですので、さらなるご努力で、充実と拡大をお願いして終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-095"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"１５４ページの介護保険会計についてお聞きしたいと思います。基金の繰入金が減額になっていますけれども、介護保険の第３期の計画では、基金を取り崩して保険料を安く設定するという計画になっていたかと思うんです。その計画に対して現状がどうなっているかということに対しても、お聞かせいただきたいと思います。","respondent":"蓼沼高齢福祉課長","answer":"現実に、平成１８年度につきましては、この補正予算にありますように、補正をして約４,４００万円の取崩し、平成１９年度については、これからご審議いただく予定ですけれども、１,１００万円ほど取崩しを予定しているという状況です。","id":"exchange-096"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"４,４００万円の、２年目が１,１００万円というと、５,５００万円ということですけれども、５億３,０００万円取り崩す中で、１年目と２年目で５,５００万円ということですと、３年目で残りの４億七、八千万円になるんでしょうか、それぐらいの額を取り崩すということになるのか。そのことを一つお聞かせいただきたい。この給付ができなくなったことによって、どれぐらい給付費が減額になったのか。","respondent":"蓼沼高齢福祉課長","answer":"軽度者への福祉用具の見直しの関係です。平成１８年度の当初予算と、平成１８年度末の実績の見込みから申し上げますと、約１億８,０００万円ぐらい、福祉用具に関しては給付が減しているという状況です。","id":"exchange-097"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"１％ですか、本当にわずかな額だと思うんですね。スリーモーターはこの方に必要ないというご答弁だったんですけれども、それであればワンモーターとか、ツーモーターとか、これだけの９５.５％の方がベッドを使わざるを得ないという状況の中で、改めて介護ベッドについて、このベッドが使えなくなった方の中に、必要な方がいると思われないか、どうか、その認識についてお聞かせいただきたいと思います。","respondent":"蓼沼高齢福祉課長","answer":"９５％の方の中にも必要な人がいるのではないかというご指摘ですけれども、それについては、はっきり何とも申し上げられないところですけれども、国のほうで示した基準が、実際に、昨年、各自治体のほうで調査をして、なかなか判断が難しくて。","id":"exchange-098"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"だって、やっぱり９５.５％の方がベッドを使わざるを得ないというこういう現実の中で、やっぱり必要な人がいるんだとは認識されないでしょうか。改めて、ご答弁いただけないでしょうか。","respondent":"蓼沼高齢福祉課長","answer":"必要ありや、なしやの判断は、なかなか難しいものがあると思います。ただ、これは介護保険の制度上、調査項目でその給付を認める。そういう取り扱いになっておりますで、それに従って、区としては、利用者にご理解をいただいてきたと考えております。","id":"exchange-099"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"実際は、もうどうにもならなくて、取り上げられたというのが利用者の思いで、その中には大きな不満になっている。国がこういうふうに出して初めて、国の言うとおりにするというのではなくて、やっぱり国に改善策を求めていく、実際に介護が必要な方のところの実態を一番よく把握している品川区が、その改善策を国に求めていくという姿勢こそ必要なんじゃないかと思うんですけれども、いかがでしょうか。","respondent":"蓼沼高齢福祉課長","answer":"利用者と接する身近な自治体として、というご指摘ですけれども、これにつきましては、２３区の場でもいろいろ論議もしました。都を通じて働きかけということも、課長会の中でも論議がありましたけれども、実際問題、なかなかその場では、国の基準を変えるような形での……。","id":"exchange-100"},{"speaker":"松澤委員","kind":"質問・要望","question":"短く３点聞きたいと思います。５２ページの不動産売払収入、７,４００万円のところ、補正が１億２,３７２万２,０００円、これの内容をお知らせいただきたいと思います。橋さえ完成すれば散歩はできるのかなと思うんですが、どの部分の工事が終わらないのか、あるいは、いつごろすべて完成するのかについて、お聞かせいただきたいと思います。","respondent":"中島経理課長、市川庶務課長、松代管理工事課長","answer":"１点目の不動産売払収入につきまして、ご説明申し上げます。補正前の７,４００万円から１億２,３７２万２,０００円の補正をしたものです。結果的には、国との交渉の中で５６万円の単価が、路線価の約１.３倍相当の４６万円に落ち着きまして。そういった関係から、今、工事が少し延びているところでございまして、一応、完成目標は平成１９年８月ぐらいを予定しています。","id":"exchange-101"},{"speaker":"松澤委員","kind":"質問・要望","question":"これが、１０年工事があるんだったら、まだ工事が始まらないかもしれないということはあるけれども、残り３年なんですから、もうせっぱ詰まっているところで、何でこれを本予算に載せられなかったのか、ここをお答えいただきたいと思います。１.６倍の計算が１.３倍だった。ところが、２分の１に減免になった、これはもともとわかるんじゃないですか、国有財産２分の１減免は。","respondent":"中島経理課長、市川庶務課長、松代管理工事課長、日下部企画財政課長","answer":"一方で、タコ公園の機能を少しでも生かしたいということで、道路の反対側に東京都の所有の用地があるんですけれども、そことの関係で。大間窪小学校の国有地購入の予算の立て方ですけれども、確かに、これまで、校舎改築に関連いたしまして、第二延山小学校、小山小学校。戸越公園の公園利用者の皆様へのお知らせですけれども、工事区域をフェンスで囲っていますところに、３カ所ほど。今、所管課長からもるるご説明させていただきました。","id":"exchange-102"},{"speaker":"西本委員","kind":"質問・要望","question":"７ページの歳入について、それから６５ページの子どもすこやか医療費、それから認証保育所運営助成、それから、保育園運営費、児童センター運営費の中のそれぞれの職員費について、８１ページの学校環境整備事業の中の、校舎等の整備について、質問いたします。入る前に、今の松澤委員の質問の中にタコ公園のお話があったんですが、これはちょっと要望にもなりますけれども、今、工事が始まっているんですね。","respondent":"松代管理工事課長","answer":"それのお知らせについての周知ですけれども、まさにこれから移設する予定になっておりますので、そういったことを、ちょっと東京都第二建設事務所と調整しまして、少しでもそこを通る方、利用される方にわかりやすくお知らせをしたいと考えております。","id":"exchange-103"},{"speaker":"西本委員","kind":"質問","question":"ぜひ、看板等々でわかりやすくお知らせをしていただくように、よろしくお願いいたします。その件については、さまざま委員のほうからも質問がありましたけれども、都は財調の関係もありますので、予算当初は不明瞭なところもあったので、増えるという最低限のところで予算化をしたとおっしゃったと思うんですけれども、その予算の立て方、それから、補正の考え方、今後、どういうような形でつくっていくのか。","respondent":"日下部企画財政課長","answer":"ただ、今後とも、できる限り当初予算の編成段階で、１年間をしっかり見通す形で、歳入、歳出ともに計上できるような努力は、引き続きしてまいりたいと考えております。","id":"exchange-104"},{"speaker":"西本委員","kind":"質問・要望","question":"そのずれの考え方、それから、病院側、薬局との支払いはどうなっているのか。それから、保険の種類によって、その場での精算という形ではなくて、後で品川区のほうに申請を出して助成を受けるという形の方も何人かいらっしゃいますけれども、その方たちが、自分の意思なんでしょうけれども、どれだけきちんと助成されているか、そこら辺の状況把握はどのように考えられているでしょうか。","respondent":"諸岡児童課長","answer":"子どもすこやか医療費助成制度についてですけれども、この請求、支払い関係ですが、受診をされますと、医療機関のほうで、レセプトを国保連合会のほうに送られてまいりまして、国保連合会のほうが審査、支払い機関ということで、医療機関のほうに料金を払う。","id":"exchange-105"},{"speaker":"西本委員","kind":"確認","question":"その内容はよくわかっているんですが、病院側とか、薬局の回収はきちんとできているのか。品川区の助成が現場の病院とか、薬局のほうに行っているのかどうかの確認は、区としては把握をしているのか。それは、自己責任下においてやっていただくというような考え方なのかを、お聞きしたいと思います。","respondent":"諸岡児童課長","answer":"東京都外でかかられた場合は、患者が医療証をお持ちになっていらっしゃいますので、それにその場合の手続方法が書かれていますし、そのほかのさまざまな区のお知らせ等によって、そういった場合には、区の児童課の窓口のほうで現金を払い戻しといいますか。","id":"exchange-106"},{"speaker":"西本委員","kind":"質問・要望","question":"医療費のほう、私たち区民側としては非常にありがたい制度でありますけれども、それを負担というか、やり取りをしているところも、きちんと流れの中で入っているかどうかというのは、医師会等々を通して、現場サイドで確認をしていただけないかなと思います。それから、都外の保険の関係は後での精算の形なんですけれども、これは自己管理になりますので、大体周知徹底はしているはずなんですね。","respondent":"小林保育課長","answer":"新規に開設いたしますときに、その内装も含めた設備費、開設準備経費につきましても、都と区と２分の１ずつ、最高２,０００万円までの補助というふうになっています。","id":"exchange-107"},{"speaker":"西本委員","kind":"質問","question":"区のほうも２分の１、運営費として助成しているということですが、非常に入りにくい状況なんですね。認証保育所も定員がいっぱいになってしまう。区外の方も入って来られるというところでは、優先順位というのは、いいのかどうかというところがありますが、なるべく区内の希望されている親御さんの利用を促すような形ではできないのかなと思っているんですが、いかがでしょうか。","respondent":"小林保育課長","answer":"認証保育所は、都市型の保育需要に対応するということで、特に駅周辺に立地することが多うあります。","id":"exchange-108"},{"speaker":"西本委員","kind":"質問","question":"認証保育所は、これからもますます建設されるんじゃないかと思っています。なかなか認可保育園に入りにくいという方がいらっしゃいますので、有効的に、いい関係で利用できるようになればいいかなと思っています。今後、どういうふうになっていって、この減額というのは、今後どういう形になるのか。ますます減額という形になっていくのか、動向を、どういうふうに考えていらっしゃいますでしょうか。","respondent":"小林保育課長、諸岡児童課長","answer":"ただ、職員構成上は、基本的に、例えば平成１７年度と比べて、平成１８年度は人員が減って、それを非常勤に置きかえたとかといったことではなくて、給与財源の構成上の差が生じたものと考えております。児童センター運営費の更正減額ですが、これは平成１７年１０月１日の現員で、９７名という予算を計上しておりましたが、実質的に、その後、普通退職者、あるいは人事異動ですまいるスクールのほうへ異動したりという者が６名おりまして。","id":"exchange-109"},{"speaker":"西本委員","kind":"質問","question":"保育園のほうとしては、いろいろ制度上の関係だということで、今後、同様の考え方でやっていくということだったと思います。児童センターについてですが、今、民間のほう、委託という形で入っていられると思うんですが、これが今後やはり増えていくということになると、職員費ということについては下がっていくと考えてよろいしんでしょうか。","respondent":"諸岡児童課長","answer":"今後、児童センター、新たに再編をいたしまして、５地区、１３ブロック、地域にシフトした体制で、児童問題を中心に、子ども家庭あんしんネット協議会の事務局を担ったり、虐待防止機能も果たしていくということがありますので、今後につきましては、職員の配置等。","id":"exchange-110"},{"speaker":"西本委員","kind":"質問","question":"いろいろな人材を考えていくということですが、今日は質問いたしませんけれども、質の担保というところもありますので、これはまた款別のところで質問していきたいと思っています。次に、学級環境整備事業、この中の校舎等整備の中には、例えば体育館とか、校舎とかの設備も関係しているという形でよろしいですか。どういう内容のものが入っているんでしょうか。","respondent":"市川庶務課長","answer":"あるいは、プールの塗装、防火区画の整備、こういったものも含んでおります。それらも一連を含めて校舎等整備ということで対応しております。","id":"exchange-111"},{"speaker":"西本委員","kind":"質問","question":"これは、最近経験したことなんですが、体育館の設備がちょっと壊れている。それを改修してほしいので、１月ぐらいに聞きましたら、年度内では予算がもうないと。来年度に早急に直しますという返事をいただいたんです。しかも、やはり体育館等々について、校舎内もそうですが、安全性を考えると、すぐに改修するべきではないのかというふうに思うんですが、その考え方はいかがなものなんでしょうか。","respondent":"市川庶務課長","answer":"その一方、施設はやはり生き物ですから、随時対応しなくちゃいけないというケースもあるということは承知しております。こういった一連の工事ニーズに対しまして、１年間の予算額の中でどう対応していくか、これが一つあります。","id":"exchange-112"},{"speaker":"土井委員","kind":"質問・要望","question":"５７ページのりんかい線にかかわること、さらに５９ページの公共施設整備基金積立金追加分等に関すること、それから、６５ページの在宅介護支援センター運営費の予算財源構成に関すること、とりあえずこれを中心にお伺いして、さらに加えて、一定の補正とは何ぞやというところを、ちょっと聞かせていただきたいと思っています。そこら辺をどう考えたらいいのかということなんです。","respondent":"日下部企画財政課長、蓼沼高齢福祉課長","answer":"公共施設整備基金の積立でありますけれども、これの執行の時期は、これからいろいろな財源の問題が、最終補正でご議決をいただいた後、整理をしてまいりまして、５月末の出納整理期間中に、これを執行するというものです。ということで、当初予算を計上する時点では、この交付金の見込みがはっきりしなかったために補正で組んだものでございまして、これは、今回限りの措置です。","id":"exchange-113"},{"speaker":"土井委員","kind":"質問","question":"大変よくわかりました。そもそも論というのは、先ほどお話をしたんですけれども、きょう、伺っておりましても、補正予算はなるべくないほうがいいんだと、できればやらないほうがいいというお話ですよね。１１月の第３回定例会とか、第２回定例会ですと、そこから新しい事業が始まるかもしれないということなので、ちょっとその辺のそもそもの考え方と、そもそもについてお伺いをしたいと思います。","respondent":"日下部企画財政課長","answer":"最終補正でいろいろ組み立て直しをしたものが、翌年度の予算にも、明日以降は平成１９年度の新年度予算でご審議をいただきますけれども、そういう一つの年度間のつなぎの役割も担っていると考えておりますので、そういう意味では、できる限り最大限、歳入。","id":"exchange-114"},{"speaker":"土井委員","kind":"確認","question":"大変ありがとうあります。だから、その審議をこの場で、予算特別委員会でやれば、別に同じことじゃないかなという感じがするので、ちょっと聞いてみたんですけれども、もう一度、その意味では、先ほど言った国庫支出金だとか、都の支出金だとか、そういう歳入面は、少なくともここで確認しなきゃならないことなんですね。","respondent":"日下部企画財政課長","answer":"基本的には、歳出については、執行額の限度を決めるというものでありますけれども、いずれにしましても、それの一つの財源的な裏付けをはっきりしないことには、事業の性格自体もなかなかご理解いただけない面もあろうかと思いますし、そういうことも含めまして、それはそれで。","id":"exchange-115"},{"speaker":"土井委員","kind":"質問","question":"でも締めだけは、平成１８年度の３月１、２、３、４ぐらいまであるという形で締めていくわけですよね。まあ、いいです。というのは、真剣に、まさしく１円も間違いのないようにこういうものをつくらなきゃいけないわけですから、大変だなと思うので、できるだけ簡素にならないのかなと思って聞かせていただきました。すぐにどうなるというものでもなさそうなので、これをもって終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-116"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"これは大井ふ頭の青空野球場の交換をする分、６,０００m2と、新規購入１,５００m2だと思ったんですが、その分が、現区長が東京都と折衝の結果で、これが品川区が使えるようになったと思うんですが、この整備の中で、前にも出ていたと思うんですが、一応、確認として、どのぐらいのグラウンドができ上がってくるのか。その辺から、教えていただきたいと思います。","respondent":"松代管理工事課長","answer":"ここをご利用いただく際には、基本的に公共交通機関、一番近いところは天王洲アイル駅、歩いて五、六分ですけれども、そちらをご利用いただければと思うんですが、そうはいいましても、道具等をお運びになりますので、駐車場として、１９台から２０台、何とか設置できればなと。","id":"exchange-117"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"あそこは、現状、緑も多い公園になっていると思うんですね。駐車場、１９台、２０台という台数があれば、一番混んだときでも、あそこは１面でしょうから間に合うと思うんですが、やはりあの周りの道路に置かれてしまうと、あそこもかなり危ない。それとも、まだ全然検討してないのか。ですから、利用者の要望をまだ調べていないのか、それとも、現状どうなっているのか、先に。","respondent":"松代管理工事課長","answer":"それ以外は残念ながら伐採という形をとっております。八潮北野球場ですが、こちらは、現在、土系の野球場としてご利用いただいております。人工芝等の計画は、現在のところは考えてございません。","id":"exchange-118"},{"speaker":"鈴木（真）委員","kind":"確認","question":"私も、今言ったように、人工芝系にしてほしくないと思うんですけれども、これからの利用状況とか、グラウンドが、青空３面のところが１面になってしまうということを考えると、今後、検討の材料になってしまうのかなとも思いますが、その際は、よく現在の利用者の状況も確認していただいた上で、区のほうで考えていってもらいたいと思います。それから、キャンプ場もまだ使っていると思うんです。","respondent":"藤田道路公園課長","answer":"青空野球場ですが、２月１日から、入口が変更になってあります。現在、従来の入口がトレーラー等の入口がなっておりますので、その辺の安全性を高めるために、別な入口を設け、そこからご利用いただくという形になっております。","id":"exchange-119"},{"speaker":"鈴木（真）委員","kind":"意見","question":"それからもう１点のほうに移ります。防災対策費の中で、地域防災アドバイザー育成事業に対する都支出金交付に伴い、同額一般財源を更正減額ということで、これが、先ほど、都補助金の中で、民生費補助金の福祉施策包括補助金２４７万８,０００円、これでいいんですよね、財源が変わったということで。","respondent":"久保田防災課長","answer":"今回、地域防災アドバイザーの育成事業費に関する財源更正なんですけれども、東京都のほうの東京都福祉改革推進事業の中に、先駆的事業として、新たな課題に取り組む試行的事業ということで採択されまして、先ほど出ました４９ページにある２４７万８,０００円、全額なんですが。","id":"exchange-120"},{"speaker":"鈴木（真）委員","kind":"質問","question":"財源が都の補助金に移ったということで、それは新しい施策でいいなと思うんですが、何で福祉施策なのかなというのが、まず一つ引っかかったんです。その中で、高齢者の支援ということからこれに入っているのかなという思いもあったんです。この補助が、また来年以降も同じように続いてきて、新たにまたこれからもアドバイザーの育成を進めていくのかどうか、そこら辺の考え方を教えてください。","respondent":"久保田防災課長","answer":"防災アドバイザーなんですけれども、現在、災害事業援護者対策として、区内全域で、避難誘導のワークショップ等をやっておりますけれども、大きく言うと、やはり要援護者対策として取り上げているということについて。","id":"exchange-121"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"先駆的事業で、いい事業でしたら、補助金がなくても、区の一般財源でもやっていくべき話だと思いますので、ぜひ活用していっていただきたいと思います。最近、ちょっとお聞きしたんですが、ある警察署の中で、ビデオまでつくって、シミュレーションを実施したということを聞いたんです。それは、地域の町会長たちが警察に呼ばれて、見せてもらったという話を聞いています。","respondent":"久保田防災課長","answer":"そういう点でいけば、新しく変わったということについても、大きな混乱はないんじゃないかなと認識しております。","id":"exchange-122","title":"町会・自治会支援"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"最後に、警察のシミュレーションと区の指示が全然別になってしまうようなことがないように、一環した体制。だれかこれから防災のリーダーになっていくべき人が、違う形になってしまうと困るなと思いますので、その辺もよく検討していっていただきたいと思います。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-123"},{"speaker":"堺委員","kind":"質問・要望","question":"今回、補正予算で９２億８,８０４万４,０００円計上されているわけですけれども、これの中身、内容というんでしょうか、これについて確認をしておきたいと思います。これが１点目です。この改良に当たっては、一度、地元でも説明会がされているわけですが、そのときにおそらく出た要望だろうと思うんですが、その辺の具体的な要望の内容について、確認の意味で教えていただけましょうか。","respondent":"日下部企画財政課長、浜脇街路事業担当課長、松代管理工事課長","answer":"ほぼこの半額は、これも先ほど来ご答弁申し上げておりますように、国文学研究資料館跡地の取得、来年予定しておりますので。補助１６３号線の補正の理由ですけれども、当初予算は１７億８,０００万円ということでしたが、これには。戸越公園避難通路整備に関する要望の内容というご質問です。昨年８月に説明会等をしまして、その際、また地域の町会等からの要望ということでございました。","id":"exchange-124"},{"speaker":"堺委員","kind":"質問・要望","question":"もう１点は、移転をするに当たっては、区は用地を取得するということも、当時から意思表示は明確にしておりましたから、場合によっては、取得する時期が来たら買えるようにという意味で、今回、補正予算で積み立てるのではなくて、例えば５年計画で積み立てていくとかという形もあったのではないかなと、こういう気がしましたけれども、この辺の考え方だけを、ちょっと確認しておきたいなと思いまして。","respondent":"堀越行財政改革担当課長、浜脇街路事業担当課長、松代管理工事課長","answer":"建物については、今後、どういった形で利用するのが一番有利な形になるのか等を含めまして、整備方針を定める中で検討をしていくという予定です。１６３号線の関係ですけれども、あと残り約２年ですので、その工期内に、事業期間内に終わるように、今後とも努力してまいります。内容の具体的なものですけれども、バリアフリーということで、車いすもゆっくりと入れる勾配５％以下ぐらいになるように、今回、整備を変更いたしました。","id":"exchange-125"},{"speaker":"菊地委員","kind":"質問","question":"７９ページの大井町周辺の地区再開発事業、それとあわせまして、７２ページの中小企業対策に関連して、お聞きをしてまいりたいと思います。更正減額されているところ、西地区かと思いますけれども、その内容について、ちょっとお聞かせを願いたいということ。それから、これからの展望なんかについても、ちょっとお聞かせ願いたいと思います。","respondent":"青木都市開発課長","answer":"７９ページ、ご質問の大井町駅周辺地区再開発事業の更正減額ですけれども、今現在、私どものほうで、平成１８年度歳出で予定しておりました大井町西地区というところで再開発準備組合が結成されておりまして、そこが本年度中に組合設立して、法的な団体になった後に。","id":"exchange-126"},{"speaker":"菊地委員","kind":"意見","question":"今、最後に言われたにぎわいというところで、実際に今のこういう商店街の状況なんかを見ないで形成をしていけるのか、そういう展望があるのかというところを、ちょっとお聞かせを願います。","respondent":"青木都市開発課長","answer":"ですので、今後進めていく開発の中では、地元の商店街のにぎわいを阻害しないような、むしろ共存できるような、お客様を呼べるような施設の導入というようなことを検討しながら、まちづくりを進めていきたいと、区としては考えております。","id":"exchange-127"},{"speaker":"菊地委員","kind":"意見","question":"ここに、２０年も前に区の区民部商工課というところが、当時の名前みたいですが、行った近隣の商店街の調査表があるんです。この項目の中で、「再開発や地区計画を進めて、核となる大型店を誘致して、そのよさと、近隣商店街のよさをあわせ持つまちなみが、来訪者に支持をされる。この辺では、いかがでしょうね。開発というよりも、商業という目線で見たときに、どうなのかを、ちょっとお知らせください。","respondent":"金子産業振興課長","answer":"特に、私どもも商店街連合会とも意見交換をしておりますが、大型店との対決等々というようなことについては考えていなくて、大型店とどう連携していくかということが、今後の商店街の一つのあり方だろうということで、私どもも、今年度、あるいは来年度においても。","id":"exchange-128"},{"speaker":"菊地委員","kind":"質問","question":"大きく発展と言いますけれども、それは非常に異論のあるところですよね。要は、開発を進めて、大型店を誘致をしてくる、そういう形式そのものが、こういう都心部でも崩れつつあるんだということなんじゃないですか。地区計画、開発を進めるということでまちづくりが進む、こういう考え方が、そもそも崩れてきているんだということが言えるんじゃないでしょうか。その辺をお願いします。","respondent":"岩田まちづくり事業部次長","answer":"駅前整備については、ある一定程度成果が出ております。ただ、大井町全体におきましては、Ｅ地区、Ｂ地区、それから問題のＣ地区といったところがまだ手つかずの状態で残っておりますので、いわゆるまだ発展途上の地域であるというに認識です。","id":"exchange-129"},{"speaker":"菊地委員","kind":"質問・要望","question":"そこをもう少し明確にしてほしいんですよ。さっき言った、どこの商店街を見たって、やっぱり厳しい状況にあって、後継者をつくっても、それでは後継者にきちんとした営業をさせられないということで、皆さん廃業されるという実態があるわけですから、ここをもう少しきっちりと見たご答弁をいただきたいんです。","respondent":"金子産業振興課長","answer":"であるからして、平成元年のころのそういう判断、ないし出店というものが間違いだったかどうかというのは、私は、それについて評価できる立場にはないので、私どもとしましては、丸井が営業を終了するという話をお聞きしていますので、なおかつ、その後。","id":"exchange-130"},{"speaker":"菊地委員","kind":"意見","question":"今の話というのは、丸井の撤退は自分たちの責任ではないと、全く関係ないんだと、それは好き勝手という形ですよね。再開発ビルの中で営業をしてきた、いわゆる核店舗なわけでしょ。そこに対する責任というのを、もっと明確にしてくださいよ。最後。","respondent":"山田区民生活事業部長","answer":"これは全国展開の中で、ご自分の経営的な判断ということで、私どもは認識をしております。その後も責任を持って、今の条件のまま新たな企業と話し合いをしているです。","id":"exchange-131","title":"町会・自治会支援"},{"speaker":"石田委員","kind":"確認","question":"品川区というか、特別区側は、東京都がそういうふうに思っていると思っているのか、どうか、それを確認したいと思います。そうなってくると、今度、都との協議の中で、必ず特別区が水平調整を行うので、特別区の決定に文句を言うなと、その協議の中で、都はそれをすべて黙って承認しろということの話し合いというのはできるのか、できないのか、そこら辺の確認をお願いします。","respondent":"日下部企画財政課長","answer":"もともとこれは８月の当初算定の時点と、ここへきての最終実績との見込みの違いではありますけれども、いずれにしろ、この間、２３区が以前からずっと東京都に対して、これはもともと区にとって非常に貴重な財源でもありますので。","id":"exchange-132"},{"speaker":"石田委員","kind":"質問","question":"そういうふうにおっしゃるだろうなと思ったんですけれども、質問になかなかお答えしてくれてないと思うんですけれども、でも、企画財政課長の答弁では、それ以上言えないんだろうなと思うんですけれども、先ほど、今話があって、区長からも、本会議で強くお話があったと思いますが、改めて伺います。じゃあ、地方分権を進める意味からも、基礎的自治体として、今後、都区の財政調整の問題も残っている。","respondent":"濱野区長","answer":"どれだけ特別区が自主的な水平調整をできるかというのは、正直申し上げて、かなり難しい問題だろうと考えています。ただ、難しいだろうから、水平調整の試みもしないでそのままにしておくというわけにはいかないと思っています。","id":"exchange-133"},{"speaker":"石田委員","kind":"提案","question":"それで、がんがん品川区から提案をしてやっていく。この問題は、区長と行政側と議会も一体となって取り組まなくちゃならないと思うから、それをもし品川区から提案してやっていったとしたら、区長としては、これはちょっと目立ちすぎて、区長会でも立場がなくなるからありがた迷惑と思うのか、ぜひ提案をしてがんがんやってほしいと思うのか、これもあわせて教えてください。","respondent":"濱野区長","answer":"そしてまた、議会についても、２３の議会がこぞって動き出すことが一番望ましいわけで、品川区だけが動いていると、ちょっと逆に何かやりづらいこともあろうかと思います。といいますのは、５２％から５５％にすることについては、２３区だれも異論はありません。","id":"exchange-134"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/562921?Template=document&Id=874#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=3&TermStart=2007-01-01&TermEnd=2007-12-31"}],"sourceMeta":{"pages":0,"characters":122157,"voices":329}}]);
